INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C1','kor',6,2,'u6',1,'경험을 글로 표현하면 좋은 점 — 그때 내 마음이 어땠는지 또렷하게 알게 되고, 말로는 잘 안 되던 것을 다른 사람에게 생생하게 전하며, 지나가 버릴 일이 오래 남는다 (글씨를 예쁘게 쓰거나 글을 길게 늘리는 것은 좋은 점이 아니다)',ARRAY['6국05 문학(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C2','kor',6,2,'u6',1,'날마다 겪는 작은 일도 글감 — 여행이나 대단한 일이 없어도 우유갑을 여느라 씨름한 일처럼 마음이 움직인 일이면 무엇이든 글감이 되며, 글감을 고르는 물음은 「그때 내 마음이 움직였는가」 하나다',ARRAY['6국05 문학(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C3','kor',6,2,'u6',1,'좋은 표현은 개수가 아니라 알맞음 — 빗댄 표현을 많이 넣거나 어려운 말을 쓸수록 좋은 시가 되는 것이 아니라 그 마음에 알맞은 표현이 좋은 표현이며, 빗댄 표현이 하나뿐이거나 하나도 없는 짧고 쉬운 시도 마음이 잘 전해지면 좋은 시다',ARRAY['6국05 문학(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C4','kor',6,2,'u6',1,'이야기의 세 요소 — 인물(이야기에 나오는 사람이나 대상)·배경(일이 일어난 때와 곳)·사건(이야기 속에서 일어난 일)이 모여 이야기가 되며, 셋은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직인다',ARRAY['6국05 문학(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C5','kor',6,2,'u6',2,'시가 담은 경험과 장면 떠올리기 — 말하는 이가 실제로 한 일을 찾아 시가 어떤 경험을 담았는지 알고, 장면을 머릿속에 그리며 읽으며, 빗댄 말(벌써 백 번은 미끄러졌다)은 실제로 일어난 일이 아니라 말하는 이의 마음(놓칠까 걱정함)을 나타낸 것으로 읽는다',ARRAY['6국05 문학(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C6','kor',6,2,'u6',2,'겪은 일을 시로 옮기는 일 — 겪은 일을 전부 쓰지 않고 인상 깊었던 부분만 고르고, 장면이 바뀔 때 연과 행을 나누고, 마음을 다른 사물이나 비슷한 상황에 빗대고, 본 것·들은 것·만진 것을 그대로 살린다',ARRAY['6국05 문학(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C7','kor',6,2,'u6',2,'비유적 표현과 빗댄 까닭 — 비슷한 점이 있는 두 대상을 이어 나타내는 것을 비유적 표현이라 하며, 빗댈 때에는 반드시 비슷한 점이 있어(아침 집 = 끓는 주전자: 바쁘고 뜨거운 기운 · 낮 집 = 빈 운동장: 텅 빔 · 저녁 집 = 난롯가: 따뜻하게 둘러앉음) 그 점을 말로 옮길 수 있어야 한다',ARRAY['6국05 문학(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C8','kor',6,2,'u6',2,'직유법과 은유법 — 직유법은 「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법(주전자처럼 끓는다)이고, 은유법은 「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법(낮 우리 집은 빈 운동장이다)이다',ARRAY['6국05 문학(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C9','kor',6,2,'u6',2,'감각적 표현 — 보고·듣고·맡고·만지고·맛본 것을 그대로 살려 쓴 표현으로(들은 것 — 김이 푹푹 · 본 것 — 시계 초침), 다른 것에 빗대는 비유적 표현과 달리 느낀 감각을 그대로 옮겨 장면을 생생하게 한다',ARRAY['6국05 문학(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C10','kor',6,2,'u6',2,'시의 특성은 규칙이 아니라 방법 — 연과 행으로 나누어 노래하는 듯한 리듬이 느껴지고, 생각이나 느낌을 짧은 글로 눌러 담으며, 비유적 표현과 감각적 표현으로 대상을 생생하게 나타내지만, 이 셋은 지켜야 할 규칙이 아니라 쓸 수 있는 방법이다',ARRAY['6국05 문학(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C11','kor',6,2,'u6',4,'시 쓰기 준비와 묻고 답하기 — 시로 쓸 경험 고르기 → 묻고 답하며 자세히 떠올리기 → 생각그물로 모으기 → 남길 것과 버릴 것 고르기의 차례로 준비하며, 「가장 기억에 남는 순간은? · 그때 본 것과 들은 것은? · 무엇에 빗댈 수 있을까? · 마음이 어떻게 움직였나?」처럼 그 경험 속으로 다시 들어가게 하는 물음이 기억을 또렷하게 한다',ARRAY['6국05 문학(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C12','kor',6,2,'u6',4,'생각그물로 갈래 나누어 모으기 — 가운데에 경험을 두고 둘레에 본 것(지나가는 줄)·들은 것(탁, 탁 소리)·만진 것(미끄러운 손잡이)·생각이나 느낌(드디어 되었다)·빗댈 것(떠 있는 몸 → 새)을 갈래별로 적어 두면 시로 옮기기 쉬워진다',ARRAY['6국05 문학(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C13','kor',6,2,'u6',4,'시는 넣는 일보다 버리는 일 — 생각그물을 다 넣으면 빠뜨린 것은 없어도 어느 순간이 중요한지 알 수 없는 목록이 되고, 인상 깊은 순간만 골라 남기면 그 마음이 또렷해진다 (짧아서 좋은 것이 아니라 고르고 버려서 또렷해진 것이다)',ARRAY['6국05 문학(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C14','kor',6,2,'u6',4,'마음이 드러나는 제목 — 제목은 겪은 일 그대로(줄넘기를 한 날)·가장 인상 깊은 것으로·빗댄 표현으로(백한 번째 새) 붙일 수 있고, 맨 처음에 붙여도 다 쓴 뒤에 붙여도 되지만 시를 읽고 나서 고개가 끄덕여지게 시에 담긴 마음이 드러나면 좋다',ARRAY['6국05 문학(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C15','kor',6,2,'u6',4,'시 고쳐 쓰기 — 다 쓴 시는 전하려던 마음이 드러나는가 · 장면이 바뀌는 곳에서 연이 나뉘었는가 · 없어도 되는 줄이 남아 있지 않은가 · 소리 내어 읽었을 때 걸리는 곳이 없는가를 보며 고치고, 고쳐 쓰기는 벌이 아니라 시를 자라게 하는 단계다 (빗댄 표현의 개수나 글씨 모양은 볼 것이 아니다)',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C16','kor',6,2,'u6',6,'낭송 계획 — 마음에 맞는 목소리와 속도 — 듣는 사람에게 꼭 전하고 싶은 마음을 먼저 정하고, 그 마음에 맞게 부분마다 목소리와 속도를 정하며(숨을 참듯 낮고 느리게 · 또렷하고 빠르게 · 한 음절씩 힘을 실어 천천히), 여러 번 연습해 걸리는 곳을 고친다 — 목소리는 그 부분의 마음을 따라간다',ARRAY['6국01 듣기·말하기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C17','kor',6,2,'u6',6,'효과음 · 배경 음악 · 영상은 돕는 만큼 — 효과음은 시의 장면과 맞닿은 소리를 아주 짧게, 배경 음악은 시의 분위기와 어울리는 것을 낭송하는 목소리보다 작게, 영상이나 그림은 장면을 떠올리는 데 도움이 될 만큼만 쓰며, 셋 다 낭송을 돕는 것이지 대신하거나 덮는 것이 아니다',ARRAY['6국01 듣기·말하기(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C18','kor',6,2,'u6',6,'낭송을 듣는 사람과 구체적인 조언 — 낭송회는 낭송하는 사람과 듣는 사람이 함께 만들어, 듣는 사람은 낭송하는 사람을 바라보며 시와 관련 있는 내 경험을 떠올리며 듣고, 끝난 뒤 「잘했어」가 아니라 어느 부분을 어떻게 하면 좋을지까지 말해 준다',ARRAY['6국01 듣기·말하기(초안)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C19','kor',6,2,'u6',6,'낭송을 잘한다는 것 — 들리지 않을 만큼 읽어도, 마음과 상관없이 무조건 크게 읽어도, 음악과 영상으로 화려하게 꾸며도 안 되고, 뒤에 앉은 사람까지 들릴 만큼 부분마다 마음에 맞는 크기로 읽어 멋있게 들리는 것이 아니라 그 시의 마음이 건너가게 하는 것이다',ARRAY['6국01 듣기·말하기(초안)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C20','kor',6,2,'u6',7,'패러디와 표절 — 널리 알려진 이야기를 원래 이야기를 밝히고 일부러 비틀어 바뀐 곳에서 새로운 뜻이 생기게 하는 것이 패러디이고, 남의 것을 그대로 옮기고 자기 것인 척해 새로운 뜻이 생기지 않는 것이 표절이다',ARRAY['6국05 문학(초안)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C21','kor',6,2,'u6',7,'성격이 바뀌면 하는 일이 바뀐다 — 「금도끼 은도끼」의 나무꾼은 제 것이 아닌 것을 제 것이라 하지 않고 주는 것을 고맙게 받지만, 「마르지 않는 샘」의 나무꾼은 받기 전에 마을에 무슨 일이 생길지 먼저 생각해 상을 거절하듯, 인물의 성격이 바뀌면 그 인물이 하는 일도 바뀐다',ARRAY['6국05 문학(초안)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C22','kor',6,2,'u6',7,'배경이 바뀌면 할 수 있는 일이 바뀐다 — 그저 「옛날」이던 때를 「몇 해째 비가 오지 않아 우물이 말라 가던 해」로 바꾸자 나무꾼이 물을 걱정하는 것이 자연스러워졌듯, 때와 곳을 바꾸면 인물이 할 수 있는 일과 일어날 사건이 함께 달라진다',ARRAY['6국05 문학(초안)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C23','kor',6,2,'u6',7,'앞의 일이 뒤의 일을 부른다 — 이야기는 바뀌어도 원인과 결과로 이어져야 해서(가뭄이 든 해였으므로 → 물을 먼저 걱정했고 → 그래서 상을 거절했고 → 그래서 샘이 생겼다) 이어 쓸 때에도 앞에서 생긴 일이 뒤의 일을 불러오게 쓴다',ARRAY['6국05 문학(초안)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C24','kor',6,2,'u6',7,'잘 바꾼 이야기는 많이 바꾼 이야기가 아니다 — 갑자기 우주선이 내려오는 것처럼 놀랍기만 하고 앞의 일과 이어지지 않는 바꾸기는 잘 바꾼 것이 아니며, 바꾸어 쓰기는 기발한 생각을 얼마나 많이 넣었는가가 아니라 바뀐 것에 따라 뒤가 자연스럽게 이어지는가로 가늠한다',ARRAY['6국05 문학(초안)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C25','kor',6,2,'u6',7,'바꾸어 쓸 때 생각할 점과 경험 — 인물을 어떤 성격으로 · 때와 곳을 어떻게 바꿀지 · 앞의 일이 뒤의 일을 부르는지 · 내가 잘 아는 경험을 살릴 수 있는지를 생각하며, 경험을 바탕으로 쓴 이야기는 실제로 있었던 일만 적는 일기와 달리 겪은 일에서 출발하되 인물·배경·사건을 지어낸다 (겪어 본 것에서 출발하면 더 자세히 쓸 수 있다)',ARRAY['6국05 문학(초안)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C26','kor',6,2,'u6',9,'바꾸어 쓰면 새로운 뜻이 생긴다 — 「정직하면 상을 받는다」던 이야기가 상을 거절하고 마을에 샘이 생기는 이야기로 바뀌면 「정직함은 나 혼자의 일이 아니다」라는 새로운 뜻이 생기며, 그것이 이야기를 바꾸어 쓰는 까닭이다',ARRAY['6국05 문학(초안)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C27','kor',6,2,'u6',9,'인물의 성격과 사건의 차례 정리하기 — 인물의 성격은 그 인물이 한 말과 행동에서 드러나고(놀라지 않은 척 둘러대는 토끼 · 혼자 뭍까지 올라간 자라 · 들은 말을 그대로 믿는 용왕), 사건은 보통 발단(일이 시작됨)·전개(일이 커짐)·절정(가장 긴장되는 순간)을 거쳐 마지막에 일이 마무리되는 차례로 흘러가므로, 바꾸기 전에 이 둘을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보인다',ARRAY['6국05 문학(초안)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C28','kor',6,2,'u6',9,'바꾸기 계획 — 하나를 바꾸면 함께 손볼 곳 — 인물·배경·사건 가운데 하나만 골라 바꾸어도 충분하며(나머지가 따라 움직이므로), 바꿀 것 · 그 때문에 달라지는 것 · 그대로 둘 것을 적고, 성격을 바꾸었으면 행동도 함께 바꾸어야 한다 (자라가 따져 보는 성격이 되면 토끼에게 하는 말 · 토끼의 행동 · 이야기의 끝이 함께 바뀐다)',ARRAY['6국05 문학(초안)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C29','kor',6,2,'u6',9,'바꾼 이야기의 첫 문장과 제목 — 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 읽는 사람이 금방 알아채고, 제목은 새로 바꾼 인물의 성격·배경·사건이 드러나게 붙이며(「자라가 입을 열었다」), 맨 처음에 붙여도 다 쓴 뒤에 붙여도 된다',ARRAY['6국05 문학(초안)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C30','kor',6,2,'u6',9,'칭찬 쪽지 — 어느 부분이 왜 — 글은 읽어 주는 사람이 있을 때 완성되며, 친구의 이야기를 읽고 「잘 썼어 · 재미있어」에서 멈추지 않고 어느 부분이 좋았는지 짚고 왜 좋았는지 까닭을 붙여 쓴다 (글씨처럼 이야기와 상관없는 겉모습만 칭찬하지 않는다)',ARRAY['6국05 문학(초안)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C31','kor',6,2,'u6',12,'책의 형태와 독자 — 종이책(교실에 두고 아무 때나 넘겨 봄)·소리로 담는 책(낭송의 목소리와 속도를 그대로 남김)·화면으로 보는 책(멀리 있는 사람에게도 보냄)은 더 나은 것 없이 알맞은 자리가 서로 다를 뿐이고, 누가 읽을지와 무엇을 전하고 싶은지를 먼저 정하면 형태가 따라 정해진다',ARRAY['6국03 쓰기(초안)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C32','kor',6,2,'u6',12,'실을 글을 쓰기 전에 정할 것 — 중심 사건 · 등장인물의 이름과 성격 · 일이 일어난 때와 곳 · 사건이 이어지는 차례를 정해 두면 글이 빨리 써지며, 겪은 일에서 출발하되 일기를 옮겨 적는 것이 아니라 인물과 배경을 지어내도 된다 (표지 색이나 글자 수는 먼저 정할 것이 아니다)',ARRAY['6국03 쓰기(초안)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C33','kor',6,2,'u6',12,'꾸미기가 이야기를 덮지 않게 함께 만들기 — 이야기를 먼저 완성하고 꾸미기는 읽기 좋게 돕는 만큼만 하며, 함께 만들 때에는 누구와 · 무엇을 맡을지 · 언제까지를 정하고 다 만든 뒤 글에서 잘한 점부터 이야기한다 — 목적은 멋진 결과물이 아니라 쓰고 나누는 즐거움을 겪어 보는 것',ARRAY['6국03 쓰기(초안)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C34','kor',6,2,'u6',12,'소리가 같고 뜻이 다른 낱말 — 읽을 때 소리는 같지만 쓰는 글자와 뜻이 다른 낱말(바치다 = 웃어른께 정중히 올리다 · 받치다 = 밑에서 괴어 기울지 않게 하다 / 메다 = 어깨에 걸쳐 지다 · 매다 = 끈이나 줄을 묶다 / 부치다 = 편지나 물건을 보내다 · 붙이다 = 맞닿아 떨어지지 않게 하다)은 앞뒤 문장을 보고 쓰이는 자리에 맞게 골라 쓴다 (기초 다지기)',ARRAY['6국04 문법(초안)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X01','kor',6,'u6',ARRAY['K6-2-u6-C1']::text[],'경험을 글로 쓰는 좋은 점을 글씨를 예쁘게 쓰기 · 글을 길게 늘리기 같은 겉모습에서 찾는다','나에게, 읽는 사람에게 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X02','kor',6,'u6',ARRAY['K6-2-u6-C2','K6-2-u6-C25']::text[],'여행이나 대단한 일을 겪어야 글감이 된다고 여겨, 날마다 겪는 작은 일을 글감으로 보지 않는다','그때 마음이 움직였는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X03','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C7','K6-2-u6-C10']::text[],'빗댄 표현을 많이 넣을수록 좋은 시라고 여긴다','개수가 아니라 그 마음에 알맞은가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X04','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C10']::text[],'어렵고 멋있어 보이는 말을 쓸수록 좋은 시라고 여긴다','짧고 쉬운 말도 좋은 시가 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X05','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C27']::text[],'인물 · 배경 · 사건의 뜻을 서로 헷갈린다','누가 · 언제 어디서 · 무슨 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X06','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C21','K6-2-u6-C22']::text[],'이야기의 세 요소가 따로 움직인다고 여겨, 하나를 바꾸어도 나머지는 그대로라고 생각한다','하나를 바꾸면 나머지도 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X07','kor',6,'u6',ARRAY['K6-2-u6-C5']::text[],'시가 담은 경험을 말하는 이가 실제로 한 일에서 찾지 않고 시에 없는 사건으로 짐작한다','말하는 이가 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X08','kor',6,'u6',ARRAY['K6-2-u6-C5','K6-2-u6-C7']::text[],'빗댄 말을 실제로 일어난 일로 읽어, 그 말이 나타낸 마음을 놓친다','실제 일인가, 마음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X09','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C13']::text[],'겪은 일을 시로 옮길 때 하나도 빠뜨리지 않고 차례대로 다 적어야 한다고 여긴다','인상 깊은 부분만 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X10','kor',6,'u6',ARRAY['K6-2-u6-C7']::text[],'빗댄 두 대상 사이의 비슷한 점을 찾지 못하거나, 비슷한 점이 없는 것끼리 아무렇게나 빗댄다','어떤 점에서 닮았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X11','kor',6,'u6',ARRAY['K6-2-u6-C8']::text[],'직유법과 은유법을 서로 헷갈린다','「처럼 · 같이 · 듯이」가 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X12','kor',6,'u6',ARRAY['K6-2-u6-C9','K6-2-u6-C12']::text[],'감각적 표현과 비유적 표현을 헷갈리거나, 본 것 · 들은 것 · 만진 것을 갈래대로 가르지 못한다','느낀 그대로? 다른 것에 빗댐?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X13','kor',6,'u6',ARRAY['K6-2-u6-C10','K6-2-u6-C3']::text[],'연과 행 · 비유 같은 시의 특성을 꼭 지켜야 할 규칙으로 여겨, 빗댄 표현이 없으면 시가 아니라고 생각한다','규칙이 아니라 쓸 수 있는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X14','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C15']::text[],'장면이 바뀌어도 연을 나누지 않거나, 장면과 상관없이 아무 데서나 연과 행을 나눈다','장면이 바뀌는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X15','kor',6,'u6',ARRAY['K6-2-u6-C11']::text[],'경험을 자세히 떠올리는 물음 대신 몇 시 몇 분 · 몇 줄로 쓸지 같은 겉 물음을 고른다','그 경험 속으로 다시 들어가게 하는 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X16','kor',6,'u6',ARRAY['K6-2-u6-C12','K6-2-u6-C13']::text[],'생각그물에 모은 것을 다 넣어야 빠짐없는 좋은 시가 된다고 여긴다','넣는 일보다 버리는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X17','kor',6,'u6',ARRAY['K6-2-u6-C13']::text[],'고른 시가 더 나은 까닭을 「짧아서 · 빗댄 표현이 많아서」로 여겨, 고르고 버려서 마음이 또렷해진 것을 보지 못한다','읽고 나서 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X18','kor',6,'u6',ARRAY['K6-2-u6-C14','K6-2-u6-C29']::text[],'제목을 담긴 마음이나 바뀐 것과 상관없이 붙이거나, 제목은 반드시 맨 처음에 정해야 한다고 여긴다','읽고 나서 고개가 끄덕여지는 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X19','kor',6,'u6',ARRAY['K6-2-u6-C15']::text[],'시를 고쳐 쓸 때 빗댄 표현의 개수나 글씨 모양 같은 겉모습을 보거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','전하려던 마음 · 연 · 없어도 되는 줄 · 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X20','kor',6,'u6',ARRAY['K6-2-u6-C16']::text[],'전할 마음을 정하지 않고 낭송하거나, 시의 모든 부분을 같은 목소리와 속도로 읽는다','목소리는 그 부분의 마음을 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X21','kor',6,'u6',ARRAY['K6-2-u6-C19','K6-2-u6-C16']::text[],'낭송을 잘한다는 것을 마음과 상관없이 무조건 크게 읽는 것으로 여긴다','크게가 아니라 마음에 맞는 크기로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X22','kor',6,'u6',ARRAY['K6-2-u6-C17','K6-2-u6-C19']::text[],'효과음 · 배경 음악 · 영상을 많이, 크게, 화려하게 쓸수록 낭송이 좋아진다고 여긴다','돕는 만큼만, 목소리보다 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X23','kor',6,'u6',ARRAY['K6-2-u6-C19']::text[],'마음만 담으면 들리지 않을 만큼 작게 읽어도 괜찮다고 여긴다','뒤에 앉은 사람까지 들리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X24','kor',6,'u6',ARRAY['K6-2-u6-C18']::text[],'친구의 낭송을 들을 때 옆 친구와 이야기하거나 틀린 글자만 찾는 것을 잘 듣는 것으로 여긴다','바라보며, 내 경험을 떠올리며') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X25','kor',6,'u6',ARRAY['K6-2-u6-C18','K6-2-u6-C30']::text[],'조언이나 칭찬을 「잘했어 · 재미있어」처럼 어느 부분이 왜 그런지 없이 막연하게 하거나, 글씨 같은 겉모습만 칭찬한다','어느 부분을 · 왜 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X26','kor',6,'u6',ARRAY['K6-2-u6-C20']::text[],'패러디와 표절을 같은 것으로 여기거나, 원래 이야기를 밝히지 않고 그대로 옮겨도 패러디라고 생각한다','밝히고 일부러 바꾸어 새 뜻이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X27','kor',6,'u6',ARRAY['K6-2-u6-C21','K6-2-u6-C28']::text[],'인물의 성격을 바꾸어 놓고 그 인물의 말과 행동은 그대로 둔다','성격이 바뀌면 하는 일도 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X28','kor',6,'u6',ARRAY['K6-2-u6-C22']::text[],'배경을 바꾼 것이 인물이 할 수 있는 일이나 사건과 어떻게 이어지는지 보지 못한다','그 때와 곳이라서 할 수 있는 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X29','kor',6,'u6',ARRAY['K6-2-u6-C23','K6-2-u6-C24']::text[],'앞의 일과 이어지지 않는 갑작스러운 사건(하늘에서 우주선이 내려옴 · 갑자기 병이 나음)을 이어 쓴다','앞의 일이 뒤의 일을 부르나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X30','kor',6,'u6',ARRAY['K6-2-u6-C24']::text[],'많이 · 놀랍게 · 기발하게 바꿀수록 잘 바꾼 이야기라고 여긴다','놀라움이 아니라 이어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X31','kor',6,'u6',ARRAY['K6-2-u6-C25','K6-2-u6-C32']::text[],'경험을 바탕으로 쓴 이야기를 일기처럼 겪은 일 그대로만 써야 한다고 여기거나, 반대로 일기에 지어낸 일을 적어도 된다고 여긴다','일기는 사실, 이야기는 지어냄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X32','kor',6,'u6',ARRAY['K6-2-u6-C26']::text[],'이야기를 바꾸어 쓰는 까닭을 글을 길게 늘리기나 재미만으로 여겨, 바뀐 곳에서 새로운 뜻이 생기는 것을 모른다','바꾸면 무엇이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X33','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'인물의 성격을 그 인물이 한 말과 행동과 잇지 못한다','그 인물이 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X34','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'발단 · 전개 · 절정의 차례와 각 단계에서 일어나는 일을 헷갈린다','시작 · 커짐 · 가장 긴장되는 순간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X35','kor',6,'u6',ARRAY['K6-2-u6-C28']::text[],'하나를 바꾸어도 다른 곳은 손볼 필요가 없다고 여기거나, 이야기와 상관없는 글자 수 · 공간 같은 것을 손볼 곳으로 고른다','바꾼 것에 닿아 있던 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X36','kor',6,'u6',ARRAY['K6-2-u6-C28','K6-2-u6-C24']::text[],'인물 · 배경 · 사건을 모두 한꺼번에 바꾸어야 제대로 바꾼 것이라고 여긴다','하나만 바꾸어도 충분해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X37','kor',6,'u6',ARRAY['K6-2-u6-C29']::text[],'바꾼 이야기의 첫 문장을 바뀐 것과 상관없이 원래 이야기 그대로 시작해, 읽는 사람이 무엇이 바뀌었는지 알아채기 어렵게 한다','바뀐 것이 드러나는 곳에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X38','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'책의 형태에 등수를 매기거나, 가장 새롭고 멋있어 보이는 형태 · 가장 빨리 끝나는 형태를 고른다','더 나은 형태는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X39','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'누가 읽을지와 무엇을 전하고 싶은지를 정하지 않고 책의 형태부터 고른다','독자가 정해지면 형태가 따라와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X40','kor',6,'u6',ARRAY['K6-2-u6-C32']::text[],'글을 쓰기 전에 정할 것을 표지 색깔 · 글자 수 같은 겉모습에서 찾는다','중심 사건 · 인물 · 때와 곳 · 차례') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X41','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'표지와 그림이 화려한 것을 잘한 것으로 여겨 꾸미기에 시간을 다 쓰고 글은 급히 쓴다','이야기가 먼저, 꾸미기는 돕는 만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X42','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'함께 만들 때 누가 무엇을 언제까지 맡을지 정하지 않거나, 다 만든 뒤 잘한 점이 아니라 고칠 점부터 말한다','누구와 · 무엇을 · 언제까지 · 잘한 점부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X43','kor',6,'u6',ARRAY['K6-2-u6-C34']::text[],'소리가 같은 낱말(바치다 · 받치다, 메다 · 매다, 부치다 · 붙이다)을 앞뒤 문장의 뜻과 상관없이 섞어 쓴다','앞뒤 문장을 보고 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#1','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C5',1,'mc','auto','시 「우유갑」은 어떤 경험을 시로 표현했나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C5","difficulty":1,"kind":"mc","stem":"시 「우유갑」은 어떤 경험을 시로 표현했나요?","options":[{"t":"급식 우유갑을 여느라 애쓴 경험","correct":true},{"t":"아침에 늦잠을 자 학교에 뛰어간 경험","mis":"K6-2-u6-X07"},{"t":"집 대문이 고장 나 고쳐 본 경험","mis":"K6-2-u6-X07"},{"t":"우유를 쏟아 옷을 버린 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이가 실제로 한 일을 찾아요.","손톱으로 모서리를 톡, 톡 두드렸어요.","우유갑을 여는 작은 경험이 시가 되었어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#2','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',1,'match','auto','이야기의 요소와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C4","difficulty":1,"kind":"match","stem":"이야기의 요소와 알맞은 설명을 이으세요.","pairs":[{"l":"인물","r":"이야기에 나오는 사람이나 대상"},{"l":"배경","r":"일이 일어난 때와 곳"},{"l":"사건","r":"이야기 속에서 일어난 일"}],"mis":"K6-2-u6-X05","explanation":["누가 나오는지가 인물이에요.","언제 어디인지가 배경이에요.","무슨 일이 일어나는지가 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#3','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C2',1,'ox','auto','대단한 일을 겪어야만 시의 글감이 될 수 있어요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":3,"concept":"K6-2-u6-C2","difficulty":1,"kind":"ox","stem":"대단한 일을 겪어야만 시의 글감이 될 수 있어요.","answer":"X","reason_options":[{"t":"마음이 움직인 일이면 작은 일도 글감이 되기 때문에","correct":true},{"t":"특별한 일이어야 읽는 사람이 놀라기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["우유갑 하나도 시가 되었어요.","글감을 고르는 물음은 하나예요.","그때 내 마음이 움직였는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#4','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',1,'mc','auto','「비가 오지 않던 해, 산속 연못」은 이야기의 세 요소 가운데 무엇인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":4,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"「비가 오지 않던 해, 산속 연못」은 이야기의 세 요소 가운데 무엇인가요?","options":[{"t":"배경","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"사건","mis":"K6-2-u6-X05"},{"t":"제목","mis":"K6-2-u6-X05"}],"explanation":["때와 곳이 들어 있어요.","일이 일어난 때와 곳은 배경이에요.","인물은 누가, 사건은 무슨 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#5','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C1',2,'mc','auto','경험을 시나 이야기로 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X04']::text[],false,'{"seq":5,"concept":"K6-2-u6-C1","difficulty":2,"kind":"mc","stem":"경험을 시나 이야기로 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"그때 내 마음이 어땠는지 또렷하게 알게 된다","correct":true},{"t":"글씨를 예쁘게 쓰는 법을 익힌다","mis":"K6-2-u6-X01"},{"t":"글의 길이를 길게 늘릴 수 있다","mis":"K6-2-u6-X01"},{"t":"어려운 낱말을 많이 외우게 된다","mis":"K6-2-u6-X04"}],"explanation":["글씨와 길이는 겉모습이에요.","쓰는 동안 내 마음이 정리돼요.","읽는 사람에게도 생생하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#6','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C3',2,'mc','auto','이 단원의 약속으로 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":6,"concept":"K6-2-u6-C3","difficulty":2,"kind":"mc","stem":"이 단원의 약속으로 알맞게 말한 것은 어느 것인가요?","options":[{"t":"빗댄 표현은 그 마음에 알맞을 때 힘이 있다","correct":true},{"t":"빗댄 표현이 많은 시가 언제나 더 좋은 시다","mis":"K6-2-u6-X03"},{"t":"어려운 말을 쓸수록 좋은 시다","mis":"K6-2-u6-X04"},{"t":"특별한 일을 겪은 사람만 시를 쓸 수 있다","mis":"K6-2-u6-X02"}],"explanation":["「우유갑」에는 빗댄 표현이 하나뿐이에요.","그래도 마음이 잘 전해져요.","개수가 아니라 알맞음이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#7','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C5',2,'mc','auto','「우유갑」의 말하는 이가 「꼭 이만큼만 열렸으면」 하고 바라는 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":7,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「우유갑」의 말하는 이가 「꼭 이만큼만 열렸으면」 하고 바라는 것은 무엇인가요?","options":[{"t":"엄마한테 삐친 자기 마음","correct":true},{"t":"우유갑의 작은 문","mis":"K6-2-u6-X08"},{"t":"교실의 창문","mis":"K6-2-u6-X07"},{"t":"엄마가 닫아 둔 대문","mis":"K6-2-u6-X07"}],"explanation":["우유갑이 겨우 열린 모습을 보았어요.","그 모습에 삐친 마음을 견주었어요.","마음도 조금은 풀리기를 바란 거예요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#8','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',2,'ox','auto','이야기에서 인물을 바꾸면 사건도 함께 달라질 수 있어요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":8,"concept":"K6-2-u6-C4","difficulty":2,"kind":"ox","stem":"이야기에서 인물을 바꾸면 사건도 함께 달라질 수 있어요.","answer":"O","reason_options":[{"t":"세 요소는 서로 붙어 있어 하나를 바꾸면 나머지도 움직이기 때문에","correct":true},{"t":"세 요소는 따로따로라서 바꾸어도 상관없기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["겁 많은 나무꾼과 용감한 나무꾼은 하는 일이 달라요.","하는 일이 달라지면 사건이 달라져요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#9','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C2',2,'error','auto','글감에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":9,"concept":"K6-2-u6-C2","difficulty":2,"kind":"error","stem":"글감에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지오 — 「나는 여행도 안 갔고 특별한 일도 없어서 쓸 게 없어.」","correct":true,"mis_target":"K6-2-u6-X02"},{"t":"채아 — 「우유갑이 안 열려 씨름했던 일도 글감이야.」","mis":"K6-2-u6-X02"},{"t":"세윤 — 「마음이 움직인 일이면 뭐든 돼.」","mis":"K6-2-u6-X02"}],"explanation":["채아와 세윤은 바르게 말했어요.","지오는 대단한 일만 글감이라고 여겼어요.","날마다 겪는 작은 일도 글감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#10','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C3',3,'mc','auto','「우유갑」을 두고 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":3,"kind":"mc","stem":"「우유갑」을 두고 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빗댄 표현이 하나뿐이지만 삐친 마음이 잘 전해진다","correct":true},{"t":"빗댄 표현이 하나뿐이라 좋은 시라고 할 수 없다","mis":"K6-2-u6-X03"},{"t":"어려운 말이 없어 시답지 않다","mis":"K6-2-u6-X04"},{"t":"우유갑은 대단한 일이 아니라 글감이 되지 않는다","mis":"K6-2-u6-X02"}],"explanation":["빗댄 표현의 개수로 시를 재지 않아요.","짧고 쉬운 말도 좋은 시가 돼요.","그 마음에 알맞으면 힘이 있어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#1','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',2,'mc','auto','「도끼를 물에 빠뜨렸다」는 이야기의 세 요소 가운데 무엇인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":1,"concept":"K6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「도끼를 물에 빠뜨렸다」는 이야기의 세 요소 가운데 무엇인가요?","options":[{"t":"사건","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"배경","mis":"K6-2-u6-X05"},{"t":"주제","mis":"K6-2-u6-X05"}],"explanation":["누가 나오는지는 인물이에요.","때와 곳은 배경이에요.","일어난 일은 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#2','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',2,'mc','auto','「우유갑」에서 경험을 시로 쓴 덕분에 읽는 사람에게까지 전해진 것은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X01']::text[],false,'{"seq":2,"concept":"K6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「우유갑」에서 경험을 시로 쓴 덕분에 읽는 사람에게까지 전해진 것은 무엇인가요?","options":[{"t":"우유갑을 여는 모습과 함께 삐친 마음","correct":true},{"t":"우유갑을 만든 회사 이름","mis":"K6-2-u6-X07"},{"t":"시를 쓴 날의 날씨","mis":"K6-2-u6-X07"},{"t":"글씨를 쓴 모양","mis":"K6-2-u6-X01"}],"explanation":["우유갑 하나로 장면이 떠올라요.","삐친 마음까지 함께 전해져요.","말로 하기 어려운 것을 전할 수 있어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#3','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',3,'mc','auto','지오가 「쓸 게 없다」고 할 때 글감을 찾도록 돕는 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X15']::text[],false,'{"seq":3,"concept":"K6-2-u6-C2","difficulty":3,"kind":"mc","stem":"지오가 「쓸 게 없다」고 할 때 글감을 찾도록 돕는 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「오늘 마음이 조금이라도 움직인 일이 있었어?」","correct":true},{"t":"「이번 방학에 어디로 여행 갔어?」","mis":"K6-2-u6-X02"},{"t":"「남들이 놀랄 만한 일을 겪은 적 있어?」","mis":"K6-2-u6-X02"},{"t":"「시를 몇 줄로 쓸 거야?」","mis":"K6-2-u6-X15"}],"explanation":["여행이나 놀랄 일을 물으면 글감이 줄어들어요.","줄 수는 글감과 상관없어요.","마음이 움직였는지를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#4','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',3,'ox','auto','빗댄 표현이 다섯 개 넘게 들어간 시가 하나만 들어간 시보다 언제나 더 좋아요.',ARRAY['K6-2-u6-X03']::text[],false,'{"seq":4,"concept":"K6-2-u6-C3","difficulty":3,"kind":"ox","stem":"빗댄 표현이 다섯 개 넘게 들어간 시가 하나만 들어간 시보다 언제나 더 좋아요.","answer":"X","reason_options":[{"t":"표현은 개수가 아니라 그 마음에 알맞은지로 고르기 때문에","correct":true},{"t":"빗댄 표현이 많을수록 시가 화려해지기 때문에","mis":"K6-2-u6-X03"}],"mis":"K6-2-u6-X03","explanation":["많이 넣는다고 마음이 더 잘 전해지지 않아요.","알맞지 않은 표현은 오히려 흐리게 해요.","그 마음에 알맞은지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#5','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',3,'match','auto','이야기 속 내용과 요소를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C4","difficulty":3,"kind":"match","stem":"이야기 속 내용과 요소를 알맞게 이으세요.","pairs":[{"l":"겁이 많은 나무꾼","r":"인물"},{"l":"비가 오지 않던 해, 산속 연못","r":"배경"},{"l":"도끼를 물에 빠뜨렸다","r":"사건"}],"mis":"K6-2-u6-X05","explanation":["나무꾼은 이야기에 나오는 사람이에요.","해와 연못은 때와 곳이에요.","빠뜨린 일은 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#6','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',3,'error','auto','좋은 시에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X04','K6-2-u6-X03']::text[],false,'{"seq":6,"concept":"K6-2-u6-C3","difficulty":3,"kind":"error","stem":"좋은 시에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준하 — 「어려운 말을 많이 써야 시가 멋있어져.」","correct":true,"mis_target":"K6-2-u6-X04"},{"t":"하진 — 「짧고 쉬운 말로도 마음이 잘 전해질 수 있어.」","mis":"K6-2-u6-X04"},{"t":"세윤 — 「그 마음에 알맞은 표현이면 좋은 표현이야.」","mis":"K6-2-u6-X03"}],"explanation":["하진과 세윤은 바르게 말했어요.","준하는 어려운 말을 좋은 시의 기준으로 삼았어요.","알맞음이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#7','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',3,'mc','auto','경험을 글로 남기면 「지나가 버릴 일이 오래 남는다」는 것은 어떤 뜻인가요?',ARRAY['K6-2-u6-X01']::text[],false,'{"seq":7,"concept":"K6-2-u6-C1","difficulty":3,"kind":"mc","stem":"경험을 글로 남기면 「지나가 버릴 일이 오래 남는다」는 것은 어떤 뜻인가요?","options":[{"t":"글로 적어 두면 그때의 일과 마음을 나중에도 다시 만날 수 있다","correct":true},{"t":"글로 적으면 그 일이 실제로 다시 일어난다","mis":"K6-2-u6-X01"},{"t":"글로 적은 일은 잊어버려도 괜찮다","mis":"K6-2-u6-X01"},{"t":"글을 길게 쓸수록 오래 기억된다","mis":"K6-2-u6-X01"}],"explanation":["일은 지나가도 글은 남아요.","다시 읽으면 그때 마음을 만나요.","길이와는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#8','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',4,'mc','auto','「겁이 많은 나무꾼」을 「겁이 없는 나무꾼」으로 바꾸면 어떤 일이 생길지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":8,"concept":"K6-2-u6-C4","difficulty":4,"kind":"mc","stem":"「겁이 많은 나무꾼」을 「겁이 없는 나무꾼」으로 바꾸면 어떤 일이 생길지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"나무꾼이 연못 앞에서 하는 말과 행동이 달라져 사건도 함께 바뀐다","correct":true},{"t":"인물만 바뀌고 사건과 배경은 그대로 둔다","mis":"K6-2-u6-X06"},{"t":"이야기의 제목만 바뀐다","mis":"K6-2-u6-X06"},{"t":"인물을 바꾸면 이야기가 이어질 수 없다","mis":"K6-2-u6-X06"}],"explanation":["성격이 바뀌면 하는 일이 바뀌어요.","하는 일이 바뀌면 사건이 바뀌어요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#9','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',4,'essay','teacher','오늘 하루 가운데 마음이 조금이라도 움직인 작은 일을 하나 골라, 그 일이 왜 시의 글감이 될 수 있는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C2","difficulty":4,"kind":"essay","stem":"오늘 하루 가운데 마음이 조금이라도 움직인 작은 일을 하나 골라, 그 일이 왜 시의 글감이 될 수 있는지 쓰세요.","answer_guide":{"answer":"예: 아침에 신발 끈이 자꾸 풀려서 세 번이나 다시 맨 일. 아주 작은 일이지만 늦을까 봐 조마조마하고 짜증이 났던 마음이 또렷하게 기억난다. 글감은 대단한 일이 아니라 그때 내 마음이 움직였는가로 고르기 때문에, 이 일도 시의 글감이 될 수 있다.","scoring_points":["날마다 겪는 작은 일을 하나 골랐는가","그때 움직인 마음을 썼는가","「마음이 움직였는가」를 까닭으로 썼는가"]},"explanation":["작은 일이어도 좋아요.","그때 마음을 떠올려요.","마음이 움직였는가가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#10','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',4,'essay','teacher','「빗댄 표현을 많이 넣을수록 좋은 시다.」라는 말이 왜 알맞지 않은지 「우유갑」을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":4,"kind":"essay","stem":"「빗댄 표현을 많이 넣을수록 좋은 시다.」라는 말이 왜 알맞지 않은지 「우유갑」을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 「우유갑」에는 우유갑이 겨우 열린 모습에 삐친 마음을 견준 빗댄 표현이 딱 하나뿐이다. 그런데도 엄마한테 삐친 마음이 조금은 풀렸으면 하는 마음이 잘 전해진다. 좋은 표현은 개수가 아니라 그 마음에 알맞은지로 정해지기 때문에, 많이 넣는다고 좋은 시가 되는 것은 아니다.","scoring_points":["「우유갑」의 빗댄 표현이 하나뿐임을 썼는가","그런데도 마음이 전해진다고 썼는가","개수가 아니라 알맞음이 기준이라고 썼는가"]},"explanation":["빗댄 표현의 수를 세어 봐요.","마음이 전해지는지 봐요.","알맞음이 기준이에요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#1','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C5',1,'mc','auto','시 「바통」은 어떤 경험을 담았나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C5","difficulty":1,"kind":"mc","stem":"시 「바통」은 어떤 경험을 담았나요?","options":[{"t":"이어달리기에서 바통을 받기까지 기다린 경험","correct":true},{"t":"이어달리기에서 일 등을 한 경험","mis":"K6-2-u6-X07"},{"t":"달리다가 넘어져 다친 경험","mis":"K6-2-u6-X07"},{"t":"바통을 잃어버려 찾은 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이는 아직 달리지 않았어요.","앞 주자를 기다리고 있어요.","짧은 기다림이 시 한 편이 되었어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#2','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C7',1,'sa','auto','비슷한 점이 있는 두 대상을 이어 나타내는 것을 무엇이라고 하나요? 여섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C7","difficulty":1,"kind":"sa","stem":"비슷한 점이 있는 두 대상을 이어 나타내는 것을 무엇이라고 하나요? 여섯 글자로 쓰세요.","answer":["비유적표현","비유적 표현"],"explanation":["다른 것에 빗대어 나타내요.","두 대상 사이에는 비슷한 점이 있어요.","이것을 비유적 표현이라고 해요."],"mis":"K6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#3','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C8',1,'mc','auto','「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법은 무엇인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12','K6-2-u6-X14']::text[],false,'{"seq":3,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법은 무엇인가요?","options":[{"t":"직유법","correct":true},{"t":"은유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"연 나누기","mis":"K6-2-u6-X14"}],"explanation":["「처럼」이 들어 있으면 직유법이에요.","「무엇은 무엇이다」는 은유법이에요.","주전자처럼 끓는다가 직유법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#4','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C9',1,'ox','auto','「김이 푹푹 난다」는 들은 것을 그대로 살린 감각적 표현이에요.',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C9","difficulty":1,"kind":"ox","stem":"「김이 푹푹 난다」는 들은 것을 그대로 살린 감각적 표현이에요.","answer":"O","reason_options":[{"t":"귀로 들은 소리를 그대로 옮겼기 때문에","correct":true},{"t":"다른 대상에 빗대어 나타냈기 때문에","mis":"K6-2-u6-X12"}],"mis":"K6-2-u6-X12","explanation":["푹푹은 김이 나는 소리예요.","들은 것을 그대로 살렸어요.","그래서 감각적 표현이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#5','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C5',2,'mc','auto','「내 손 안에서 / 벌써 백 번은 미끄러졌다」는 어떤 마음을 나타낸 말인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「내 손 안에서 / 벌써 백 번은 미끄러졌다」는 어떤 마음을 나타낸 말인가요?","options":[{"t":"바통을 놓칠까 봐 걱정하는 마음이 몇 번이나 되풀이된 것","correct":true},{"t":"바통에 물이 묻어 실제로 자꾸 떨어진 것","mis":"K6-2-u6-X08"},{"t":"이어달리기를 백 번 연습해 보았다는 것","mis":"K6-2-u6-X08"},{"t":"손이 다쳐서 바통을 쥐지 못한 것","mis":"K6-2-u6-X07"}],"explanation":["바통은 아직 손에 오지도 않았어요.","실제로 미끄러진 것이 아니에요.","마음속에서 걱정한 거예요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#6','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C8',2,'mc','auto','「낮 / 우리 집은 빈 운동장이다」는 어떤 방법을 썼나요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":6,"concept":"K6-2-u6-C8","difficulty":2,"kind":"mc","stem":"「낮 / 우리 집은 빈 운동장이다」는 어떤 방법을 썼나요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"흉내 내는 말","mis":"K6-2-u6-X12"}],"explanation":["「처럼 · 같이」가 없어요.","「무엇은 무엇이다」로 말해 버렸어요.","그래서 은유법이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#7','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C7',2,'match','auto','빗댄 표현과 그렇게 빗댄 까닭을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u6-C7","difficulty":2,"kind":"match","stem":"빗댄 표현과 그렇게 빗댄 까닭을 이으세요.","pairs":[{"l":"아침 집 — 주전자처럼 끓는다","r":"바쁘고 뜨거운 기운이 넘쳐서"},{"l":"낮 집 — 빈 운동장이다","r":"아무도 없이 텅 비어 있어서"},{"l":"저녁 집 — 난롯가처럼 둥글다","r":"따뜻하게 둘러앉아 있어서"}],"mis":"K6-2-u6-X10","explanation":["빗댈 때에는 비슷한 점이 있어요.","그 점을 말로 옮겨 봐요.","아침 · 낮 · 저녁의 집이 달라요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#8','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C6',2,'mc','auto','겪은 일을 그대로 적은 글 ㉮를 시 「바통」으로 옮기면서 한 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X14']::text[],false,'{"seq":8,"concept":"K6-2-u6-C6","difficulty":2,"kind":"mc","stem":"겪은 일을 그대로 적은 글 ㉮를 시 「바통」으로 옮기면서 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 부분만 골라 남겼다","correct":true},{"t":"겪은 일을 하나도 빠뜨리지 않고 적었다","mis":"K6-2-u6-X09"},{"t":"어려운 낱말로 바꾸어 썼다","mis":"K6-2-u6-X04"},{"t":"장면이 바뀌어도 연을 나누지 않았다","mis":"K6-2-u6-X14"}],"explanation":["두 글은 같은 경험을 담았어요.","시는 인상 깊은 순간만 남겼어요.","연을 나누고 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["오늘 운동회에서 이어달리기를 했다. 내 차례를 기다리는 동안","손에 땀이 많이 났다. 앞 주자가 달려오는 것을 보니","심장이 빨리 뛰었다. 바통을 놓칠까 봐 걱정이 되었다.","바통을 받고 달리니 걱정이 사라졌다."],"title":"㉮ 같은 경험을 그대로 적은 글 (㉯는 시 「바통」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#9','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C10',2,'ox','auto','시는 반드시 빗댄 표현이 있어야 시라고 할 수 있어요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"ox","stem":"시는 반드시 빗댄 표현이 있어야 시라고 할 수 있어요.","answer":"X","reason_options":[{"t":"시의 특성은 지켜야 할 규칙이 아니라 쓸 수 있는 방법이기 때문에","correct":true},{"t":"빗댄 표현이 시를 시답게 만드는 규칙이기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["「우산 하나」에는 빗댄 표현이 하나도 없어요.","그래도 마음이 전해져요.","특성은 쓸 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#10','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C3',3,'mc','auto','시 「우산 하나」를 읽고 알맞게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X13','K6-2-u6-X04']::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「우산 하나」를 읽고 알맞게 말한 친구는 누구인가요?","options":[{"t":"세윤 — 「빗댄 표현이 없어도 마음이 그대로 전해져.」","correct":true},{"t":"하진 — 「빗댄 표현을 다섯 개 넘게 넣어야 좋은 시야.」","mis":"K6-2-u6-X03"},{"t":"준하 — 「빗댄 표현이 없으면 시라고 할 수 없어.」","mis":"K6-2-u6-X13"},{"t":"나은 — 「어려운 낱말이 없어서 시답지 않아.」","mis":"K6-2-u6-X04"}],"explanation":["「우산 하나」에는 빗댄 표현이 없어요.","젖은 어깨 하나로 마음이 전해져요.","표현은 알맞은지로 골라요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#1','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C9',2,'mc','auto','「우리 집 소리」에서 본 것을 그대로 살린 감각적 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":1,"concept":"K6-2-u6-C9","difficulty":2,"kind":"mc","stem":"「우리 집 소리」에서 본 것을 그대로 살린 감각적 표현은 어느 것인가요?","options":[{"t":"시계 초침만 혼자 술래를 한다","correct":true},{"t":"서둘러, 서둘러","mis":"K6-2-u6-X12"},{"t":"김이 푹푹 난다","mis":"K6-2-u6-X12"},{"t":"우리 집은 주전자처럼 끓는다","mis":"K6-2-u6-X12"}],"explanation":["서둘러와 푹푹은 들은 것이에요.","주전자처럼은 빗댄 표현이에요.","혼자 도는 초침은 본 것이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#2','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',2,'mc','auto','시의 특성으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":2,"concept":"K6-2-u6-C10","difficulty":2,"kind":"mc","stem":"시의 특성으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"겪은 일을 빠짐없이 차례대로 길게 적는다","correct":true},{"t":"연과 행으로 나누어 리듬이 느껴진다","mis":"K6-2-u6-X13"},{"t":"생각이나 느낌을 짧은 글로 눌러 담는다","mis":"K6-2-u6-X13"},{"t":"비유적 표현과 감각적 표현으로 생생하게 나타낸다","mis":"K6-2-u6-X13"}],"explanation":["리듬 · 짧게 · 생생하게는 시의 특성이에요.","빠짐없이 길게 적는 것은 일기에 가까워요.","시는 인상 깊은 것을 골라 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#3','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C7',3,'mc','auto','「누구 하나 빠지면 / 동그라미가 찌그러진다」에서 「동그라미」가 빗댄 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X10']::text[],false,'{"seq":3,"concept":"K6-2-u6-C7","difficulty":3,"kind":"mc","stem":"「누구 하나 빠지면 / 동그라미가 찌그러진다」에서 「동그라미」가 빗댄 것은 무엇인가요?","options":[{"t":"저녁에 둘러앉은 우리 가족","correct":true},{"t":"식탁 위에 놓인 둥근 접시","mis":"K6-2-u6-X08"},{"t":"밤하늘에 뜬 둥근 달","mis":"K6-2-u6-X10"},{"t":"난로에서 피어오르는 연기","mis":"K6-2-u6-X10"}],"explanation":["저녁 우리 집은 난롯가처럼 둥글어요.","가족이 둘러앉은 모습이 동그라미예요.","하나라도 빠지면 모양이 찌그러져요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#4','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C8',3,'error','auto','빗댄 표현을 가렸어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":3,"kind":"error","stem":"빗댄 표현을 가렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보람 — 「‘빈 운동장이다’는 ‘처럼’이 없으니 직유법이야.」","correct":true,"mis_target":"K6-2-u6-X11"},{"t":"도하 — 「‘주전자처럼 끓는다’는 ‘처럼’이 있으니 직유법이야.」","mis":"K6-2-u6-X11"},{"t":"이서 — 「‘난롯가처럼 둥글다’도 직유법이야.」","mis":"K6-2-u6-X11"}],"explanation":["도하와 이서는 바르게 가렸어요.","「처럼」이 없이 그것이라고 말하면 은유법이에요.","보람은 둘을 바꾸어 말했어요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#5','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C5',3,'ox','auto','「운동장이 앞으로 뛰어온다」는 운동장이 실제로 움직였다는 뜻이에요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":5,"concept":"K6-2-u6-C5","difficulty":3,"kind":"ox","stem":"「운동장이 앞으로 뛰어온다」는 운동장이 실제로 움직였다는 뜻이에요.","answer":"X","reason_options":[{"t":"달리기 시작하자 운동장이 밀려오듯 느껴진 마음을 나타냈기 때문에","correct":true},{"t":"시에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["운동장은 실제로 움직이지 않아요.","말하는 이가 힘껏 달리고 있어요.","그 느낌을 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#6','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C9',3,'match','auto','「우리 집 소리」의 표현과 그것을 느낀 감각을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C9","difficulty":3,"kind":"match","stem":"「우리 집 소리」의 표현과 그것을 느낀 감각을 이으세요.","pairs":[{"l":"서둘러, 서둘러","r":"들은 것"},{"l":"시계 초침이 혼자 돈다","r":"본 것"},{"l":"난롯가처럼 따뜻하다","r":"빗댄 것"}],"mis":"K6-2-u6-X12","explanation":["서두르는 말소리는 들은 것이에요.","초침이 도는 모습은 본 것이에요.","난롯가는 다른 것에 빗댄 거예요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#7','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C6',3,'mc','auto','㉮와 시 「바통」을 견주었을 때, 「바통」에만 있는 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X12']::text[],false,'{"seq":7,"concept":"K6-2-u6-C6","difficulty":3,"kind":"mc","stem":"㉮와 시 「바통」을 견주었을 때, 「바통」에만 있는 것은 어느 것인가요?","options":[{"t":"걱정하는 마음을 「백 번은 미끄러졌다」로 빗댄 표현","correct":true},{"t":"「바통을 놓칠까 봐 걱정이 되었다」는 문장","mis":"K6-2-u6-X09"},{"t":"겪은 일을 처음부터 끝까지 차례대로 적은 것","mis":"K6-2-u6-X09"},{"t":"「심장이 빨리 뛰었다」는 문장","mis":"K6-2-u6-X12"}],"explanation":["걱정되었다 · 심장이 뛰었다는 ㉮에 있어요.","차례대로 다 적은 것도 ㉮예요.","시는 마음을 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["오늘 운동회에서 이어달리기를 했다. 내 차례를 기다리는 동안","손에 땀이 많이 났다. 앞 주자가 달려오는 것을 보니","심장이 빨리 뛰었다. 바통을 놓칠까 봐 걱정이 되었다.","바통을 받고 달리니 걱정이 사라졌다."],"title":"㉮ 같은 경험을 그대로 적은 글 (㉯는 시 「바통」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#8','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',4,'mc','auto','「연과 행 · 짧게 눌러 담기 · 빗대기」를 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X03']::text[],false,'{"seq":8,"concept":"K6-2-u6-C10","difficulty":4,"kind":"mc","stem":"「연과 행 · 짧게 눌러 담기 · 빗대기」를 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"시를 생생하게 하는 방법이지만, 지켜야 할 규칙은 아니어서 마음에 알맞게 골라 쓴다","correct":true},{"t":"셋 가운데 하나라도 빠지면 시가 아니다","mis":"K6-2-u6-X13"},{"t":"셋을 모두 많이 쓸수록 좋은 시다","mis":"K6-2-u6-X03"},{"t":"셋은 일기를 쓸 때 지키는 규칙이다","mis":"K6-2-u6-X13"}],"explanation":["셋 다 시의 특성이에요.","그래도 규칙이 아니라 방법이에요.","마음에 알맞게 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#9','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C7',4,'essay','teacher','「우리 집 소리」에서 빗댄 표현 하나를 골라 무엇을 무엇에 빗대었는지, 두 대상이 어떤 점에서 비슷한지 쓰고, 그 표현이 직유법인지 은유법인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C7","difficulty":4,"kind":"essay","stem":"「우리 집 소리」에서 빗댄 표현 하나를 골라 무엇을 무엇에 빗대었는지, 두 대상이 어떤 점에서 비슷한지 쓰고, 그 표현이 직유법인지 은유법인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「아침 / 우리 집은 주전자처럼 끓는다」는 아침의 우리 집을 끓는 주전자에 빗대었다. 아침에 모두 서두르느라 바쁘고 시끄러운 모습이 김을 내며 끓는 주전자처럼 뜨겁고 바쁜 기운이 넘친다는 점에서 비슷하다. 「처럼」을 써서 두 대상을 바로 견주었으므로 직유법이다.","scoring_points":["무엇을 무엇에 빗대었는지 썼는가","두 대상의 비슷한 점을 썼는가","직유법 · 은유법을 까닭과 함께 가렸는가"]},"explanation":["빗댄 두 대상을 찾아요.","닮은 점을 말로 옮겨요.","「처럼」이 있는지 봐요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#10','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C5',4,'essay','teacher','시 「바통」에서 가장 인상 깊은 표현을 하나 골라 어떤 장면이 떠오르는지 쓰고, 그 표현이 말하는 이의 어떤 마음을 나타내는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C5","difficulty":4,"kind":"essay","stem":"시 「바통」에서 가장 인상 깊은 표현을 하나 골라 어떤 장면이 떠오르는지 쓰고, 그 표현이 말하는 이의 어떤 마음을 나타내는지 쓰세요.","answer_guide":{"answer":"예: 「호루라기 소리보다 / 내 심장이 먼저 울린다」. 출발 신호가 울리기도 전에 내 차례를 기다리며 가슴이 쿵쾅거리는 장면이 떠오른다. 실제로 심장이 소리를 낸 것이 아니라, 그만큼 떨리고 긴장된 마음을 나타낸 표현이다.","scoring_points":["표현을 하나 골랐는가","떠오르는 장면을 썼는가","실제 일이 아니라 마음으로 읽었는가"]},"explanation":["장면을 머릿속에 그려요.","실제로 일어난 일인지 따져요.","마음을 나타낸 말로 읽어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#1','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C7',1,'mc','auto','시 「이단 뛰기」에서 「새가 된다」는 무엇을 나타낸 표현인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C7","difficulty":1,"kind":"mc","stem":"시 「이단 뛰기」에서 「새가 된다」는 무엇을 나타낸 표현인가요?","options":[{"t":"줄을 두 번 넘는 동안 몸이 잠깐 떠 있는 모습","correct":true},{"t":"말하는 이가 새를 기르고 있다는 뜻","mis":"K6-2-u6-X08"},{"t":"비행기를 타고 날아 본 경험","mis":"K6-2-u6-X07"},{"t":"창밖으로 새가 날아간 모습","mis":"K6-2-u6-X08"}],"explanation":["이단 뛰기를 할 때 몸을 떠올려요.","몸이 바닥에서 잠깐 떠요.","그 모습을 새에 빗대었어요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#2','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',1,'mc','auto','시를 쓰기 전에 가장 먼저 할 일은 무엇인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X03','K6-2-u6-X15']::text[],false,'{"seq":2,"concept":"K6-2-u6-C11","difficulty":1,"kind":"mc","stem":"시를 쓰기 전에 가장 먼저 할 일은 무엇인가요?","options":[{"t":"시로 쓰고 싶은 경험 고르기","correct":true},{"t":"제목을 멋있게 정하기","mis":"K6-2-u6-X18"},{"t":"빗댄 표현을 다섯 개 정하기","mis":"K6-2-u6-X03"},{"t":"시를 몇 줄로 쓸지 정하기","mis":"K6-2-u6-X15"}],"explanation":["무엇을 쓸지부터 정해요.","그다음 묻고 답하며 자세히 떠올려요.","생각그물에 모으고 남길 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#3','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',1,'ox','auto','생각그물에 모은 것은 하나도 빠뜨리지 않고 시에 다 넣어야 해요.',ARRAY['K6-2-u6-X16']::text[],false,'{"seq":3,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"생각그물에 모은 것은 하나도 빠뜨리지 않고 시에 다 넣어야 해요.","answer":"X","reason_options":[{"t":"다 넣으면 어느 순간이 중요한지 알 수 없는 목록이 되기 때문에","correct":true},{"t":"빠뜨린 것이 있으면 좋은 시가 될 수 없기 때문에","mis":"K6-2-u6-X16"}],"mis":"K6-2-u6-X16","explanation":["시는 넣는 일보다 버리는 일이 커요.","인상 깊은 순간만 남겨요.","그래야 마음이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#4','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',1,'mc','auto','생각그물에서 「탁, 탁 하는 두 번의 소리」는 어느 칸에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"생각그물에서 「탁, 탁 하는 두 번의 소리」는 어느 칸에 들어가나요?","options":[{"t":"들은 것","correct":true},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"만진 것","mis":"K6-2-u6-X12"},{"t":"빗댈 것","mis":"K6-2-u6-X12"}],"explanation":["귀로 들은 소리예요.","줄이 지나가는 모습은 본 것이에요.","미끄러운 손잡이는 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#5','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',2,'mc','auto','경험을 자세히 떠올리는 데 도움이 되는 물음은 어느 것인가요?',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":5,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"경험을 자세히 떠올리는 데 도움이 되는 물음은 어느 것인가요?","options":[{"t":"「그 순간을 무엇에 빗댈 수 있을까?」","correct":true},{"t":"「그 일은 몇 시 몇 분에 일어났어?」","mis":"K6-2-u6-X15"},{"t":"「시를 몇 줄로 쓸 생각이야?」","mis":"K6-2-u6-X15"},{"t":"「줄넘기는 얼마에 샀어?」","mis":"K6-2-u6-X15"}],"explanation":["시각 · 줄 수 · 값은 경험 속으로 데려가지 않아요.","그 순간을 다시 떠올리게 하는 물음이 좋아요.","빗댈 것을 물으면 표현이 생겨요."],"asset":{"type":"speech","turns":[{"who":"하진","text":"나는 이단 뛰기 처음 성공한 날을 쓸래."},{"who":"준하","text":"그때 제일 기억에 남는 순간이 언제였어?"},{"who":"하진","text":"두 번째 탁 소리가 났을 때. 그 전까지는 계속 한 번만 났거든."},{"who":"준하","text":"그 순간 몸은 어땠는데? 무엇에 빗댈 수 있을 것 같아?"},{"who":"하진","text":"아, 잠깐 붕 떠 있었어. 새 같았던 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#6','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',2,'match','auto','생각그물의 칸과 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C12","difficulty":2,"kind":"match","stem":"생각그물의 칸과 알맞은 내용을 이으세요.","pairs":[{"l":"본 것","r":"빠르게 지나가는 줄"},{"l":"만진 것","r":"땀으로 미끄러운 손잡이"},{"l":"빗댈 것","r":"잠깐 떠 있는 몸 — 새"}],"mis":"K6-2-u6-X12","explanation":["눈으로 본 것을 가려요.","손으로 만진 것을 가려요.","다른 것에 빗댈 것을 가려요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#7','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',2,'mc','auto','㉯ 시 「이단 뛰기」가 ㉮보다 더 시답게 읽히는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X17','K6-2-u6-X16']::text[],false,'{"seq":7,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"㉯ 시 「이단 뛰기」가 ㉮보다 더 시답게 읽히는 까닭은 무엇인가요?","options":[{"t":"인상 깊은 순간만 남겨 그 마음이 또렷해졌기 때문에","correct":true},{"t":"빗댄 표현을 더 많이 넣었기 때문에","mis":"K6-2-u6-X17"},{"t":"시는 무조건 짧아야 하기 때문에","mis":"K6-2-u6-X17"},{"t":"생각그물을 빠짐없이 다 넣었기 때문에","mis":"K6-2-u6-X16"}],"explanation":["㉮는 빠뜨린 것이 없어요.","그런데 무엇이 중요한지 알 수 없어요.","㉯는 버렸기 때문에 남은 것이 또렷해요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#8','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C14',2,'ox','auto','시의 제목은 맨 처음에 붙여도 되고 다 쓴 뒤에 붙여도 돼요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":8,"concept":"K6-2-u6-C14","difficulty":2,"kind":"ox","stem":"시의 제목은 맨 처음에 붙여도 되고 다 쓴 뒤에 붙여도 돼요.","answer":"O","reason_options":[{"t":"언제 붙이든 시에 담긴 마음이 드러나면 되기 때문에","correct":true},{"t":"제목은 반드시 시를 쓰기 전에 정해야 하기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["제목을 먼저 정해도 돼요.","다 쓰고 붙여도 돼요.","고개가 끄덕여지는 제목이면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#9','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C15',2,'mc','auto','시를 고쳐 쓸 때 볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":9,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 고쳐 쓸 때 볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"없어도 되는 줄이 남아 있지는 않은가","correct":true},{"t":"빗댄 표현이 다섯 개를 넘는가","mis":"K6-2-u6-X19"},{"t":"글씨를 예쁘게 썼는가","mis":"K6-2-u6-X19"},{"t":"줄 수가 친구 시보다 많은가","mis":"K6-2-u6-X19"}],"explanation":["개수와 글씨는 볼 것이 아니에요.","전하려던 마음이 드러나는지 봐요.","없어도 되는 줄은 지워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#10','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C6',3,'mc','auto','「이단 뛰기」에서 장면이 바뀌는 곳에 연을 나눈 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X14']::text[],false,'{"seq":10,"concept":"K6-2-u6-C6","difficulty":3,"kind":"mc","stem":"「이단 뛰기」에서 장면이 바뀌는 곳에 연을 나눈 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"줄이 지나가는 순간 · 소리가 난 순간 · 성공한 순간처럼 장면이 바뀔 때마다 나누어 읽는 사람이 따라가기 쉽게 하려고","correct":true},{"t":"연이 많을수록 좋은 시가 되기 때문에","mis":"K6-2-u6-X13"},{"t":"아무 데서나 나누어도 상관없기 때문에","mis":"K6-2-u6-X14"},{"t":"한 연에는 반드시 두 줄만 써야 하기 때문에","mis":"K6-2-u6-X13"}],"explanation":["연은 장면이 바뀌는 곳에서 나눠요.","읽는 사람이 장면을 따라가요.","정해진 줄 수 규칙은 없어요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#1','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C14',2,'mc','auto','「이단 뛰기」의 마음이 가장 잘 드러나는 제목은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":1,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"「이단 뛰기」의 마음이 가장 잘 드러나는 제목은 어느 것인가요?","options":[{"t":"백한 번째 새","correct":true},{"t":"줄넘기를 한 날","mis":"K6-2-u6-X18"},{"t":"체육 시간","mis":"K6-2-u6-X18"},{"t":"줄넘기 손잡이의 색깔","mis":"K6-2-u6-X18"}],"explanation":["겪은 일 그대로의 제목도 쓸 수 있어요.","그런데 마음이 잘 드러나지 않아요.","드디어 새가 된 순간이 담긴 제목이 좋아요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#2','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',2,'mc','auto','시 쓰기를 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X16','K6-2-u6-X15']::text[],false,'{"seq":2,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"시 쓰기를 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 고르기 → 묻고 답하며 떠올리기 → 생각그물로 모으기 → 남길 것 고르기","correct":true},{"t":"제목 정하기 → 빗댄 표현 다섯 개 정하기 → 경험 고르기 → 쓰기","mis":"K6-2-u6-X18"},{"t":"생각그물 그리기 → 모두 넣기 → 경험 고르기 → 쓰기","mis":"K6-2-u6-X16"},{"t":"줄 수 정하기 → 쓰기 → 경험 고르기 → 고치기","mis":"K6-2-u6-X15"}],"explanation":["무엇을 쓸지 먼저 골라요.","묻고 답하며 자세히 떠올려요.","모은 것에서 남길 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#3','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C12',3,'mc','auto','하진이의 생각그물에서 다른 칸으로 잘못 옮기면 안 되는 것끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":3,"concept":"K6-2-u6-C12","difficulty":3,"kind":"mc","stem":"하진이의 생각그물에서 다른 칸으로 잘못 옮기면 안 되는 것끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"「땀으로 미끄러운 손잡이」 — 만진 것","correct":true},{"t":"「탁, 탁 하는 두 번의 소리」 — 본 것","mis":"K6-2-u6-X12"},{"t":"「발밑을 지나가는 줄」 — 들은 것","mis":"K6-2-u6-X12"},{"t":"「잠깐 떠 있는 몸 → 새」 — 만진 것","mis":"K6-2-u6-X12"}],"explanation":["소리는 들은 것이에요.","줄은 눈으로 본 것이에요.","손잡이는 손으로 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#4','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',3,'ox','auto','「그때 마음이 어떻게 움직였니?」는 경험을 자세히 떠올리게 하는 좋은 물음이에요.',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":4,"concept":"K6-2-u6-C11","difficulty":3,"kind":"ox","stem":"「그때 마음이 어떻게 움직였니?」는 경험을 자세히 떠올리게 하는 좋은 물음이에요.","answer":"O","reason_options":[{"t":"그 경험 속으로 다시 들어가 마음을 떠올리게 하기 때문에","correct":true},{"t":"시를 몇 줄로 쓸지 정하게 해 주기 때문에","mis":"K6-2-u6-X15"}],"mis":"K6-2-u6-X15","explanation":["좋은 물음은 그 순간으로 데려가요.","마음이 움직인 곳을 찾게 해요.","흐릿한 기억이 또렷해져요."],"asset":{"type":"speech","turns":[{"who":"하진","text":"나는 이단 뛰기 처음 성공한 날을 쓸래."},{"who":"준하","text":"그때 제일 기억에 남는 순간이 언제였어?"},{"who":"하진","text":"두 번째 탁 소리가 났을 때. 그 전까지는 계속 한 번만 났거든."},{"who":"준하","text":"그 순간 몸은 어땠는데? 무엇에 빗댈 수 있을 것 같아?"},{"who":"하진","text":"아, 잠깐 붕 떠 있었어. 새 같았던 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#5','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',3,'error','auto','㉮와 ㉯를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X09']::text[],false,'{"seq":5,"concept":"K6-2-u6-C13","difficulty":3,"kind":"error","stem":"㉮와 ㉯를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하진 — 「㉮는 빠뜨린 것이 없으니까 ㉯보다 더 좋은 시야.」","correct":true,"mis_target":"K6-2-u6-X16"},{"t":"준하 — 「㉯는 버렸기 때문에 남은 것이 또렷해.」","mis":"K6-2-u6-X16"},{"t":"지오 — 「㉮는 어느 순간이 중요한지 알 수 없어.」","mis":"K6-2-u6-X09"}],"explanation":["준하와 지오는 바르게 말했어요.","하진은 다 넣어야 좋은 시라고 여겼어요.","시는 버리는 일이 더 커요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#6','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C15',3,'match','auto','고쳐 쓸 때 본 것과 그렇게 고친 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C15","difficulty":3,"kind":"match","stem":"고쳐 쓸 때 본 것과 그렇게 고친 방법을 이으세요.","pairs":[{"l":"전하려던 마음이 흐릿하다","r":"마음이 드러난 순간을 앞으로 옮긴다"},{"l":"장면이 바뀌는데 한 연에 붙어 있다","r":"장면이 바뀌는 곳에서 연을 나눈다"},{"l":"소리 내어 읽으니 걸리는 줄이 있다","r":"걸리는 줄을 고치거나 지운다"}],"mis":"K6-2-u6-X19","explanation":["마음이 드러나게 고쳐요.","연을 장면에 맞게 나눠요.","소리 내어 읽고 걸리는 곳을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#7','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C14',3,'mc','auto','시 「우산 하나」의 제목에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X18']::text[],false,'{"seq":7,"concept":"K6-2-u6-C14","difficulty":3,"kind":"mc","stem":"시 「우산 하나」의 제목에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"우산이 하나뿐이어서 친구 쪽으로 기울인 마음이 제목에서부터 떠오른다","correct":true},{"t":"제목에 빗댄 표현이 없어서 아쉽다","mis":"K6-2-u6-X03"},{"t":"제목은 쓰기 전에 정해야 하는데 다 쓴 뒤 붙인 것 같아 잘못이다","mis":"K6-2-u6-X18"},{"t":"제목이 짧아서 좋은 제목이라고 할 수 없다","mis":"K6-2-u6-X18"}],"explanation":["제목에 빗댄 표현이 꼭 있어야 하지는 않아요.","언제 붙여도 괜찮아요.","시를 읽고 고개가 끄덕여지면 좋은 제목이에요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#8','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',4,'mc','auto','하진이가 생각그물에서 「이마에 땀이 났다」와 「친구들이 세어 주었다」를 시에서 뺀 것을 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17','K6-2-u6-X03']::text[],false,'{"seq":8,"concept":"K6-2-u6-C13","difficulty":4,"kind":"mc","stem":"하진이가 생각그물에서 「이마에 땀이 났다」와 「친구들이 세어 주었다」를 시에서 뺀 것을 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"두 번째 소리가 나며 새가 된 순간이 또렷해지도록 덜 중요한 것을 버린 것이다","correct":true},{"t":"빠뜨린 것이 생겨 좋은 시가 될 수 없다","mis":"K6-2-u6-X16"},{"t":"시는 무조건 짧아야 하니 뺀 것이다","mis":"K6-2-u6-X17"},{"t":"빗댄 표현이 아니라서 뺀 것이다","mis":"K6-2-u6-X03"}],"explanation":["버린 것은 잘못 빠뜨린 것이 아니에요.","짧게 하려는 것이 목적도 아니에요.","남길 순간이 또렷해지도록 골랐어요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#9','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',4,'essay','teacher','내가 겪은 일 하나를 정해, 짝이 경험을 자세히 떠올리게 도와줄 물음 세 가지를 쓰고, 그 물음이 왜 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C11","difficulty":4,"kind":"essay","stem":"내가 겪은 일 하나를 정해, 짝이 경험을 자세히 떠올리게 도와줄 물음 세 가지를 쓰고, 그 물음이 왜 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 겪은 일 — 처음으로 혼자 김밥을 만 날. 물음 ① 「가장 기억에 남는 순간은 언제였어?」 ② 「그때 손에 무엇이 느껴졌어?」 ③ 「그 순간을 무엇에 빗댈 수 있을까?」 이런 물음은 그 경험 속으로 다시 들어가게 해 줘서, 흐릿하던 순간과 감각, 마음이 또렷하게 떠오르게 한다. 몇 시였는지나 몇 줄로 쓸지 같은 물음은 도움이 되지 않는다.","scoring_points":["겪은 일을 하나 정했는가","경험 속으로 들어가게 하는 물음을 세 가지 썼는가","물음이 도움이 되는 까닭을 썼는가"]},"explanation":["가장 기억에 남는 순간을 물어요.","본 것 · 들은 것 · 만진 것을 물어요.","빗댈 것과 마음을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#10','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',4,'essay','teacher','㉮처럼 생각그물을 다 넣은 시와 ㉯처럼 인상 깊은 것만 고른 시는 읽는 사람에게 어떻게 다르게 읽히는지 쓰고, 시를 쓸 때 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C13","difficulty":4,"kind":"essay","stem":"㉮처럼 생각그물을 다 넣은 시와 ㉯처럼 인상 깊은 것만 고른 시는 읽는 사람에게 어떻게 다르게 읽히는지 쓰고, 시를 쓸 때 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: ㉮는 빠뜨린 것이 없지만 줄, 소리, 땀, 친구들이 모두 같은 무게로 늘어서 있어 어느 순간이 중요한지 알 수 없는 목록처럼 읽힌다. ㉯는 줄이 지나가는 사이, 두 번째 소리, 백한 번째에 새가 된 순간만 남겨 처음 성공했을 때의 마음이 또렷하게 읽힌다. 그래서 시를 쓸 때에는 생각그물에서 인상 깊은 것만 골라 남기고 나머지는 과감히 버려야 한다.","scoring_points":["㉮가 목록처럼 읽히는 까닭을 썼는가","㉯에서 마음이 또렷해진 까닭을 썼는가","고르고 버려야 한다고 썼는가"]},"explanation":["무엇이 남는지 견주어요.","버린 덕분에 또렷해져요.","넣는 일보다 버리는 일이에요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#1','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',1,'mc','auto','낭송을 준비할 때 가장 먼저 정할 것은 무엇인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":1,"concept":"K6-2-u6-C16","difficulty":1,"kind":"mc","stem":"낭송을 준비할 때 가장 먼저 정할 것은 무엇인가요?","options":[{"t":"듣는 사람에게 꼭 전하고 싶은 마음","correct":true},{"t":"배경 음악으로 쓸 노래","mis":"K6-2-u6-X22"},{"t":"입고 나갈 옷","mis":"K6-2-u6-X20"},{"t":"시를 다 외웠는지","mis":"K6-2-u6-X20"}],"explanation":["전하고 싶은 마음을 먼저 정해요.","그 마음에 어울리는 목소리와 속도를 찾아요.","음악은 그다음에 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#2','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',1,'ox','auto','배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":2,"concept":"K6-2-u6-C17","difficulty":1,"kind":"ox","stem":"배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.","answer":"X","reason_options":[{"t":"음악이 목소리를 덮으면 시의 마음이 들리지 않기 때문에","correct":true},{"t":"음악이 커야 낭송이 멋있게 들리기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["배경 음악은 작게 깔아요.","듣는 사람은 시를 끝까지 들어야 해요.","음악은 돕는 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#3','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',1,'mc','auto','친구의 낭송을 들을 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":3,"concept":"K6-2-u6-C18","difficulty":1,"kind":"mc","stem":"친구의 낭송을 들을 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"낭송하는 사람을 바라보며 듣는다","correct":true},{"t":"옆 친구와 감상을 그때그때 이야기한다","mis":"K6-2-u6-X24"},{"t":"틀린 글자를 찾아 두었다가 알려 준다","mis":"K6-2-u6-X24"},{"t":"내 차례에 읽을 시를 미리 읽어 둔다","mis":"K6-2-u6-X24"}],"explanation":["낭송회는 함께 만들어요.","바라보며 들어요.","시와 관련 있는 내 경험을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#4','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',1,'mc','auto','낭송의 목표로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":4,"concept":"K6-2-u6-C19","difficulty":1,"kind":"mc","stem":"낭송의 목표로 알맞은 것은 어느 것인가요?","options":[{"t":"그 시의 마음이 듣는 사람에게 건너가는 것","correct":true},{"t":"가장 큰 목소리로 읽는 것","mis":"K6-2-u6-X21"},{"t":"화려하게 꾸며 멋있게 들리는 것","mis":"K6-2-u6-X22"},{"t":"가장 빨리 끝까지 읽는 것","mis":"K6-2-u6-X20"}],"explanation":["크게 읽는 것이 목표가 아니에요.","화려한 꾸밈도 목표가 아니에요.","시의 마음이 건너가게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#5','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',2,'match','auto','「이단 뛰기」의 부분과 알맞은 낭송 방법을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C16","difficulty":2,"kind":"match","stem":"「이단 뛰기」의 부분과 알맞은 낭송 방법을 이으세요.","pairs":[{"l":"줄이 두 번 지나가는 그 짧은 사이","r":"숨을 참듯 낮고 느리게"},{"l":"탁, 탁 / 성공이다","r":"또렷하고 빠르게"},{"l":"백 번을 걸리고 백한 번째에","r":"한 음절씩 힘을 실어 천천히"}],"mis":"K6-2-u6-X20","explanation":["숨죽인 순간은 낮고 느리게 읽어요.","성공한 순간은 또렷하고 빠르게 읽어요.","버틴 마음은 힘을 실어 천천히 읽어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#6','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',2,'mc','auto','낭송에 효과음을 쓸 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":6,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"낭송에 효과음을 쓸 때 알맞은 것은 어느 것인가요?","options":[{"t":"시의 장면과 맞닿은 소리를 아주 짧게 쓴다","correct":true},{"t":"여러 가지 소리를 쉬지 않고 계속 튼다","mis":"K6-2-u6-X22"},{"t":"시와 상관없이 재미있는 소리를 고른다","mis":"K6-2-u6-X22"},{"t":"목소리 대신 효과음으로 시를 들려준다","mis":"K6-2-u6-X22"}],"explanation":["효과음은 장면과 맞닿은 소리여야 해요.","아주 짧게 써요.","낭송을 대신하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#7','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',2,'ox','auto','마음만 담으면 들리지 않을 만큼 작게 읽어도 좋은 낭송이에요.',ARRAY['K6-2-u6-X23']::text[],false,'{"seq":7,"concept":"K6-2-u6-C19","difficulty":2,"kind":"ox","stem":"마음만 담으면 들리지 않을 만큼 작게 읽어도 좋은 낭송이에요.","answer":"X","reason_options":[{"t":"뒤에 앉은 사람까지 들려야 마음이 건너가기 때문에","correct":true},{"t":"작게 읽을수록 마음이 깊게 전해지기 때문에","mis":"K6-2-u6-X23"}],"mis":"K6-2-u6-X23","explanation":["들리지 않으면 마음도 건너가지 않아요.","뒤에 앉은 사람까지 들리게 읽어요.","부분마다 마음에 맞는 크기로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#8','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',2,'mc','auto','낭송을 들은 뒤 해 줄 조언으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X21','K6-2-u6-X24']::text[],false,'{"seq":8,"concept":"K6-2-u6-C18","difficulty":2,"kind":"mc","stem":"낭송을 들은 뒤 해 줄 조언으로 알맞은 것은 어느 것인가요?","options":[{"t":"「탁, 탁」 부분을 조금 더 빠르게 읽으면 그 순간이 더 살아날 것 같아","correct":true},{"t":"그냥 잘했어. 다음에도 그렇게 해","mis":"K6-2-u6-X25"},{"t":"목소리를 무조건 더 크게 내면 돼","mis":"K6-2-u6-X21"},{"t":"글자 하나 틀린 것만 고치면 돼","mis":"K6-2-u6-X24"}],"explanation":["잘했어만으로는 무엇을 바꿀지 몰라요.","무조건 크게는 알맞은 조언이 아니에요.","어느 부분을 어떻게 할지 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#9','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',2,'mc','auto','「이단 뛰기」 낭송 계획에서 전하고 싶은 마음은 무엇인가요?',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":9,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"「이단 뛰기」 낭송 계획에서 전하고 싶은 마음은 무엇인가요?","options":[{"t":"백 번을 걸리고도 다시 뛰었던 버티는 마음","correct":true},{"t":"줄넘기가 쉽다는 마음","mis":"K6-2-u6-X20"},{"t":"친구들보다 잘한다고 뽐내는 마음","mis":"K6-2-u6-X20"},{"t":"체육 시간이 지루했던 마음","mis":"K6-2-u6-X20"}],"explanation":["계획의 맨 위에 적혀 있어요.","백 번을 걸리고도 다시 뛰었어요.","그 마음에 맞춰 목소리를 정했어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#10','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C21',3,'error','auto','낭송에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X23']::text[],false,'{"seq":10,"concept":"K6-2-u6-C21","difficulty":3,"kind":"error","stem":"낭송에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태린 — 「처음부터 끝까지 가장 큰 목소리로 읽으면 잘하는 낭송이야.」","correct":true,"mis_target":"K6-2-u6-X21"},{"t":"하진 — 「부분마다 마음에 맞는 크기로 읽어야 해.」","mis":"K6-2-u6-X21"},{"t":"준하 — 「뒤에 앉은 사람까지는 들려야 해.」","mis":"K6-2-u6-X23"}],"explanation":["하진과 준하는 바르게 말했어요.","태린은 마음과 상관없이 크게만 읽으려 했어요.","크기는 마음을 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#1','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',2,'mc','auto','낭송할 때 영상이나 그림을 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":1,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"낭송할 때 영상이나 그림을 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"시의 장면을 떠올리는 데 도움이 될 만큼만 쓴다","correct":true},{"t":"화려한 영상을 쉬지 않고 바꾸어 눈을 사로잡는다","mis":"K6-2-u6-X22"},{"t":"영상만 보여 주고 낭송은 하지 않는다","mis":"K6-2-u6-X22"},{"t":"시와 상관없는 재미있는 그림을 고른다","mis":"K6-2-u6-X22"}],"explanation":["영상이 화려하면 낭송의 흐름을 방해해요.","낭송을 대신하지 않아요.","장면을 떠올리는 데 도움이 될 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#2','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',2,'mc','auto','「이단 뛰기」 낭송 계획에서 ㉮ 부분을 숨을 참듯 낮고 느리게 읽는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X20','K6-2-u6-X21']::text[],false,'{"seq":2,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"「이단 뛰기」 낭송 계획에서 ㉮ 부분을 숨을 참듯 낮고 느리게 읽는 까닭은 무엇인가요?","options":[{"t":"줄이 지나가는 짧은 사이, 숨죽인 긴장된 마음을 따라가기 때문에","correct":true},{"t":"모든 부분을 같은 목소리로 읽어야 하기 때문에","mis":"K6-2-u6-X20"},{"t":"낮게 읽어야 언제나 낭송이 멋있기 때문에","mis":"K6-2-u6-X21"},{"t":"㉮가 가장 긴 부분이기 때문에","mis":"K6-2-u6-X20"}],"explanation":["목소리는 그 부분의 마음을 따라가요.","숨죽인 순간이에요.","그래서 낮고 느리게 읽어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#3','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',3,'ox','auto','「이단 뛰기」는 처음부터 끝까지 같은 목소리와 속도로 읽는 것이 가장 알맞아요.',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":3,"concept":"K6-2-u6-C16","difficulty":3,"kind":"ox","stem":"「이단 뛰기」는 처음부터 끝까지 같은 목소리와 속도로 읽는 것이 가장 알맞아요.","answer":"X","reason_options":[{"t":"부분마다 담긴 마음이 달라 목소리와 속도도 달라지기 때문에","correct":true},{"t":"같은 속도로 읽어야 듣는 사람이 헷갈리지 않기 때문에","mis":"K6-2-u6-X20"}],"mis":"K6-2-u6-X20","explanation":["숨죽인 순간과 성공한 순간은 마음이 달라요.","목소리는 그 마음을 따라가요.","부분마다 크기와 속도를 정해요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#4','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',3,'error','auto','친구의 낭송을 듣는 모습이에요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['K6-2-u6-X24','K6-2-u6-X25']::text[],false,'{"seq":4,"concept":"K6-2-u6-C18","difficulty":3,"kind":"error","stem":"친구의 낭송을 듣는 모습이에요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"나은 — 낭송하는 동안 옆 친구와 감상을 이야기했다","correct":true,"mis_target":"K6-2-u6-X24"},{"t":"도하 — 낭송하는 친구를 바라보며 들었다","mis":"K6-2-u6-X24"},{"t":"이서 — 끝난 뒤 좋았던 부분을 짚어 말해 주었다","mis":"K6-2-u6-X25"}],"explanation":["도하와 이서는 잘 들었어요.","나은이는 듣는 동안 이야기를 해 집중을 흐렸어요.","이야기는 끝난 뒤에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#5','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C19',3,'mc','auto','「낭송을 잘한다는 것」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X23']::text[],false,'{"seq":5,"concept":"K6-2-u6-C19","difficulty":3,"kind":"mc","stem":"「낭송을 잘한다는 것」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뒤에 앉은 사람까지 들리게, 부분마다 마음에 맞는 크기로 읽어 시의 마음이 건너가게 하는 것","correct":true},{"t":"마음과 상관없이 무조건 크게 읽는 것","mis":"K6-2-u6-X21"},{"t":"음악과 영상을 많이 넣어 화려하게 꾸미는 것","mis":"K6-2-u6-X22"},{"t":"마음만 담으면 작게 읽어도 되는 것","mis":"K6-2-u6-X23"}],"explanation":["작게도, 무조건 크게도 아니에요.","꾸밈이 시를 덮으면 안 돼요.","마음이 건너가는 것이 목표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#6','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',3,'match','auto','낭송을 돕는 것과 알맞은 쓰는 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C17","difficulty":3,"kind":"match","stem":"낭송을 돕는 것과 알맞은 쓰는 방법을 이으세요.","pairs":[{"l":"효과음","r":"시의 장면과 맞닿은 소리를 아주 짧게"},{"l":"배경 음악","r":"분위기에 어울리는 것을 목소리보다 작게"},{"l":"영상이나 그림","r":"장면을 떠올리는 데 도움이 될 만큼만"}],"mis":"K6-2-u6-X22","explanation":["효과음은 짧게 써요.","배경 음악은 작게 깔아요.","영상은 도움이 될 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#7','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',3,'mc','auto','낭송회를 「낭송하는 사람과 듣는 사람이 함께 만든다」고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X24','K6-2-u6-X25']::text[],false,'{"seq":7,"concept":"K6-2-u6-C18","difficulty":3,"kind":"mc","stem":"낭송회를 「낭송하는 사람과 듣는 사람이 함께 만든다」고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 바라보며 들어 주고 구체적으로 조언해야 낭송하는 사람의 마음이 건너가고 다음에 더 나아지기 때문에","correct":true},{"t":"듣는 사람도 한 줄씩 함께 소리 내어 읽어야 하기 때문에","mis":"K6-2-u6-X24"},{"t":"듣는 사람이 틀린 글자를 찾아 주어야 하기 때문에","mis":"K6-2-u6-X24"},{"t":"듣는 사람이 「잘했어」라고만 말해 주면 되기 때문에","mis":"K6-2-u6-X25"}],"explanation":["듣는 사람이 있어야 낭송회가 돼요.","바라보며 집중해서 들어요.","구체적인 조언이 다음을 키워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#8','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',4,'mc','auto','「우산 하나」를 낭송하며 쓸 배경 음악으로 가장 알맞은 계획은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":8,"concept":"K6-2-u6-C17","difficulty":4,"kind":"mc","stem":"「우산 하나」를 낭송하며 쓸 배경 음악으로 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"빗소리와 어울리는 잔잔한 음악을 목소리보다 작게 깔고, 마지막 연에서는 음악을 멈춘다","correct":true},{"t":"모두가 아는 신나는 유행 노래를 목소리보다 크게 튼다","mis":"K6-2-u6-X22"},{"t":"효과음 여러 개를 쉬지 않고 계속 튼다","mis":"K6-2-u6-X22"},{"t":"음악만 틀고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["분위기에 어울리는 음악을 골라요.","목소리보다 작게 깔아요.","젖은 어깨의 마음이 들리게 비워 두기도 해요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#9','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',4,'essay','teacher','「우유갑」을 낭송한다고 생각하고, 전하고 싶은 마음을 한 문장으로 쓴 뒤, 첫 연과 마지막 연을 각각 어떤 목소리와 속도로 읽을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"「우유갑」을 낭송한다고 생각하고, 전하고 싶은 마음을 한 문장으로 쓴 뒤, 첫 연과 마지막 연을 각각 어떤 목소리와 속도로 읽을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 전하고 싶은 마음 — 엄마한테 삐친 마음이 조금은 풀리기를 바라는 마음. 첫 연 「우유갑 모서리를 / 손톱으로 톡, 톡」은 손끝으로 조심조심 두드리는 장면이라 작고 또렷하게, 톡, 톡을 끊어 읽는다. 마지막 연 「꼭 이만큼만 / 열렸으면」은 바라는 마음이 담겨 있어 천천히, 조금 낮추어 한 음절씩 힘을 실어 읽는다.","scoring_points":["전하고 싶은 마음을 한 문장으로 썼는가","두 연의 목소리와 속도를 정했는가","그 부분의 마음과 이어 까닭을 썼는가"]},"explanation":["마음을 먼저 정해요.","부분마다 목소리를 정해요.","까닭은 그 부분의 마음이에요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#10','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',4,'essay','teacher','친구가 「바통」을 낭송했는데, 처음부터 끝까지 같은 속도로 빠르게 읽었어요. 이 친구에게 해 줄 조언을 잘한 점 하나와 고칠 점 하나를 넣어 구체적으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C18","difficulty":4,"kind":"essay","stem":"친구가 「바통」을 낭송했는데, 처음부터 끝까지 같은 속도로 빠르게 읽었어요. 이 친구에게 해 줄 조언을 잘한 점 하나와 고칠 점 하나를 넣어 구체적으로 쓰세요.","answer_guide":{"answer":"예: 뒤에 앉은 나에게도 또렷하게 들려서 좋았어. 그런데 「바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다」는 조마조마한 마음이 담긴 부분이니까, 거기서는 조금 느리게, 숨을 고르듯 읽으면 걱정하는 마음이 더 잘 건너올 것 같아. 마지막 연은 지금처럼 빠르게 읽으면 달려 나가는 느낌이 살아날 거야.","scoring_points":["잘한 점을 구체적으로 짚었는가","고칠 부분과 방법을 함께 썼는가","그 부분의 마음과 이어 조언했는가"]},"explanation":["잘한 점부터 말해요.","어느 부분을 어떻게 할지 말해요.","까닭은 그 부분의 마음이에요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#1','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C20',1,'mc','auto','널리 알려진 이야기를 일부러 비틀어 새로운 뜻을 담아내는 것을 무엇이라고 하나요?',ARRAY['K6-2-u6-X26','K6-2-u6-X31']::text[],false,'{"seq":1,"concept":"K6-2-u6-C20","difficulty":1,"kind":"mc","stem":"널리 알려진 이야기를 일부러 비틀어 새로운 뜻을 담아내는 것을 무엇이라고 하나요?","options":[{"t":"패러디","correct":true},{"t":"표절","mis":"K6-2-u6-X26"},{"t":"일기","mis":"K6-2-u6-X31"},{"t":"낭송","mis":"K6-2-u6-X26"}],"explanation":["원래 이야기를 밝히고 일부러 바꿔요.","바뀐 곳에서 새로운 뜻이 생겨요.","이것을 패러디라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#2','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C21',1,'mc','auto','㉮에서 나무꾼이 세 도끼를 모두 받게 된 까닭은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X33']::text[],false,'{"seq":2,"concept":"K6-2-u6-C21","difficulty":1,"kind":"mc","stem":"㉮에서 나무꾼이 세 도끼를 모두 받게 된 까닭은 무엇인가요?","options":[{"t":"제 것이 아닌 도끼를 제 것이라고 하지 않아서","correct":true},{"t":"산신령이 낸 힘겨루기에서 이겨서","mis":"K6-2-u6-X07"},{"t":"세 도끼를 모두 달라고 간절히 빌어서","mis":"K6-2-u6-X33"},{"t":"이웃보다 나무를 많이 해서","mis":"K6-2-u6-X07"}],"explanation":["산신령이 무엇을 칭찬했는지 봐요.","나무꾼은 금도끼도 은도끼도 제 것이 아니라고 했어요.","사건은 정직함에서 시작돼요."],"asset":{"type":"passage","lines":["옛날 어느 산 아래 마을에 나무꾼이 살았다. 하루는 나무를 하다가","하나뿐인 쇠도끼를 산속 연못에 빠뜨렸다. 물살이 갈라지며","산신령이 나타나 금도끼와 은도끼를 들어 보였지만,","나무꾼은 둘 다 제 것이 아니라고 했다. 쇠도끼를 보고서야","「예, 그것이 제 도끼입니다.」 하고 반가워했다.","산신령은 정직함을 칭찬하며 세 도끼를 모두 주었다. 소문을 들은 이웃이","일부러 도끼를 던지고 금도끼를 제 것이라 했다가 제 도끼마저 잃었다."],"title":"㉮ 금도끼 은도끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#3','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C20',1,'ox','auto','남의 이야기를 그대로 옮기고 자기 것인 척하는 것도 패러디예요.',ARRAY['K6-2-u6-X26']::text[],false,'{"seq":3,"concept":"K6-2-u6-C20","difficulty":1,"kind":"ox","stem":"남의 이야기를 그대로 옮기고 자기 것인 척하는 것도 패러디예요.","answer":"X","reason_options":[{"t":"그대로 옮기고 자기 것인 척하는 것은 표절이기 때문에","correct":true},{"t":"널리 알려진 이야기를 썼으니 패러디이기 때문에","mis":"K6-2-u6-X26"}],"mis":"K6-2-u6-X26","explanation":["표절은 새로운 뜻이 생기지 않아요.","패러디는 원래 이야기를 밝혀요.","일부러 바꾸어 새 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#4','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C22',1,'mc','auto','㉯에서 바뀐 배경 가운데 「때」는 어느 것인가요?',ARRAY['K6-2-u6-X28','K6-2-u6-X05']::text[],false,'{"seq":4,"concept":"K6-2-u6-C22","difficulty":1,"kind":"mc","stem":"㉯에서 바뀐 배경 가운데 「때」는 어느 것인가요?","options":[{"t":"몇 해째 비가 오지 않아 마을 우물이 말라 가던 해","correct":true},{"t":"그저 옛날","mis":"K6-2-u6-X28"},{"t":"산속 연못","mis":"K6-2-u6-X05"},{"t":"나무꾼이 도끼를 빠뜨린 일","mis":"K6-2-u6-X05"}],"explanation":["㉮의 때는 그저 옛날이었어요.","산속 연못은 곳이에요.","㉯의 때는 가뭄이 든 해예요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#5','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C21',2,'mc','auto','㉯에서 나무꾼이 금도끼를 받지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"㉯에서 나무꾼이 금도끼를 받지 않은 까닭은 무엇인가요?","options":[{"t":"사람들이 몰려들면 마을의 연못이 상할까 걱정해서","correct":true},{"t":"산신령에게 벌을 받을까 봐 무서워서","mis":"K6-2-u6-X33"},{"t":"금도끼와 은도끼가 가짜인 것을 알아서","mis":"K6-2-u6-X07"},{"t":"이웃이 도끼를 빼앗을까 봐 겁이 나서","mis":"K6-2-u6-X07"}],"explanation":["나무꾼이 되물은 말을 읽어요.","마을에 마실 물이 없다고 했어요.","마을까지 생각하는 성격이 되었어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#6','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C4',2,'match','auto','요소와 ㉯에서 그 요소가 달라진 점을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C4","difficulty":2,"kind":"match","stem":"요소와 ㉯에서 그 요소가 달라진 점을 이으세요.","pairs":[{"l":"인물","r":"마을까지 함께 생각하는 사람이 되었다"},{"l":"배경","r":"가뭄이 든 해로 때가 정해졌다"},{"l":"사건","r":"상을 받는 대신 마을에 샘이 생겼다"}],"mis":"K6-2-u6-X05","explanation":["나무꾼의 생각이 넓어졌어요.","때가 가뭄이 든 해로 바뀌었어요.","일어난 일이 달라졌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#7','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C23',2,'mc','auto','㉯의 뒤에 이어 쓸 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X27']::text[],false,'{"seq":7,"concept":"K6-2-u6-C23","difficulty":2,"kind":"mc","stem":"㉯의 뒤에 이어 쓸 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"샘 앞에 물동이가 줄을 서고 나무꾼은 차례를 정하는 일을 맡게 되었다","correct":true},{"t":"그날 밤 용이 나타나 나무꾼을 임금으로 만들어 주었다","mis":"K6-2-u6-X29"},{"t":"나무꾼은 몰래 금도끼를 가져가 부자가 되었다","mis":"K6-2-u6-X27"},{"t":"마을 사람들이 모두 다른 별로 떠났다","mis":"K6-2-u6-X29"}],"explanation":["㉯에서 마지막으로 샘이 생겼어요.","샘이 뒤의 일을 불러와요.","갑작스러운 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#8','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C25',2,'ox','auto','경험을 바탕으로 쓴 이야기는 일기처럼 실제로 있었던 일만 적어야 해요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":8,"concept":"K6-2-u6-C25","difficulty":2,"kind":"ox","stem":"경험을 바탕으로 쓴 이야기는 일기처럼 실제로 있었던 일만 적어야 해요.","answer":"X","reason_options":[{"t":"겪은 일에서 출발하되 인물 · 배경 · 사건을 지어내도 되기 때문에","correct":true},{"t":"지어낸 부분이 있으면 이야기가 될 수 없기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["일기는 실제로 있었던 일만 적어요.","이야기는 지어낸 부분이 있어야 해요.","겪은 일에서 출발하면 더 자세히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#9','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C25',2,'mc','auto','이야기를 바꾸어 쓸 때 생각할 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X29','K6-2-u6-X02']::text[],false,'{"seq":9,"concept":"K6-2-u6-C25","difficulty":2,"kind":"mc","stem":"이야기를 바꾸어 쓸 때 생각할 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"원래 이야기보다 몇 배 길게 쓸지","correct":true},{"t":"인물의 성격을 어떻게 바꿀지","mis":"K6-2-u6-X35"},{"t":"앞의 일이 뒤의 일을 부르는지","mis":"K6-2-u6-X29"},{"t":"내가 잘 아는 경험을 살릴 수 있는지","mis":"K6-2-u6-X02"}],"explanation":["성격 · 때와 곳 · 원인과 결과를 생각해요.","내 경험도 살려요.","길이는 생각할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#10','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C24',3,'mc','auto','「나무꾼이 도끼를 빠뜨리자 갑자기 하늘에서 우주선이 내려와 마을을 다른 별로 옮겼다.」를 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X26']::text[],false,'{"seq":10,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"「나무꾼이 도끼를 빠뜨리자 갑자기 하늘에서 우주선이 내려와 마을을 다른 별로 옮겼다.」를 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"놀랍기는 하지만 앞의 일과 이어지지 않아 잘 바꾼 것이 아니다","correct":true},{"t":"가장 기발하게 바꾸었으니 가장 잘 바꾼 이야기다","mis":"K6-2-u6-X30"},{"t":"많이 바꿀수록 좋으니 배경도 더 바꾸면 된다","mis":"K6-2-u6-X36"},{"t":"옛이야기에 우주선이 나오면 패러디가 아니다","mis":"K6-2-u6-X26"}],"explanation":["놀라움으로 가늠하지 않아요.","앞의 일이 뒤의 일을 불러야 해요.","바뀐 것에서 다음 일이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#1','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C21',2,'mc','auto','㉮와 ㉯의 나무꾼이 같은 점은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X27']::text[],false,'{"seq":1,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"㉮와 ㉯의 나무꾼이 같은 점은 무엇인가요?","options":[{"t":"둘 다 정직하다","correct":true},{"t":"둘 다 세 도끼를 모두 받았다","mis":"K6-2-u6-X07"},{"t":"둘 다 마을의 물을 걱정했다","mis":"K6-2-u6-X27"},{"t":"둘 다 이웃에게 도끼를 빼앗겼다","mis":"K6-2-u6-X07"}],"explanation":["둘 다 금도끼를 제 것이라 하지 않았어요.","정직하다는 점은 같아요.","달라진 것은 무엇까지 생각하는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#2','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C22',2,'mc','auto','㉯에서 때를 「가뭄이 든 해」로 바꾸자 자연스러워진 것은 무엇인가요?',ARRAY['K6-2-u6-X28']::text[],false,'{"seq":2,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"㉯에서 때를 「가뭄이 든 해」로 바꾸자 자연스러워진 것은 무엇인가요?","options":[{"t":"나무꾼이 물을 걱정하는 것","correct":true},{"t":"나무꾼이 금도끼를 받는 것","mis":"K6-2-u6-X28"},{"t":"이웃이 도끼를 연못에 던지는 것","mis":"K6-2-u6-X28"},{"t":"산신령이 나타나는 것","mis":"K6-2-u6-X28"}],"explanation":["배경이 바뀌면 할 수 있는 일이 바뀌어요.","가뭄에는 물이 가장 걱정돼요.","그래서 상을 거절하는 것도 자연스러워요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#3','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C20',3,'error','auto','패러디에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X26','K6-2-u6-X32']::text[],false,'{"seq":3,"concept":"K6-2-u6-C20","difficulty":3,"kind":"error","stem":"패러디에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준하 — 「원래 이야기를 밝히지 않고 조금만 고쳐 내 것처럼 내도 패러디야.」","correct":true,"mis_target":"K6-2-u6-X26"},{"t":"채아 — 「원래 이야기를 밝히고 일부러 바꾸는 거야.」","mis":"K6-2-u6-X26"},{"t":"세윤 — 「바뀐 곳에서 새로운 뜻이 생겨야 해.」","mis":"K6-2-u6-X32"}],"explanation":["채아와 세윤은 바르게 말했어요.","밝히지 않고 내 것처럼 내면 표절이에요.","패러디는 새로운 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#4','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C23',3,'mc','auto','㉯의 사건 흐름을 원인과 결과로 바르게 이은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X27']::text[],false,'{"seq":4,"concept":"K6-2-u6-C23","difficulty":3,"kind":"mc","stem":"㉯의 사건 흐름을 원인과 결과로 바르게 이은 것은 어느 것인가요?","options":[{"t":"가뭄이 든 해였으므로 → 물을 먼저 걱정했고 → 그래서 상을 거절했고 → 그래서 샘이 생겼다","correct":true},{"t":"상을 거절했으므로 → 가뭄이 들었고 → 그래서 도끼를 빠뜨렸다","mis":"K6-2-u6-X29"},{"t":"도끼를 빠뜨렸으므로 → 갑자기 부자가 되었다","mis":"K6-2-u6-X29"},{"t":"샘이 생겼으므로 → 나무꾼이 금도끼를 받았다","mis":"K6-2-u6-X27"}],"explanation":["앞의 일이 뒤의 일을 불러요.","가뭄 → 걱정 → 거절 → 샘이에요.","차례가 거꾸로면 이어지지 않아요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#5','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C4',3,'ox','auto','㉯에서 배경만 바꾸고 인물의 생각과 사건은 ㉮와 똑같이 두어도 자연스러운 이야기가 돼요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":5,"concept":"K6-2-u6-C4","difficulty":3,"kind":"ox","stem":"㉯에서 배경만 바꾸고 인물의 생각과 사건은 ㉮와 똑같이 두어도 자연스러운 이야기가 돼요.","answer":"X","reason_options":[{"t":"배경이 바뀌면 인물이 하는 일과 사건도 함께 움직이기 때문에","correct":true},{"t":"세 요소는 따로따로라서 하나만 바꾸어도 되기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["가뭄이 든 해라면 물이 걱정돼요.","그 걱정이 하는 일을 바꿔요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#6','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C25',3,'match','auto','두 글과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C25","difficulty":3,"kind":"match","stem":"두 글과 알맞은 설명을 이으세요.","pairs":[{"l":"일기","r":"실제로 있었던 일만 적는다"},{"l":"경험을 바탕으로 쓴 이야기","r":"겪은 일에서 출발해 인물 · 배경 · 사건을 지어낸다"},{"l":"표절한 글","r":"남의 것을 그대로 옮기고 자기 것인 척한다"}],"mis":"K6-2-u6-X31","explanation":["일기는 사실만 적어요.","이야기는 지어낸 부분이 있어요.","표절은 새 뜻이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#7','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C24',3,'mc','auto','바꾸어 쓴 이야기를 가늠하는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X32']::text[],false,'{"seq":7,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"바꾸어 쓴 이야기를 가늠하는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 것에 따라 뒤가 자연스럽게 이어지는가","correct":true},{"t":"기발한 생각을 얼마나 많이 넣었는가","mis":"K6-2-u6-X30"},{"t":"얼마나 많은 곳을 바꾸었는가","mis":"K6-2-u6-X36"},{"t":"원래 이야기보다 얼마나 길어졌는가","mis":"K6-2-u6-X32"}],"explanation":["많이 · 기발하게가 기준이 아니에요.","길이도 기준이 아니에요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#8','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C26',4,'mc','auto','㉮를 ㉯로 바꾸자 새로 생긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":8,"concept":"K6-2-u6-C26","difficulty":4,"kind":"mc","stem":"㉮를 ㉯로 바꾸자 새로 생긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정직함은 나 혼자의 일이 아니라 마을을 함께 생각하는 일이기도 하다","correct":true},{"t":"정직하면 반드시 금도끼를 받는다","mis":"K6-2-u6-X32"},{"t":"욕심을 부리면 제 것도 잃는다","mis":"K6-2-u6-X32"},{"t":"산신령은 무서운 존재다","mis":"K6-2-u6-X32"}],"explanation":["㉮는 정직하면 상을 받는다는 이야기예요.","㉯는 상을 거절하고 마을에 샘이 생겨요.","정직함이 마을로 넓어졌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#9','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C21',4,'essay','teacher','㉮와 ㉯의 나무꾼을 견주어 성격이 어떻게 달라졌는지 쓰고, 성격이 달라지자 하는 일이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C21","difficulty":4,"kind":"essay","stem":"㉮와 ㉯의 나무꾼을 견주어 성격이 어떻게 달라졌는지 쓰고, 성격이 달라지자 하는 일이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: ㉮의 나무꾼은 제 것이 아닌 것을 제 것이라 하지 않는 정직한 사람이고, 산신령이 주는 세 도끼를 고맙게 받는다. ㉯의 나무꾼도 정직하지만, 받기 전에 마을에 무슨 일이 생길지 먼저 생각하는 사람이다. 그래서 금도끼를 얻으려고 사람들이 몰려오면 연못이 상할 것을 걱정해 상을 거절하고 쇠도끼만 받는다. 성격이 달라지자 하는 일이 달라졌다.","scoring_points":["두 나무꾼의 같은 점을 썼는가","성격이 어떻게 달라졌는지 썼는가","성격 때문에 하는 일이 달라졌다고 이어 썼는가"]},"explanation":["같은 점부터 찾아요.","무엇까지 생각하는지 견주어요.","성격이 바뀌면 하는 일이 바뀌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#10','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C24',4,'essay','teacher','「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 우주선이 내려오는 이야기와 ㉯를 견주어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C24","difficulty":4,"kind":"essay","stem":"「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 우주선이 내려오는 이야기와 ㉯를 견주어 설명하세요.","answer_guide":{"answer":"예: 우주선이 내려와 마을을 다른 별로 옮기는 이야기는 놀랍기는 하지만 도끼를 빠뜨린 앞의 일과 아무 상관이 없어 이어지지 않는다. ㉯는 때를 가뭄이 든 해로 하나 바꾸었을 뿐인데, 그래서 나무꾼이 물을 걱정하고, 그래서 상을 거절하고, 그래서 샘이 생기는 일이 앞이 뒤를 부르며 자연스럽게 이어진다. 그러므로 이야기를 바꿀 때에는 얼마나 많이·놀랍게 바꾸었는가가 아니라 바뀐 것에서 다음 일이 자연스럽게 나오는가로 가늠해야 한다.","scoring_points":["우주선 이야기가 이어지지 않는 까닭을 썼는가","㉯에서 앞이 뒤를 부르는 흐름을 썼는가","가늠하는 기준을 이어짐으로 썼는가"]},"explanation":["놀라움은 기준이 아니에요.","앞이 뒤를 부르는지 봐요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#1','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',1,'mc','auto','「토끼와 자라」에서 토끼가 살아서 돌아올 수 있었던 까닭은 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C27","difficulty":1,"kind":"mc","stem":"「토끼와 자라」에서 토끼가 살아서 돌아올 수 있었던 까닭은 무엇인가요?","options":[{"t":"간을 산에 두고 왔다고 둘러대어 용왕을 믿게 해서","correct":true},{"t":"자라보다 헤엄을 잘 쳐서","mis":"K6-2-u6-X33"},{"t":"용왕의 병을 고칠 다른 약을 찾아 주어서","mis":"K6-2-u6-X07"},{"t":"용궁의 신하들과 싸워 이겨서","mis":"K6-2-u6-X07"}],"explanation":["토끼가 용궁에서 한 말을 읽어요.","간을 볕에 말리려고 두고 왔다고 했어요.","토끼는 말로 자기를 지켰어요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#2','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C26',1,'mc','auto','이야기를 바꾸어 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":2,"concept":"K6-2-u6-C26","difficulty":1,"kind":"mc","stem":"이야기를 바꾸어 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 곳에서 새로운 뜻이 생기기 때문에","correct":true},{"t":"글을 원래보다 길게 늘리기 위해서","mis":"K6-2-u6-X32"},{"t":"원래 이야기를 그대로 외우기 위해서","mis":"K6-2-u6-X32"},{"t":"어려운 낱말을 많이 쓰기 위해서","mis":"K6-2-u6-X32"}],"explanation":["정직하면 상을 받는다던 이야기가 있었어요.","바꾸자 정직함이 마을로 넓어졌어요.","새로운 뜻이 생기는 것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#3','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',1,'mc','auto','이야기에서 가장 긴장되는 순간을 무엇이라고 하나요?',ARRAY['K6-2-u6-X34','K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C27","difficulty":1,"kind":"mc","stem":"이야기에서 가장 긴장되는 순간을 무엇이라고 하나요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u6-X34"},{"t":"전개","mis":"K6-2-u6-X34"},{"t":"배경","mis":"K6-2-u6-X05"}],"explanation":["발단은 일이 시작되는 곳이에요.","전개는 일이 커지는 곳이에요.","가장 긴장되는 순간이 절정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#4','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',1,'ox','auto','이야기를 바꿀 때 인물 · 배경 · 사건 가운데 하나만 골라 바꾸어도 충분해요.',ARRAY['K6-2-u6-X36']::text[],false,'{"seq":4,"concept":"K6-2-u6-C28","difficulty":1,"kind":"ox","stem":"이야기를 바꿀 때 인물 · 배경 · 사건 가운데 하나만 골라 바꾸어도 충분해요.","answer":"O","reason_options":[{"t":"하나를 바꾸면 나머지가 따라 움직이기 때문에","correct":true},{"t":"셋을 모두 바꾸어야 제대로 바꾼 것이기 때문에","mis":"K6-2-u6-X36"}],"mis":"K6-2-u6-X36","explanation":["셋은 서로 붙어 있어요.","하나를 바꾸면 나머지도 움직여요.","그래서 하나만 바꾸어도 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#5','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',2,'match','auto','인물과 그 성격이 드러난 곳을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C27","difficulty":2,"kind":"match","stem":"인물과 그 성격이 드러난 곳을 이으세요.","pairs":[{"l":"토끼","r":"놀라지 않은 척하며 둘러댄다"},{"l":"자라","r":"혼자 나서서 뭍까지 올라간다"},{"l":"용왕","r":"들은 말을 그대로 믿는다"}],"mis":"K6-2-u6-X33","explanation":["성격은 인물이 한 일에서 드러나요.","토끼는 급할수록 머리가 잘 돌아가요.","용왕은 낫고 싶은 마음이 앞서요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#6','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',2,'mc','auto','「토끼와 자라」의 발단으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":6,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「토끼와 자라」의 발단으로 알맞은 것은 어느 것인가요?","options":[{"t":"용왕이 병이 들고, 토끼의 간이 약이라는 말이 돈다","correct":true},{"t":"자라가 뭍에 올라 토끼를 꾀어 용궁으로 데려간다","mis":"K6-2-u6-X34"},{"t":"토끼가 간을 두고 왔다고 둘러댄다","mis":"K6-2-u6-X34"},{"t":"뭍에 내린 토끼가 달아난다","mis":"K6-2-u6-X34"}],"explanation":["발단은 일이 시작되는 곳이에요.","용왕의 병에서 모든 일이 시작돼요.","꾀어 데려가는 것은 전개예요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#7','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',2,'mc','auto','자라의 성격을 「스스로 따져 보는 성격」으로 바꾸면 함께 손봐야 할 것은 어느 것인가요?',ARRAY['K6-2-u6-X35']::text[],false,'{"seq":7,"concept":"K6-2-u6-C28","difficulty":2,"kind":"mc","stem":"자라의 성격을 「스스로 따져 보는 성격」으로 바꾸면 함께 손봐야 할 것은 어느 것인가요?","options":[{"t":"자라가 토끼에게 하는 말","correct":true},{"t":"바닷속이라는 공간","mis":"K6-2-u6-X35"},{"t":"이야기의 글자 수","mis":"K6-2-u6-X35"},{"t":"아무것도 손볼 필요가 없다","mis":"K6-2-u6-X35"}],"explanation":["자라가 사실대로 말하게 돼요.","그러면 토끼의 행동과 끝도 바뀌어요.","바꾼 것에 닿아 있던 곳을 손봐요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#8','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C29',2,'ox','auto','바꾼 이야기의 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 좋아요.',ARRAY['K6-2-u6-X37']::text[],false,'{"seq":8,"concept":"K6-2-u6-C29","difficulty":2,"kind":"ox","stem":"바꾼 이야기의 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 좋아요.","answer":"O","reason_options":[{"t":"읽는 사람이 무엇이 바뀌었는지 금방 알아채기 때문에","correct":true},{"t":"첫 문장은 원래 이야기와 똑같아야 하기 때문에","mis":"K6-2-u6-X37"}],"mis":"K6-2-u6-X37","explanation":["바뀐 것이 첫 문장에 보이면 좋아요.","읽는 사람이 금방 알아채요.","제목도 바뀐 것이 드러나게 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#9','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C30',2,'mc','auto','친구의 이야기에 붙일 칭찬 쪽지로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X25']::text[],false,'{"seq":9,"concept":"K6-2-u6-C30","difficulty":2,"kind":"mc","stem":"친구의 이야기에 붙일 칭찬 쪽지로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 사실대로 말하는 부분에서 마음이 바뀐 것이 잘 드러나 인상 깊었어","correct":true},{"t":"잘 썼어. 다음에도 이렇게 써","mis":"K6-2-u6-X25"},{"t":"글씨를 또박또박 써서 읽기 편했어","mis":"K6-2-u6-X25"},{"t":"재미있어","mis":"K6-2-u6-X25"}],"explanation":["어느 부분이 좋았는지 짚어요.","왜 좋았는지 까닭을 붙여요.","잘 썼어에서 멈추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#10','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',3,'mc','auto','자라를 「스스로 따져 보는 성격」으로 바꾼 계획으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X29','K6-2-u6-X36']::text[],false,'{"seq":10,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"자라를 「스스로 따져 보는 성격」으로 바꾼 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"데려가는 길에 마음이 걸려 토끼에게 사정을 사실대로 말한다","correct":true},{"t":"성격은 바뀌었지만 여전히 아무 말 없이 토끼를 속여 데려간다","mis":"K6-2-u6-X27"},{"t":"가는 길에 갑자기 벼락이 쳐 용왕의 병이 저절로 나았다","mis":"K6-2-u6-X29"},{"t":"자라는 그대로 두고 토끼와 용왕과 바다를 모두 바꾼다","mis":"K6-2-u6-X36"}],"explanation":["성격을 바꾸었으면 행동도 바뀌어야 해요.","갑작스러운 일은 이어지지 않아요.","하나를 바꾸고 따라 움직이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#1','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',2,'mc','auto','「토끼와 자라」의 전개로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":1,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「토끼와 자라」의 전개로 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 뭍에 올라 토끼를 꾀어 용궁으로 데려간다","correct":true},{"t":"용왕이 병이 들고 토끼의 간이 약이라는 말이 돈다","mis":"K6-2-u6-X34"},{"t":"토끼가 간을 산에 두고 왔다고 둘러댄다","mis":"K6-2-u6-X34"},{"t":"뭍에 내린 토끼가 풀숲으로 달아난다","mis":"K6-2-u6-X34"}],"explanation":["발단은 용왕의 병이에요.","절정은 토끼가 둘러대는 순간이에요.","꾀어 데려가는 것이 전개예요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#2','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C29',2,'mc','auto','자라 바꾸기 계획에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":2,"concept":"K6-2-u6-C29","difficulty":2,"kind":"mc","stem":"자라 바꾸기 계획에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 입을 열었다","correct":true},{"t":"토끼와 자라","mis":"K6-2-u6-X18"},{"t":"바닷속 이야기","mis":"K6-2-u6-X18"},{"t":"토끼의 간","mis":"K6-2-u6-X18"}],"explanation":["원래 제목은 바뀐 것을 드러내지 못해요.","자라가 사실대로 말한 것이 바뀐 곳이에요.","그것이 드러나는 제목이 좋아요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#3','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'error','auto','자라 바꾸기 계획을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X36']::text[],false,'{"seq":3,"concept":"K6-2-u6-C28","difficulty":3,"kind":"error","stem":"자라 바꾸기 계획을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세윤 — 「자라 성격만 바꿨으니 토끼가 하는 일은 손볼 필요 없어.」","correct":true,"mis_target":"K6-2-u6-X35"},{"t":"채아 — 「자라가 사실대로 말하면 토끼는 달아날 까닭이 없어지니까 토끼 행동도 바뀌어.」","mis":"K6-2-u6-X35"},{"t":"지오 — 「배경이랑 용왕 성격은 그대로 두어도 돼.」","mis":"K6-2-u6-X36"}],"explanation":["채아와 지오는 바르게 말했어요.","하나를 바꾸면 거기에 닿아 있던 곳이 함께 움직여요.","세윤은 손볼 곳을 놓쳤어요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#4','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'mc','auto','자라 바꾸기 계획에서 「그대로 두는 것」으로 정한 것은 무엇인가요?',ARRAY['K6-2-u6-X35']::text[],false,'{"seq":4,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"자라 바꾸기 계획에서 「그대로 두는 것」으로 정한 것은 무엇인가요?","options":[{"t":"배경(바닷속 용궁과 산)과 용왕의 성격","correct":true},{"t":"자라의 성격","mis":"K6-2-u6-X35"},{"t":"토끼가 하는 일","mis":"K6-2-u6-X35"},{"t":"이야기의 마지막","mis":"K6-2-u6-X35"}],"explanation":["자라의 성격은 바꿀 것이에요.","토끼의 행동과 마지막은 따라 바뀌어요.","배경과 용왕은 그대로 두었어요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#5','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',3,'ox','auto','「토끼와 자라」를 바꿀 때 인물의 성격을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보여요.',ARRAY['K6-2-u6-X33']::text[],false,'{"seq":5,"concept":"K6-2-u6-C27","difficulty":3,"kind":"ox","stem":"「토끼와 자라」를 바꿀 때 인물의 성격을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보여요.","answer":"O","reason_options":[{"t":"성격이 그 인물이 한 일을 낳으므로 바꿀 곳이 눈에 띄기 때문에","correct":true},{"t":"성격은 이야기와 상관없으니 아무렇게나 정해도 되기 때문에","mis":"K6-2-u6-X33"}],"mis":"K6-2-u6-X33","explanation":["성격은 인물이 한 일에서 드러나요.","성격을 바꾸면 한 일이 바뀌어요.","그래서 먼저 정리해 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#6','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',3,'match','auto','이야기의 차례와 「토끼와 자라」의 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C27","difficulty":3,"kind":"match","stem":"이야기의 차례와 「토끼와 자라」의 일을 이으세요.","pairs":[{"l":"발단","r":"용왕이 병이 들고 토끼의 간이 약이라는 말이 돈다"},{"l":"전개","r":"자라가 토끼를 꾀어 용궁으로 데려간다"},{"l":"절정","r":"토끼가 간을 두고 왔다고 둘러댄다"}],"mis":"K6-2-u6-X34","explanation":["일이 시작되는 곳이 발단이에요.","일이 커지는 곳이 전개예요.","가장 긴장되는 순간이 절정이에요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#7','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',3,'mc','auto','칭찬 쪽지를 「잘 썼어 · 재미있어」에서 멈추지 말아야 하는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X42']::text[],false,'{"seq":7,"concept":"K6-2-u6-C30","difficulty":3,"kind":"mc","stem":"칭찬 쪽지를 「잘 썼어 · 재미있어」에서 멈추지 말아야 하는 까닭은 무엇인가요?","options":[{"t":"어느 부분이 왜 좋았는지 알아야 친구가 무엇을 잘했는지 알 수 있기 때문에","correct":true},{"t":"칭찬 쪽지는 길게 써야 점수를 받기 때문에","mis":"K6-2-u6-X25"},{"t":"잘했다는 말은 하면 안 되기 때문에","mis":"K6-2-u6-X25"},{"t":"고칠 점만 써야 도움이 되기 때문에","mis":"K6-2-u6-X42"}],"explanation":["막연한 칭찬은 무엇을 잘했는지 알려 주지 않아요.","어느 부분인지 짚어요.","왜 좋았는지 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#8','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C23',4,'mc','auto','자라 바꾸기 계획의 흐름이 이어지는지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X36','K6-2-u6-X27']::text[],false,'{"seq":8,"concept":"K6-2-u6-C23","difficulty":4,"kind":"mc","stem":"자라 바꾸기 계획의 흐름이 이어지는지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"자라가 사실대로 말했으므로 토끼가 달아날 까닭이 없고, 그래서 함께 약을 찾고, 그래서 약초를 찾아내어 앞이 뒤를 부른다","correct":true},{"t":"토끼가 하늘을 날아 모두를 구해야 더 재미있게 이어진다","mis":"K6-2-u6-X29"},{"t":"바꾼 곳이 하나뿐이라 이어지지 않는다","mis":"K6-2-u6-X36"},{"t":"자라는 바꾸었지만 토끼는 여전히 거짓말로 달아나야 이어진다","mis":"K6-2-u6-X27"}],"explanation":["사실대로 말한 것이 원인이에요.","함께 약을 찾는 것이 결과예요.","앞이 뒤를 부르며 이어져요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#9','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',4,'essay','teacher','「토끼와 자라」에서 토끼의 성격을 「겁이 많은 성격」에서 「겁이 없는 성격」으로 바꾼다고 할 때, 그 때문에 달라질 전개 · 절정 · 마지막을 차례대로 쓰고, 그대로 둘 것을 하나 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"「토끼와 자라」에서 토끼의 성격을 「겁이 많은 성격」에서 「겁이 없는 성격」으로 바꾼다고 할 때, 그 때문에 달라질 전개 · 절정 · 마지막을 차례대로 쓰고, 그대로 둘 것을 하나 쓰세요.","answer_guide":{"answer":"예: 바꿀 것 — 토끼의 성격을 겁이 없는 성격으로. 전개 — 자라를 따라 용궁에 간 토끼는 사정을 듣고도 떨지 않는다. 절정 — 토끼는 둘러대는 대신 용왕 앞에서 「제 간을 내놓으면 저는 죽습니다. 다른 약을 함께 찾아봅시다.」 하고 당당하게 말한다. 마지막 — 용왕은 토끼의 말에 부끄러워하고, 토끼와 자라가 함께 바닷속 약초를 찾는다. 그대로 둘 것 — 배경(바닷속 용궁과 산).","scoring_points":["바꿀 것을 하나 정했는가","성격 때문에 달라질 일을 차례대로 이어 썼는가","그대로 둘 것을 썼는가"]},"explanation":["하나만 바꿔요.","성격이 바뀌면 행동이 바뀌어요.","그대로 둘 것도 정해요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#10','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',4,'essay','teacher','친구가 자라 바꾸기 계획대로 이야기를 썼어요. 이 이야기에 붙일 칭찬 쪽지를 어느 부분이 왜 좋았는지 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C30","difficulty":4,"kind":"essay","stem":"친구가 자라 바꾸기 계획대로 이야기를 썼어요. 이 이야기에 붙일 칭찬 쪽지를 어느 부분이 왜 좋았는지 드러나게 쓰세요.","answer_guide":{"answer":"예: 자라가 토끼를 등에 태우고 가다가 「사실은 너를 데려가는 까닭이 따로 있어.」 하고 입을 여는 부분이 가장 인상 깊었어. 맡은 일만 하던 자라가 스스로 따져 보는 자라로 바뀐 것이 그 한마디에 잘 드러났고, 그래서 토끼가 달아나지 않고 함께 약을 찾는 것도 자연스럽게 이어졌어.","scoring_points":["좋았던 부분을 콕 집었는가","왜 좋았는지 까닭을 붙였는가","겉모습이 아니라 이야기 내용을 칭찬했는가"]},"explanation":["어느 부분인지 짚어요.","왜 좋았는지 써요.","글씨가 아니라 이야기를 봐요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#1','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',1,'mc','auto','낭송한 목소리와 속도를 그대로 남길 수 있는 책의 형태는 어느 것인가요?',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":1,"concept":"K6-2-u6-C31","difficulty":1,"kind":"mc","stem":"낭송한 목소리와 속도를 그대로 남길 수 있는 책의 형태는 어느 것인가요?","options":[{"t":"소리로 담는 책","correct":true},{"t":"종이책","mis":"K6-2-u6-X38"},{"t":"화면으로 보는 책","mis":"K6-2-u6-X38"},{"t":"표지만 있는 책","mis":"K6-2-u6-X38"}],"explanation":["종이책은 아무 때나 넘겨 봐요.","화면으로 보는 책은 멀리 보낼 수 있어요.","소리로 담는 책은 목소리를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#2','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',1,'ox','auto','책의 세 형태 가운데 가장 좋은 형태가 하나 정해져 있어요.',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":2,"concept":"K6-2-u6-C31","difficulty":1,"kind":"ox","stem":"책의 세 형태 가운데 가장 좋은 형태가 하나 정해져 있어요.","answer":"X","reason_options":[{"t":"형태마다 알맞은 자리가 서로 다를 뿐이기 때문에","correct":true},{"t":"화면으로 보는 책이 언제나 가장 좋기 때문에","mis":"K6-2-u6-X38"}],"mis":"K6-2-u6-X38","explanation":["종이책 · 소리로 담는 책 · 화면으로 보는 책이 있어요.","형태마다 잘하는 일이 달라요.","더 나은 형태는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#3','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',1,'mc','auto','「끈이나 줄을 묶다」라는 뜻의 낱말은 어느 것인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":3,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"「끈이나 줄을 묶다」라는 뜻의 낱말은 어느 것인가요?","options":[{"t":"매다","correct":true},{"t":"메다","mis":"K6-2-u6-X43"},{"t":"맺다","mis":"K6-2-u6-X43"},{"t":"바치다","mis":"K6-2-u6-X43"}],"explanation":["메다는 어깨에 걸쳐 지는 거예요.","바치다는 웃어른께 올리는 거예요.","끈을 묶는 것은 매다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#4','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',1,'mc','auto','실을 글을 쓰기 전에 정해 두어야 할 것은 어느 것인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":4,"concept":"K6-2-u6-C32","difficulty":1,"kind":"mc","stem":"실을 글을 쓰기 전에 정해 두어야 할 것은 어느 것인가요?","options":[{"t":"일이 일어난 때와 곳","correct":true},{"t":"책 표지에 쓸 색깔","mis":"K6-2-u6-X40"},{"t":"글자를 몇 자나 쓸지","mis":"K6-2-u6-X40"},{"t":"그림을 몇 장 넣을지","mis":"K6-2-u6-X40"}],"explanation":["표지 색과 글자 수는 먼저 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요.","그러면 글이 빨리 써져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#5','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',2,'mc','auto','세윤이네 모둠이 책의 형태를 정할 때 가장 먼저 생각한 것은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":5,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"세윤이네 모둠이 책의 형태를 정할 때 가장 먼저 생각한 것은 무엇인가요?","options":[{"t":"누가 읽을지","correct":true},{"t":"가장 새롭고 멋있어 보이는 형태인지","mis":"K6-2-u6-X38"},{"t":"가장 빨리 끝낼 수 있는 형태인지","mis":"K6-2-u6-X38"},{"t":"표지를 어떻게 꾸밀지","mis":"K6-2-u6-X39"}],"explanation":["세윤이가 가장 먼저 물었어요.","읽을 사람을 독자라고 해요.","독자가 정해지면 형태가 따라와요."],"asset":{"type":"speech","turns":[{"who":"세윤","text":"우리 책은 누가 읽게 될까? 그것부터 정하자."},{"who":"채아","text":"우리 반 친구들이랑, 가정에 계신 분들께도 보여 드리면 좋겠어."},{"who":"지오","text":"그러면 집에서도 볼 수 있어야 하니까 화면으로 보는 책이 낫겠다."},{"who":"채아","text":"낭송한 시도 넣고 싶은데. 그럼 소리도 같이 담을 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#6','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',2,'match','auto','책의 형태와 그 형태가 잘하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C31","difficulty":2,"kind":"match","stem":"책의 형태와 그 형태가 잘하는 일을 이으세요.","pairs":[{"l":"종이책","r":"교실에 두고 아무 때나 넘겨 본다"},{"l":"소리로 담는 책","r":"낭송의 목소리와 속도를 그대로 남긴다"},{"l":"화면으로 보는 책","r":"멀리 있는 사람에게 바로 보낸다"}],"mis":"K6-2-u6-X38","explanation":["형태마다 잘하는 일이 따로 있어요.","등수가 아니라 자리가 달라요.","독자와 내용에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#7','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C33',2,'ox','auto','표지를 사흘 동안 꾸미고 글은 마지막 날 급히 쓰는 것이 좋은 방법이에요.',ARRAY['K6-2-u6-X41']::text[],false,'{"seq":7,"concept":"K6-2-u6-C33","difficulty":2,"kind":"ox","stem":"표지를 사흘 동안 꾸미고 글은 마지막 날 급히 쓰는 것이 좋은 방법이에요.","answer":"X","reason_options":[{"t":"이야기를 먼저 완성하고 꾸미기는 돕는 만큼만 해야 하기 때문에","correct":true},{"t":"책은 표지가 화려해야 잘한 책이기 때문에","mis":"K6-2-u6-X41"}],"mis":"K6-2-u6-X41","explanation":["책은 담긴 이야기로 남아요.","꾸미기는 읽기 좋게 돕는 만큼만 해요.","이야기가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#8','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',2,'mc','auto','빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「무거운 가방을 어깨에 (   ) 걸었다.」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":2,"kind":"mc","stem":"빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「무거운 가방을 어깨에 (   ) 걸었다.」","options":[{"t":"메고","correct":true},{"t":"매고","mis":"K6-2-u6-X43"},{"t":"받치고","mis":"K6-2-u6-X43"},{"t":"부치고","mis":"K6-2-u6-X43"}],"explanation":["어깨에 걸쳐 지는 것은 메다예요.","매다는 끈을 묶는 거예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#9','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',2,'mc','auto','경험을 바탕으로 학급 이야기책에 실을 글을 쓸 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":9,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"경험을 바탕으로 학급 이야기책에 실을 글을 쓸 때 알맞은 것은 어느 것인가요?","options":[{"t":"겪은 일에서 출발하되 인물과 배경은 지어내도 된다","correct":true},{"t":"일기를 그대로 옮겨 적어야 한다","mis":"K6-2-u6-X31"},{"t":"겪은 일과 상관없는 것만 써야 한다","mis":"K6-2-u6-X31"},{"t":"인물의 이름은 꼭 실제 친구 이름이어야 한다","mis":"K6-2-u6-X31"}],"explanation":["일기를 옮겨 적는 것이 아니에요.","겪은 일에서 출발해요.","인물과 배경은 지어내도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#10','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C33',3,'error','auto','학급 이야기책을 만들며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":10,"concept":"K6-2-u6-C33","difficulty":3,"kind":"error","stem":"학급 이야기책을 만들며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지오 — 「글은 짧아도 되니까 그림에 시간을 다 쓰자.」","correct":true,"mis_target":"K6-2-u6-X41"},{"t":"세윤 — 「이야기를 먼저 끝내고 남는 시간에 꾸미자.」","mis":"K6-2-u6-X41"},{"t":"채아 — 「잘한 점은 글에서 찾아 말해 주자.」","mis":"K6-2-u6-X42"}],"explanation":["세윤과 채아는 바르게 말했어요.","지오는 꾸미기가 이야기를 덮게 했어요.","이야기가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#1','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',2,'mc','auto','빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「흔들리는 책상 밑에 종이를 (   ).」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":1,"concept":"K6-2-u6-C34","difficulty":2,"kind":"mc","stem":"빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「흔들리는 책상 밑에 종이를 (   ).」","options":[{"t":"받쳤다","correct":true},{"t":"바쳤다","mis":"K6-2-u6-X43"},{"t":"부쳤다","mis":"K6-2-u6-X43"},{"t":"맸다","mis":"K6-2-u6-X43"}],"explanation":["바치다는 웃어른께 올리는 거예요.","밑에서 괴어 기울지 않게 하는 것은 받치다예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#2','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',2,'mc','auto','함께 책을 만들 때 먼저 정할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":2,"concept":"K6-2-u6-C33","difficulty":2,"kind":"mc","stem":"함께 책을 만들 때 먼저 정할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 무엇을 언제까지 맡을지","correct":true},{"t":"누구 그림이 가장 화려한지","mis":"K6-2-u6-X41"},{"t":"다 만든 뒤 누구 글이 가장 못했는지","mis":"K6-2-u6-X42"},{"t":"표지에 누구 이름을 가장 크게 쓸지","mis":"K6-2-u6-X42"}],"explanation":["누구와 · 무엇을 · 언제까지를 정해요.","다 만든 뒤에는 잘한 점부터 이야기해요.","목적은 함께 쓰고 나누는 즐거움이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#3','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',3,'mc','auto','채아가 「낭송한 시도 넣고 싶다」고 할 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":3,"concept":"K6-2-u6-C31","difficulty":3,"kind":"mc","stem":"채아가 「낭송한 시도 넣고 싶다」고 할 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"소리를 함께 담을 수 있는 형태를 고르거나, 화면으로 보는 책에 낭송 소리를 덧붙인다","correct":true},{"t":"화면으로 보는 책이 제일 좋으니 소리는 빼자","mis":"K6-2-u6-X38"},{"t":"종이책이 가장 좋은 형태니까 종이책으로 하자","mis":"K6-2-u6-X38"},{"t":"누가 읽을지는 상관없으니 아무 형태나 고르자","mis":"K6-2-u6-X39"}],"explanation":["전하고 싶은 것이 낭송한 소리예요.","형태는 독자와 내용에 맞게 골라요.","형태에 등수는 없어요."],"asset":{"type":"speech","turns":[{"who":"세윤","text":"우리 책은 누가 읽게 될까? 그것부터 정하자."},{"who":"채아","text":"우리 반 친구들이랑, 가정에 계신 분들께도 보여 드리면 좋겠어."},{"who":"지오","text":"그러면 집에서도 볼 수 있어야 하니까 화면으로 보는 책이 낫겠다."},{"who":"채아","text":"낭송한 시도 넣고 싶은데. 그럼 소리도 같이 담을 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#4','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'ox','auto','「고마운 마음을 담은 편지를 우체통에 붙였다.」는 바르게 쓴 문장이에요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":4,"concept":"K6-2-u6-C34","difficulty":3,"kind":"ox","stem":"「고마운 마음을 담은 편지를 우체통에 붙였다.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"편지를 보내는 것은 「부치다」이기 때문에","correct":true},{"t":"「붙이다」와 「부치다」는 뜻이 같기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["붙이다는 맞닿아 떨어지지 않게 하는 거예요.","편지를 보내는 것은 부치다예요.","「부쳤다」로 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#5','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C32',3,'error','auto','실을 글을 준비하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":5,"concept":"K6-2-u6-C32","difficulty":3,"kind":"error","stem":"실을 글을 준비하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"루아 — 「글자를 몇 자나 쓸지부터 정해야 글이 빨리 써져.」","correct":true,"mis_target":"K6-2-u6-X40"},{"t":"나래 — 「중심 사건이랑 인물 성격부터 정하자.」","mis":"K6-2-u6-X40"},{"t":"시후 — 「일이 일어난 때와 곳도 정해 두자.」","mis":"K6-2-u6-X40"}],"explanation":["나래와 시후는 바르게 말했어요.","글자 수는 먼저 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#6','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'match','auto','낱말과 알맞은 뜻을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C34","difficulty":3,"kind":"match","stem":"낱말과 알맞은 뜻을 이으세요.","pairs":[{"l":"바치다","r":"웃어른께 정중히 올리다"},{"l":"받치다","r":"밑에서 괴어 기울지 않게 하다"},{"l":"메다","r":"어깨에 걸쳐 지다"}],"mis":"K6-2-u6-X43","explanation":["소리는 같아도 뜻이 달라요.","쓰이는 자리를 떠올려요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#7','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',3,'mc','auto','학급 이야기책 만들기의 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":7,"concept":"K6-2-u6-C33","difficulty":3,"kind":"mc","stem":"학급 이야기책 만들기의 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰고 나누는 즐거움을 겪어 보는 것","correct":true},{"t":"가장 화려한 결과물을 만드는 것","mis":"K6-2-u6-X41"},{"t":"다른 모둠보다 빨리 끝내는 것","mis":"K6-2-u6-X42"},{"t":"친구 글의 잘못을 많이 찾는 것","mis":"K6-2-u6-X42"}],"explanation":["멋진 결과물이 목적이 아니에요.","빨리 끝내는 것도 목적이 아니에요.","쓰고 나누는 즐거움이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#8','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',4,'mc','auto','「멀리 이사 간 친구에게 우리 반 시를 들려주고 싶다」는 목적에 가장 알맞은 책의 형태와 까닭은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39','K6-2-u6-X41']::text[],false,'{"seq":8,"concept":"K6-2-u6-C31","difficulty":4,"kind":"mc","stem":"「멀리 이사 간 친구에게 우리 반 시를 들려주고 싶다」는 목적에 가장 알맞은 책의 형태와 까닭은 어느 것인가요?","options":[{"t":"낭송 소리를 담은 화면으로 보는 책 — 멀리 있는 친구에게 바로 보내고 목소리도 함께 전할 수 있어서","correct":true},{"t":"종이책 — 종이책이 언제나 가장 좋은 형태라서","mis":"K6-2-u6-X38"},{"t":"아무 형태나 — 누가 읽을지는 상관없어서","mis":"K6-2-u6-X39"},{"t":"표지만 화려한 책 — 꾸미기가 가장 중요해서","mis":"K6-2-u6-X41"}],"explanation":["독자는 멀리 있는 친구예요.","전하려는 것은 시의 목소리예요.","그래서 보내기 쉽고 소리를 담는 형태가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#9','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',4,'essay','teacher','우리 반이 만들 이야기책의 독자를 한 가지 정하고, 그 독자에게 알맞은 책의 형태를 골라 까닭을 쓰세요. 형태에 등수가 없다는 것도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"우리 반이 만들 이야기책의 독자를 한 가지 정하고, 그 독자에게 알맞은 책의 형태를 골라 까닭을 쓰세요. 형태에 등수가 없다는 것도 함께 쓰세요.","answer_guide":{"answer":"예: 독자 — 우리 학교 일학년 동생들. 형태 — 종이책. 동생들이 도서관에 두고 아무 때나 손으로 넘겨 그림과 함께 볼 수 있기 때문이다. 만약 독자가 멀리 계신 할머니라면 화면으로 보는 책이 알맞고, 눈이 불편한 분이라면 소리로 담는 책이 알맞다. 이렇게 형태에는 등수가 없고, 독자와 전하고 싶은 것에 따라 알맞은 형태가 달라진다.","scoring_points":["독자를 한 가지 정했는가","독자에게 맞는 형태와 까닭을 썼는가","형태에 등수가 없다는 것을 썼는가"]},"explanation":["독자부터 정해요.","형태가 잘하는 일과 이어요.","등수가 아니라 알맞음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#10','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',4,'essay','teacher','「바치다 · 받치다」, 「부치다 · 붙이다」 가운데 한 짝을 골라 두 낱말이 모두 들어간 짧은 글을 쓰고, 각 낱말을 그 자리에 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"「바치다 · 받치다」, 「부치다 · 붙이다」 가운데 한 짝을 골라 두 낱말이 모두 들어간 짧은 글을 쓰고, 각 낱말을 그 자리에 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께 드릴 편지를 우체국에서 부치고, 집에 와서 편지에 넣었던 사진 한 장을 내 방 벽에 붙였다. 「부치다」는 편지나 물건을 보낼 때 쓰므로 편지를 보낸 자리에 썼고, 「붙이다」는 맞닿아 떨어지지 않게 할 때 쓰므로 사진을 벽에 댄 자리에 썼다. 소리는 같지만 뜻이 달라 앞뒤 문장을 보고 골라 써야 한다.","scoring_points":["한 짝의 두 낱말을 모두 넣었는가","각 낱말을 뜻에 맞는 자리에 썼는가","고른 까닭을 뜻으로 설명했는가"]},"explanation":["두 낱말을 다 써요.","뜻에 맞는 자리에 써요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#1','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C1',1,'mc','auto','경험을 글로 표현하면 좋은 점이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u6-X01']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"경험을 글로 표현하면 좋은 점이 아닌 것은 어느 것인가요?","options":[{"t":"글씨를 예쁘게 쓰는 법을 익힐 수 있다","correct":true},{"t":"지나간 일을 오래 간직할 수 있다","mis":"K6-2-u6-X01"},{"t":"읽는 사람에게 생생하게 전해진다","mis":"K6-2-u6-X01"},{"t":"그때의 마음을 또렷하게 알게 된다","mis":"K6-2-u6-X01"}],"explanation":["간직 · 전함 · 또렷해짐은 좋은 점이에요.","글씨는 겉모습이에요.","경험을 쓰는 까닭과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#2','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C3',1,'ox','auto','짧고 쉬운 말로 쓴 시도 좋은 시가 될 수 있어요.',ARRAY['K6-2-u6-X04']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"ox","stem":"짧고 쉬운 말로 쓴 시도 좋은 시가 될 수 있어요.","answer":"O","reason_options":[{"t":"그 마음에 알맞은 표현이 좋은 표현이기 때문에","correct":true},{"t":"짧을수록 언제나 더 좋은 시이기 때문에","mis":"K6-2-u6-X04"}],"mis":"K6-2-u6-X04","explanation":["어려운 말이 기준이 아니에요.","짧다고 무조건 좋은 것도 아니에요.","마음에 알맞은지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#3','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C4',1,'mc','auto','이야기에서 「일이 일어난 때와 곳」을 무엇이라고 하나요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"이야기에서 「일이 일어난 때와 곳」을 무엇이라고 하나요?","options":[{"t":"배경","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"사건","mis":"K6-2-u6-X05"},{"t":"주제","mis":"K6-2-u6-X05"}],"explanation":["인물은 나오는 사람이나 대상이에요.","사건은 일어난 일이에요.","때와 곳은 배경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#4','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C8',1,'mc','auto','직유법을 쓴 표현은 어느 것인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"직유법을 쓴 표현은 어느 것인가요?","options":[{"t":"우리 집은 난롯가처럼 둥글다","correct":true},{"t":"우리 집은 빈 운동장이다","mis":"K6-2-u6-X11"},{"t":"김이 푹푹 난다","mis":"K6-2-u6-X12"},{"t":"서둘러, 서둘러","mis":"K6-2-u6-X12"}],"explanation":["「처럼」이 있으면 직유법이에요.","빈 운동장이다는 은유법이에요.","푹푹 · 서둘러는 들은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#5','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C9',1,'mc','auto','보고 · 듣고 · 맡고 · 만지고 · 맛본 것을 그대로 살려 쓴 표현을 무엇이라고 하나요?',ARRAY['K6-2-u6-X12','K6-2-u6-X11']::text[],false,'{"seq":5,"concept":"K6-2-u6-C9","difficulty":1,"kind":"mc","stem":"보고 · 듣고 · 맡고 · 만지고 · 맛본 것을 그대로 살려 쓴 표현을 무엇이라고 하나요?","options":[{"t":"감각적 표현","correct":true},{"t":"비유적 표현","mis":"K6-2-u6-X12"},{"t":"은유법","mis":"K6-2-u6-X11"},{"t":"제목","mis":"K6-2-u6-X12"}],"explanation":["느낀 감각을 그대로 옮겨요.","빗대는 것은 비유적 표현이에요.","이것을 감각적 표현이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#6','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C12',1,'mc','auto','생각그물에서 「땀으로 미끄러운 손잡이」는 어느 칸에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":6,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"생각그물에서 「땀으로 미끄러운 손잡이」는 어느 칸에 들어가나요?","options":[{"t":"만진 것","correct":true},{"t":"들은 것","mis":"K6-2-u6-X12"},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"빗댈 것","mis":"K6-2-u6-X12"}],"explanation":["손으로 느낀 감각이에요.","소리는 들은 것이에요.","그래서 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#7','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C17',1,'ox','auto','효과음은 시의 장면과 맞닿은 소리를 아주 짧게 쓰는 것이 좋아요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":7,"concept":"K6-2-u6-C17","difficulty":1,"kind":"ox","stem":"효과음은 시의 장면과 맞닿은 소리를 아주 짧게 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"효과음은 낭송을 돕는 것이지 대신하는 것이 아니기 때문에","correct":true},{"t":"효과음이 많을수록 낭송이 멋있어지기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["효과음은 짧게 써요.","장면과 맞닿은 소리를 골라요.","돕는 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#8','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C20',1,'mc','auto','원래 이야기를 밝히고 일부러 바꾸어 새로운 뜻이 생기게 하는 것은 무엇인가요?',ARRAY['K6-2-u6-X26']::text[],false,'{"seq":8,"concept":"K6-2-u6-C20","difficulty":1,"kind":"mc","stem":"원래 이야기를 밝히고 일부러 바꾸어 새로운 뜻이 생기게 하는 것은 무엇인가요?","options":[{"t":"패러디","correct":true},{"t":"표절","mis":"K6-2-u6-X26"},{"t":"베껴 쓰기","mis":"K6-2-u6-X26"},{"t":"줄거리 외우기","mis":"K6-2-u6-X26"}],"explanation":["표절은 그대로 옮기고 자기 것인 척해요.","패러디는 밝히고 바꿔요.","새로운 뜻이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#9','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C5',2,'mc','auto','시 「물수제비」는 어떤 경험을 담았나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"시 「물수제비」는 어떤 경험을 담았나요?","options":[{"t":"강가에서 납작한 돌을 던져 물수제비를 뜬 경험","correct":true},{"t":"강에서 수영을 배운 경험","mis":"K6-2-u6-X07"},{"t":"돌을 모아 탑을 쌓은 경험","mis":"K6-2-u6-X07"},{"t":"배를 타고 강을 건넌 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이가 실제로 한 일을 찾아요.","납작한 돌을 낮게 던졌어요.","물수제비를 뜬 경험이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#10','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C9',2,'mc','auto','「물수제비」에서 들은 것을 살린 감각적 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":10,"concept":"K6-2-u6-C9","difficulty":2,"kind":"mc","stem":"「물수제비」에서 들은 것을 살린 감각적 표현은 어느 것인가요?","options":[{"t":"톡, 톡, 톡","correct":true},{"t":"돌이 물 위를 걸어간다","mis":"K6-2-u6-X12"},{"t":"강물 속으로 숨어도","mis":"K6-2-u6-X12"},{"t":"내 어깨가 강둑까지 올라간다","mis":"K6-2-u6-X12"}],"explanation":["걸어간다 · 숨어도는 빗댄 표현이에요.","어깨가 올라간다도 빗댄 거예요.","톡, 톡, 톡은 들은 소리예요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#11','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',2,'mc','auto','도윤이의 시 「소풍」이 시보다 목록처럼 읽히는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":11,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"도윤이의 시 「소풍」이 시보다 목록처럼 읽히는 까닭은 무엇인가요?","options":[{"t":"겪은 일을 다 넣어 어느 순간이 중요한지 알 수 없기 때문에","correct":true},{"t":"빗댄 표현이 하나도 없기 때문에","mis":"K6-2-u6-X13"},{"t":"어려운 낱말이 없기 때문에","mis":"K6-2-u6-X04"},{"t":"글감이 대단한 일이 아니기 때문에","mis":"K6-2-u6-X02"}],"explanation":["빗댄 표현이 없어도 시가 돼요.","쉬운 말도 괜찮아요.","다 넣어서 중요한 순간이 흐려졌어요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#12','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C15',2,'mc','auto','시를 고쳐 쓸 때 볼 것이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 고쳐 쓸 때 볼 것이 아닌 것은 어느 것인가요?","options":[{"t":"빗댄 표현이 친구 시보다 많은가","correct":true},{"t":"전하려던 마음이 드러나는가","mis":"K6-2-u6-X19"},{"t":"없어도 되는 줄이 남아 있지는 않은가","mis":"K6-2-u6-X19"},{"t":"소리 내어 읽었을 때 걸리는 곳이 없는가","mis":"K6-2-u6-X19"}],"explanation":["마음 · 연 · 줄 · 소리를 봐요.","빗댄 표현의 개수는 볼 것이 아니에요.","고쳐 쓰기는 시를 자라게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#13','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C16',2,'mc','auto','서하의 낭송 계획에서 가장 먼저 채워야 할 곳은 어느 것인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X21']::text[],false,'{"seq":13,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"서하의 낭송 계획에서 가장 먼저 채워야 할 곳은 어느 것인가요?","options":[{"t":"전하고 싶은 마음","correct":true},{"t":"배경 음악","mis":"K6-2-u6-X22"},{"t":"영상","mis":"K6-2-u6-X22"},{"t":"모든 연의 목소리 크기","mis":"K6-2-u6-X21"}],"explanation":["마음이 아직 정해지지 않았어요.","마음이 정해져야 목소리와 속도가 정해져요.","마음부터 채워요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#14','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C21',2,'mc','auto','인물의 성격이 바뀌면 함께 바뀌는 것은 무엇인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X06']::text[],false,'{"seq":14,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"인물의 성격이 바뀌면 함께 바뀌는 것은 무엇인가요?","options":[{"t":"그 인물이 하는 말과 행동","correct":true},{"t":"이야기의 글자 수","mis":"K6-2-u6-X35"},{"t":"아무것도 바뀌지 않는다","mis":"K6-2-u6-X06"},{"t":"책의 형태","mis":"K6-2-u6-X35"}],"explanation":["성격은 하는 일로 드러나요.","성격이 바뀌면 하는 일이 바뀌어요.","그래서 사건도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#15','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C27',2,'mc','auto','지안이의 계획에서 바뀐 요소는 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X05']::text[],false,'{"seq":15,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 바뀐 요소는 무엇인가요?","options":[{"t":"베짱이의 성격","correct":true},{"t":"개미의 성격","mis":"K6-2-u6-X33"},{"t":"이야기의 배경","mis":"K6-2-u6-X05"},{"t":"이야기의 제목","mis":"K6-2-u6-X05"}],"explanation":["바꿀 것 칸을 봐요.","게으름에서 남을 위해 연습하는 성격으로 바꾸었어요.","인물의 성격을 바꾸었어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#16','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C31',2,'mc','auto','학급 이야기책 회의에서 루아의 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"학급 이야기책 회의에서 루아의 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"책의 형태에는 등수가 없고 독자에 따라 알맞은 형태가 달라지기 때문에","correct":true},{"t":"화면으로 보는 책은 만들 수 없기 때문에","mis":"K6-2-u6-X38"},{"t":"종이책이 언제나 가장 좋기 때문에","mis":"K6-2-u6-X38"},{"t":"형태는 표지 다음에 정하기 때문에","mis":"K6-2-u6-X41"}],"explanation":["형태마다 잘하는 일이 달라요.","등수가 없어요.","독자에 따라 골라요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#17','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C5',3,'mc','auto','「내 어깨가 강둑까지 올라간다」는 말하는 이의 어떤 마음을 나타내나요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":17,"concept":"K6-2-u6-C5","difficulty":3,"kind":"mc","stem":"「내 어깨가 강둑까지 올라간다」는 말하는 이의 어떤 마음을 나타내나요?","options":[{"t":"아빠보다 한 걸음 더 가서 뿌듯하고 자랑스러운 마음","correct":true},{"t":"어깨가 아파 들어 올린 것","mis":"K6-2-u6-X08"},{"t":"강둑에 올라가 쉬고 싶은 마음","mis":"K6-2-u6-X08"},{"t":"돌이 가라앉아 속상한 마음","mis":"K6-2-u6-X07"}],"explanation":["어깨가 실제로 강둑까지 가지 않아요.","아빠 돌보다 한 걸음 더 갔어요.","으쓱한 마음을 빗대었어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#18','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',3,'mc','auto','도윤이의 「소풍」을 시답게 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X04','K6-2-u6-X03']::text[],false,'{"seq":18,"concept":"K6-2-u6-C13","difficulty":3,"kind":"mc","stem":"도윤이의 「소풍」을 시답게 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"보물찾기 쪽지를 찾은 순간만 남기고, 그때 본 것과 마음을 짧게 나누어 쓴다","correct":true},{"t":"빠진 일이 없도록 점심 메뉴와 공원 이름까지 더 넣는다","mis":"K6-2-u6-X16"},{"t":"어려운 낱말로 바꾸어 쓴다","mis":"K6-2-u6-X04"},{"t":"빗댄 표현을 다섯 개 넘게 넣는다","mis":"K6-2-u6-X03"}],"explanation":["더 넣으면 더 목록이 돼요.","어려운 말이나 개수는 기준이 아니에요.","인상 깊은 순간만 남겨요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#19','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C19',3,'mc','auto','서하의 낭송 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C19","difficulty":3,"kind":"mc","stem":"서하의 낭송 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 정하지 않았고 음악과 영상이 낭송을 덮어, 멋있게 들리려다 시의 마음이 건너가지 못한다","correct":true},{"t":"목소리가 가장 크니 잘한 계획이다","mis":"K6-2-u6-X21"},{"t":"음악과 영상이 화려하니 잘한 계획이다","mis":"K6-2-u6-X22"},{"t":"목소리를 줄이고 음악만 크게 하면 된다","mis":"K6-2-u6-X22"}],"explanation":["크기와 화려함이 목표가 아니에요.","음악과 영상이 낭송을 덮으면 안 돼요.","마음이 건너가게 해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#20','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C24',3,'mc','auto','지안이의 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X27','K6-2-u6-X36']::text[],false,'{"seq":20,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"지안이의 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"성격을 바꾼 생각은 좋지만 행동이 그대로이고 로봇이 갑자기 나와, 바뀐 것에서 다음 일이 이어지지 않는다","correct":true},{"t":"로봇이 나와 가장 기발하니 잘 바꾼 계획이다","mis":"K6-2-u6-X30"},{"t":"성격을 바꾸었으니 행동은 그대로여도 된다","mis":"K6-2-u6-X27"},{"t":"하나만 바꾸었으니 잘못 바꾼 계획이다","mis":"K6-2-u6-X36"}],"explanation":["잘한 점을 먼저 짚어요.","성격과 행동이 어긋났어요.","갑작스러운 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#21','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C33',3,'mc','auto','학급 이야기책 회의에서 다온이의 말을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41']::text[],false,'{"seq":21,"concept":"K6-2-u6-C33","difficulty":3,"kind":"mc","stem":"학급 이야기책 회의에서 다온이의 말을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이야기를 먼저 완성하고, 꾸미기는 읽기 좋게 돕는 만큼만 하자.」","correct":true},{"t":"「표지를 나흘 동안 꾸미자.」","mis":"K6-2-u6-X41"},{"t":"「글은 빼고 그림만 넣자.」","mis":"K6-2-u6-X41"},{"t":"「꾸미기를 가장 잘한 모둠이 이긴 거야.」","mis":"K6-2-u6-X41"}],"explanation":["표지가 이야기를 덮으면 안 돼요.","책은 담긴 이야기로 남아요.","이야기가 먼저예요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#22','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C24',3,'mc','auto','이 단원에서 배운 것과 맞는 말은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X02','K6-2-u6-X09']::text[],false,'{"seq":22,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것과 맞는 말은 어느 것인가요?","options":[{"t":"표현은 마음에 알맞은지로 고르고, 바꾸기는 뒤가 이어지는지로 본다","correct":true},{"t":"빗댄 표현이 많을수록 좋은 시이고, 놀랍게 바꿀수록 좋은 이야기다","mis":"K6-2-u6-X30"},{"t":"시는 특별한 경험으로만 쓰고, 이야기는 그대로 옮겨야 한다","mis":"K6-2-u6-X02"},{"t":"시와 이야기는 길게 쓸수록 좋다","mis":"K6-2-u6-X09"}],"explanation":["개수가 아니라 알맞음이에요.","놀라움이 아니라 이어짐이에요.","시도 이야기도 같은 눈으로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#23','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',4,'mc','auto','도윤이의 「소풍」과 「물수제비」를 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X03','K6-2-u6-X02']::text[],false,'{"seq":23,"concept":"K6-2-u6-C13","difficulty":4,"kind":"mc","stem":"도윤이의 「소풍」과 「물수제비」를 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소풍」은 겪은 일을 다 넣어 마음이 흐리지만, 「물수제비」는 돌을 던진 순간만 골라 뿌듯한 마음이 또렷하다","correct":true},{"t":"「소풍」이 빠뜨린 것이 없어 더 좋은 시다","mis":"K6-2-u6-X16"},{"t":"「물수제비」가 빗댄 표현이 많아서 더 좋은 시다","mis":"K6-2-u6-X03"},{"t":"「소풍」은 대단한 일이 아니라서 시가 될 수 없다","mis":"K6-2-u6-X02"}],"explanation":["빠짐없이 다 넣는 것이 장점이 아니에요.","개수로 견주지 않아요.","고르고 버려 또렷해졌는지 봐요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#24','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C15',4,'essay','teacher','도윤이의 「소풍」에서 고쳐야 할 점을 세 가지 찾아 까닭과 함께 쓰고, 가장 인상 깊은 순간만 남겨 연을 나눈 짧은 시로 고쳐 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C15","difficulty":4,"kind":"essay","stem":"도윤이의 「소풍」에서 고쳐야 할 점을 세 가지 찾아 까닭과 함께 쓰고, 가장 인상 깊은 순간만 남겨 연을 나눈 짧은 시로 고쳐 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 첫째, 세수 · 버스 · 김밥처럼 겪은 일을 다 넣어 어느 순간이 중요한지 알 수 없다. 둘째, 장면이 바뀌어도 연을 나누지 않아 따라가기 어렵다. 셋째, 제목 「소풍」에는 쪽지를 찾은 기쁨이 드러나지 않는다. 고쳐 쓴 시 — 「쪽지 한 장」 / 돌 틈에 접힌 / 하얀 쪽지 하나 // 손끝이 먼저 / 알아챘다 // 오늘 공원은 / 내 것이었다","scoring_points":["고칠 점 세 가지와 까닭을 썼는가","인상 깊은 순간만 남겼는가","장면에 맞게 연을 나누고 마음이 드러나는 제목을 붙였는가"]},"explanation":["다 넣은 것을 골라내요.","장면에 맞게 연을 나눠요.","마음이 드러나는 제목을 붙여요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#25','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C3',4,'essay','teacher','「좋은 시는 비유를 많이 넣은 시가 아니다.」라는 약속을 이 단원에서 읽은 시 두 편을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C3","difficulty":4,"kind":"essay","stem":"「좋은 시는 비유를 많이 넣은 시가 아니다.」라는 약속을 이 단원에서 읽은 시 두 편을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 「우유갑」에는 빗댄 표현이 하나뿐이고, 「우산 하나」에는 빗댄 표현이 하나도 없다. 그런데도 「우유갑」은 삐친 마음이 조금은 풀렸으면 하는 마음을, 「우산 하나」는 친구 쪽으로 우산을 기울여 내 어깨가 젖은 마음을 잘 전한다. 그러므로 좋은 시는 빗댄 표현의 개수로 정해지지 않고, 그 마음에 알맞은 표현을 골랐는가로 정해진다.","scoring_points":["시 두 편을 예로 들었는가","빗댄 표현이 적어도 마음이 전해짐을 썼는가","개수가 아니라 알맞음이 기준이라고 썼는가"]},"explanation":["빗댄 표현을 세어 봐요.","마음이 전해지는지 봐요.","알맞음이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#1','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C2',1,'ox','auto','교실에서 우유갑을 여느라 애쓴 일도 시의 글감이 될 수 있어요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":1,"concept":"K6-2-u6-C2","difficulty":1,"kind":"ox","stem":"교실에서 우유갑을 여느라 애쓴 일도 시의 글감이 될 수 있어요.","answer":"O","reason_options":[{"t":"그때 마음이 움직였다면 작은 일도 글감이 되기 때문에","correct":true},{"t":"우유갑은 누구나 아는 물건이기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["「우유갑」이 바로 그런 시예요.","대단한 일이 아니어도 돼요.","마음이 움직였는가가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#2','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C3',1,'mc','auto','좋은 표현을 고르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"mc","stem":"좋은 표현을 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 마음에 알맞은가","correct":true},{"t":"빗댄 표현이 몇 개인가","mis":"K6-2-u6-X03"},{"t":"낱말이 얼마나 어려운가","mis":"K6-2-u6-X04"},{"t":"시가 얼마나 긴가","mis":"K6-2-u6-X03"}],"explanation":["개수로 세지 않아요.","어려운 말도 기준이 아니에요.","알맞음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#3','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C4',1,'mc','auto','「토끼와 자라」에서 인물에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"「토끼와 자라」에서 인물에 해당하는 것은 어느 것인가요?","options":[{"t":"자라","correct":true},{"t":"바닷속 용궁","mis":"K6-2-u6-X05"},{"t":"토끼가 달아난 일","mis":"K6-2-u6-X05"},{"t":"뭍에 있는 산","mis":"K6-2-u6-X05"}],"explanation":["용궁과 산은 곳이라 배경이에요.","달아난 일은 사건이에요.","자라는 이야기에 나오는 인물이에요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#4','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C8',1,'mc','auto','「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법은 무엇인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법은 무엇인가요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"흉내 내는 말","mis":"K6-2-u6-X12"}],"explanation":["직유법은 「처럼 · 같이」를 써요.","은유법은 그것이라고 말해 버려요.","「빈 운동장이다」가 은유법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#5','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C9',1,'mc','auto','「지우개 가루」에서 만진 것을 살린 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":5,"concept":"K6-2-u6-C9","difficulty":1,"kind":"mc","stem":"「지우개 가루」에서 만진 것을 살린 표현은 어느 것인가요?","options":[{"t":"손날로 쓱","correct":true},{"t":"틀린 답이 눈처럼 쌓여 있다","mis":"K6-2-u6-X12"},{"t":"털어 내면 사라지지만","mis":"K6-2-u6-X12"},{"t":"공책 위에","mis":"K6-2-u6-X12"}],"explanation":["손날로 가루를 쓸어 내는 감각이에요.","눈처럼은 빗댄 것이에요.","만진 느낌을 그대로 살렸어요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#6','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C13',1,'ox','auto','시는 넣는 일보다 버리는 일이 더 커요.',ARRAY['K6-2-u6-X17']::text[],false,'{"seq":6,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"시는 넣는 일보다 버리는 일이 더 커요.","answer":"O","reason_options":[{"t":"인상 깊은 순간만 남겨야 그 마음이 또렷해지기 때문에","correct":true},{"t":"시는 무조건 짧아야 하기 때문에","mis":"K6-2-u6-X17"}],"mis":"K6-2-u6-X17","explanation":["다 넣으면 목록이 돼요.","짧게 하려는 것이 목적이 아니에요.","골라서 또렷하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#7','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C19',1,'mc','auto','낭송하는 목소리의 크기로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X23','K6-2-u6-X22']::text[],false,'{"seq":7,"concept":"K6-2-u6-C19","difficulty":1,"kind":"mc","stem":"낭송하는 목소리의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"뒤에 앉은 사람까지 들릴 만큼, 부분마다 마음에 맞는 크기로","correct":true},{"t":"처음부터 끝까지 가장 큰 목소리로","mis":"K6-2-u6-X21"},{"t":"옆 사람에게만 들릴 만큼 작게","mis":"K6-2-u6-X23"},{"t":"배경 음악보다 작게","mis":"K6-2-u6-X22"}],"explanation":["무조건 크게도 아니에요.","들리지 않으면 안 돼요.","마음에 맞는 크기로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#8','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C31',1,'mc','auto','교실에 두고 아무 때나 손으로 넘겨 볼 수 있는 책의 형태는 어느 것인가요?',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":8,"concept":"K6-2-u6-C31","difficulty":1,"kind":"mc","stem":"교실에 두고 아무 때나 손으로 넘겨 볼 수 있는 책의 형태는 어느 것인가요?","options":[{"t":"종이책","correct":true},{"t":"소리로 담는 책","mis":"K6-2-u6-X38"},{"t":"화면으로 보는 책","mis":"K6-2-u6-X38"},{"t":"어느 형태도 할 수 없다","mis":"K6-2-u6-X38"}],"explanation":["소리로 담는 책은 귀로 들어요.","화면으로 보는 책은 멀리 보내요.","종이책은 넘겨 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#9','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C5',2,'mc','auto','「물수제비」를 읽고 떠오르는 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「물수제비」를 읽고 떠오르는 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"돌이 물 위를 톡, 톡, 톡 튀어 가는 모습","correct":true},{"t":"돌이 하늘 높이 날아가는 모습","mis":"K6-2-u6-X07"},{"t":"아빠가 강에 빠지는 모습","mis":"K6-2-u6-X07"},{"t":"강물이 꽁꽁 언 모습","mis":"K6-2-u6-X07"}],"explanation":["톡, 톡, 톡 소리가 들려요.","돌이 물 위를 걸어가요.","물 위를 튀어 가는 장면이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#10','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C7',2,'mc','auto','「세 걸음 만에 / 강물 속으로 숨어도」에서 「숨어도」는 무엇을 빗댄 것인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X10']::text[],false,'{"seq":10,"concept":"K6-2-u6-C7","difficulty":2,"kind":"mc","stem":"「세 걸음 만에 / 강물 속으로 숨어도」에서 「숨어도」는 무엇을 빗댄 것인가요?","options":[{"t":"돌이 물속으로 가라앉아 보이지 않게 된 것","correct":true},{"t":"돌이 바위 뒤에 숨어 있는 것","mis":"K6-2-u6-X08"},{"t":"말하는 이가 부끄러워 숨은 것","mis":"K6-2-u6-X08"},{"t":"강물이 마른 것","mis":"K6-2-u6-X10"}],"explanation":["돌이 실제로 숨은 것이 아니에요.","가라앉아 보이지 않게 되었어요.","그 모습을 숨는 것에 빗대었어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#11','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C13',2,'mc','auto','도윤이가 「소풍」에서 남기면 좋을 가장 인상 깊은 순간은 어느 것인가요?',ARRAY['K6-2-u6-X09']::text[],false,'{"seq":11,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"도윤이가 「소풍」에서 남기면 좋을 가장 인상 깊은 순간은 어느 것인가요?","options":[{"t":"보물찾기에서 쪽지를 찾은 순간","correct":true},{"t":"아침에 세수를 한 일","mis":"K6-2-u6-X09"},{"t":"버스를 탄 일","mis":"K6-2-u6-X09"},{"t":"집에 돌아온 일","mis":"K6-2-u6-X09"}],"explanation":["세수와 버스는 누구나 한 일이에요.","「너무 좋았다」는 마음이 움직인 곳이에요.","그 순간을 남겨요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#12','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C15',2,'ox','auto','고쳐 쓰기는 틀린 곳을 벌하는 일이에요.',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"ox","stem":"고쳐 쓰기는 틀린 곳을 벌하는 일이에요.","answer":"X","reason_options":[{"t":"고쳐 쓰기는 시가 마음을 더 잘 전하도록 자라게 하는 단계이기 때문에","correct":true},{"t":"고칠 곳이 있으면 처음부터 잘못 쓴 것이기 때문에","mis":"K6-2-u6-X19"}],"mis":"K6-2-u6-X19","explanation":["누구나 고쳐 써요.","지운 줄은 다음 시에 써도 돼요.","고쳐 쓰기는 시를 자라게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#13','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C17',2,'mc','auto','서하의 계획에서 배경 음악을 고칠 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":13,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"서하의 계획에서 배경 음악을 고칠 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"시의 분위기와 어울리는 음악을 목소리보다 작게 깐다","correct":true},{"t":"더 신나는 노래로 바꾸어 더 크게 튼다","mis":"K6-2-u6-X22"},{"t":"노래를 두 곡 겹쳐 튼다","mis":"K6-2-u6-X22"},{"t":"음악만 틀고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["목소리보다 크면 시가 덮여요.","분위기와 어울려야 해요.","작게 깔아 낭송을 도와요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#14','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C22',2,'mc','auto','「개미와 베짱이」의 때를 「겨울이 오지 않는 섬」으로 바꾸면 달라질 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X28','K6-2-u6-X29']::text[],false,'{"seq":14,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"「개미와 베짱이」의 때를 「겨울이 오지 않는 섬」으로 바꾸면 달라질 일로 알맞은 것은 어느 것인가요?","options":[{"t":"먹이를 모아 두지 않아도 굶지 않으니 베짱이가 개미를 찾아갈 까닭이 사라진다","correct":true},{"t":"아무것도 달라지지 않는다","mis":"K6-2-u6-X28"},{"t":"개미의 이름이 바뀐다","mis":"K6-2-u6-X28"},{"t":"하늘에서 갑자기 로봇이 내려온다","mis":"K6-2-u6-X29"}],"explanation":["배경이 바뀌면 할 수 있는 일이 바뀌어요.","겨울이 없으면 굶을 걱정이 없어요.","그래서 사건도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#15','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',2,'mc','auto','지안이의 계획에서 바꾼 성격과 맞지 않는 곳은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X35']::text[],false,'{"seq":15,"concept":"K6-2-u6-C28","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 바꾼 성격과 맞지 않는 곳은 어느 것인가요?","options":[{"t":"전개 — 베짱이가 여름 내내 낮잠만 잔다","correct":true},{"t":"바꿀 것 — 남을 위해 노래를 연습하는 성격","mis":"K6-2-u6-X27"},{"t":"원래 이야기 — 베짱이가 개미를 찾아간다","mis":"K6-2-u6-X27"},{"t":"맞지 않는 곳은 없다","mis":"K6-2-u6-X35"}],"explanation":["남을 위해 연습하는 성격으로 바꾸었어요.","그런데 하는 일은 낮잠이에요.","성격과 행동이 어긋나요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#16','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C32',2,'mc','auto','학급 이야기책 회의에서 알맞게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X39','K6-2-u6-X42']::text[],false,'{"seq":16,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"학급 이야기책 회의에서 알맞게 말한 친구는 누구인가요?","options":[{"t":"나래","correct":true},{"t":"다온","mis":"K6-2-u6-X41"},{"t":"시후","mis":"K6-2-u6-X39"},{"t":"하람","mis":"K6-2-u6-X42"}],"explanation":["다온은 표지부터, 시후는 독자를 나중에 정하자고 했어요.","하람은 고칠 점부터 말하자고 했어요.","나래는 중심 사건과 인물부터 정하자고 했어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#17','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C8',3,'error','auto','「물수제비」의 표현을 가렸어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X12','K6-2-u6-X11']::text[],false,'{"seq":17,"concept":"K6-2-u6-C8","difficulty":3,"kind":"error","stem":"「물수제비」의 표현을 가렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다인 — 「‘톡, 톡, 톡’은 다른 것에 빗댄 은유법이야.」","correct":true,"mis_target":"K6-2-u6-X12"},{"t":"도하 — 「‘돌이 물 위를 걸어간다’는 돌을 걷는 것에 빗댔어.」","mis":"K6-2-u6-X12"},{"t":"이서 — 「‘처럼’이 없으니 직유법은 아니야.」","mis":"K6-2-u6-X11"}],"explanation":["도하와 이서는 바르게 말했어요.","톡, 톡, 톡은 들은 소리를 살린 감각적 표현이에요.","다인은 감각과 빗댐을 헷갈렸어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#18','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C15',3,'error','auto','도윤이의 시를 함께 고쳐 썼어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X19','K6-2-u6-X14','K6-2-u6-X16']::text[],false,'{"seq":18,"concept":"K6-2-u6-C15","difficulty":3,"kind":"error","stem":"도윤이의 시를 함께 고쳐 썼어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「글씨를 더 예쁘게 쓰면 좋은 시가 될 거야.」","correct":true,"mis_target":"K6-2-u6-X19"},{"t":"서아 — 「장면이 바뀌는 곳에서 연을 나누자.」","mis":"K6-2-u6-X14"},{"t":"민재 — 「세수한 줄은 없어도 되니 지우자.」","mis":"K6-2-u6-X16"}],"explanation":["서아와 민재는 시를 고쳐 쓸 때 볼 것을 봤어요.","글씨는 시의 마음과 상관없어요.","하율은 겉모습을 봤어요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#19','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C18',3,'error','auto','서하의 낭송을 듣고 조언했어요. 알맞지 않게 조언한 친구는 누구인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C18","difficulty":3,"kind":"error","stem":"서하의 낭송을 듣고 조언했어요. 알맞지 않게 조언한 친구는 누구인가요?","options":[{"t":"하린 — 「그냥 잘했어. 다음에도 그렇게 해.」","correct":true,"mis_target":"K6-2-u6-X25"},{"t":"도하 — 「마지막 연은 조금 천천히 읽으면 뿌듯한 마음이 더 살아날 것 같아.」","mis":"K6-2-u6-X25"},{"t":"나은 — 「음악을 작게 하면 네 목소리가 더 또렷이 들릴 거야.」","mis":"K6-2-u6-X22"}],"explanation":["도하와 나은은 어느 부분을 어떻게 할지 말했어요.","하린의 말로는 무엇을 바꿀지 몰라요.","조언은 구체적으로 해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#20','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',3,'mc','auto','지안이의 계획에서 바꾼 성격에 맞게 전개를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X29','K6-2-u6-X36']::text[],false,'{"seq":20,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"지안이의 계획에서 바꾼 성격에 맞게 전개를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"베짱이가 여름 내내 개미들이 힘들 때 들을 노래를 연습한다","correct":true},{"t":"베짱이가 여름 내내 낮잠을 더 오래 잔다","mis":"K6-2-u6-X27"},{"t":"베짱이가 갑자기 하늘을 날 수 있게 된다","mis":"K6-2-u6-X29"},{"t":"개미의 성격도 바꾸고 배경도 우주로 바꾼다","mis":"K6-2-u6-X36"}],"explanation":["남을 위해 연습하는 성격으로 바꾸었어요.","그러면 하는 일도 연습이 되어야 해요.","하나를 바꾸고 따라 움직이게 해요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#21','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C31',3,'mc','auto','회의에서 독자를 「우리 반 친구들과 가정에 계신 분들」로 정했다면 형태를 고르는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":21,"concept":"K6-2-u6-C31","difficulty":3,"kind":"mc","stem":"회의에서 독자를 「우리 반 친구들과 가정에 계신 분들」로 정했다면 형태를 고르는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"집에서도 볼 수 있어야 하니 화면으로 보는 책이 알맞고, 교실용 종이책을 함께 두어도 된다","correct":true},{"t":"독자와 상관없이 가장 새로운 형태를 고른다","mis":"K6-2-u6-X38"},{"t":"가장 빨리 끝나는 형태를 고른다","mis":"K6-2-u6-X38"},{"t":"독자는 나중에 다시 정한다","mis":"K6-2-u6-X39"}],"explanation":["독자가 정해지면 형태가 따라와요.","집에서도 보려면 화면이 알맞아요.","형태에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#22','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C34',3,'mc','auto','두 문장의 빈칸에 들어갈 낱말을 차례대로 바르게 짝 지은 것은 어느 것인가요? 「우체국에서 소포를 (   ). / 게시판에 그림을 (   ).」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":22,"concept":"K6-2-u6-C34","difficulty":3,"kind":"mc","stem":"두 문장의 빈칸에 들어갈 낱말을 차례대로 바르게 짝 지은 것은 어느 것인가요? 「우체국에서 소포를 (   ). / 게시판에 그림을 (   ).」","options":[{"t":"부쳤다 · 붙였다","correct":true},{"t":"붙였다 · 부쳤다","mis":"K6-2-u6-X43"},{"t":"부쳤다 · 부쳤다","mis":"K6-2-u6-X43"},{"t":"붙였다 · 붙였다","mis":"K6-2-u6-X43"}],"explanation":["소포를 보내는 것은 부치다예요.","그림을 떨어지지 않게 대는 것은 붙이다예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#23','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C19',4,'mc','auto','서하가 낭송 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X23']::text[],false,'{"seq":23,"concept":"K6-2-u6-C19","difficulty":4,"kind":"mc","stem":"서하가 낭송 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마음 — 아빠를 이긴 뿌듯함 / 셋째 연은 조금 느리게, 넷째 연은 힘 있게 / 물소리를 작게 깔고 영상은 쓰지 않는다","correct":true},{"t":"마음 — 정하지 않음 / 모든 연 더 크게 / 음악 두 곡","mis":"K6-2-u6-X21"},{"t":"마음 — 뿌듯함 / 모든 연 똑같이 / 음악을 목소리보다 크게","mis":"K6-2-u6-X22"},{"t":"마음 — 뿌듯함 / 아주 작게 속삭이듯 / 음악 없음","mis":"K6-2-u6-X23"}],"explanation":["마음부터 정해요.","연마다 목소리를 달리해요.","음악은 작게, 돕는 만큼만 써요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#24','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C16',4,'essay','teacher','서하의 낭송 계획에서 고쳐야 할 점을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 「물수제비」에 알맞은 낭송 계획을 다시 세우세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"서하의 낭송 계획에서 고쳐야 할 점을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 「물수제비」에 알맞은 낭송 계획을 다시 세우세요.","answer_guide":{"answer":"예: 첫째, 전하고 싶은 마음을 정하지 않아 목소리와 속도를 정할 기준이 없다. 둘째, 모든 연을 가장 큰 목소리로 똑같이 빠르게 읽으면 연마다 다른 마음이 살지 않는다. 셋째, 신나는 노래를 목소리보다 크게 틀고 영상을 쉬지 않고 바꾸면 시를 덮어 버린다. 다시 세운 계획 — 마음: 아빠보다 한 걸음 더 간 뿌듯함. 첫째 · 둘째 연은 가볍고 또렷하게, 톡, 톡, 톡은 끊어서. 셋째 연은 조금 느리게. 넷째 연은 힘을 실어 천천히. 물 흐르는 소리를 목소리보다 작게 깔고 영상은 쓰지 않는다.","scoring_points":["고칠 점 세 가지와 까닭을 썼는가","전하고 싶은 마음을 정했는가","연마다 목소리와 속도, 음악을 돕는 만큼 정했는가"]},"explanation":["마음부터 정해요.","연마다 달리 읽어요.","음악은 작게, 돕는 만큼."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#25','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C24',4,'essay','teacher','「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 「금도끼 은도끼」를 바꾼 「마르지 않는 샘」을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C24","difficulty":4,"kind":"essay","stem":"「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 「금도끼 은도끼」를 바꾼 「마르지 않는 샘」을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 「마르지 않는 샘」은 때를 가뭄이 든 해로 하나만 바꾸었다. 그러자 나무꾼이 마을의 물을 걱정하게 되고, 그래서 금도끼를 거절하고, 그래서 마을에 샘이 생기는 일이 앞이 뒤를 부르며 자연스럽게 이어졌다. 이야기에 우주선이 내려오는 것처럼 많이 · 놀랍게 바꾸면 이어지지 않는다. 그러므로 바꾸어 쓰기는 얼마나 많이 바꾸었는가가 아니라 바뀐 것에서 다음 일이 자연스럽게 나오는가로 가늠한다.","scoring_points":["바꾼 것이 하나임을 썼는가","앞이 뒤를 부르는 흐름을 썼는가","많이 · 놀랍게가 아니라 이어짐이 기준이라고 썼는가"]},"explanation":["무엇을 바꾸었는지 봐요.","앞이 뒤를 부르는지 봐요.","이어짐이 기준이에요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#1','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C2',1,'mc','auto','글감을 고를 때 스스로에게 던질 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X04']::text[],false,'{"seq":1,"concept":"K6-2-u6-C2","difficulty":1,"kind":"mc","stem":"글감을 고를 때 스스로에게 던질 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"그때 내 마음이 움직였는가","correct":true},{"t":"남들이 놀랄 만한 일인가","mis":"K6-2-u6-X02"},{"t":"멀리 여행을 가서 겪은 일인가","mis":"K6-2-u6-X02"},{"t":"어려운 낱말을 쓸 수 있는 일인가","mis":"K6-2-u6-X04"}],"explanation":["놀랄 일이나 여행이 아니어도 돼요.","어려운 낱말도 기준이 아니에요.","마음이 움직였는가 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#2','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C13',1,'ox','auto','빗댄 표현이 하나도 없으면 시라고 할 수 없어요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":2,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"빗댄 표현이 하나도 없으면 시라고 할 수 없어요.","answer":"X","reason_options":[{"t":"「우산 하나」처럼 빗댄 표현이 없어도 마음이 전해지는 시가 있기 때문에","correct":true},{"t":"시에는 반드시 빗댄 표현이 들어가야 하기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["비유는 규칙이 아니에요.","쓸 수 있는 방법이에요.","마음이 전해지면 시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#3','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C4',1,'sa','auto','이야기 속에서 일어난 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"sa","stem":"이야기 속에서 일어난 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["사건"],"explanation":["인물은 누가예요.","배경은 언제 어디예요.","일어난 일은 사건이에요."],"mis":"K6-2-u6-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#4','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C7',1,'ox','auto','빗댈 때에는 두 대상 사이에 비슷한 점이 있어야 해요.',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":4,"concept":"K6-2-u6-C7","difficulty":1,"kind":"ox","stem":"빗댈 때에는 두 대상 사이에 비슷한 점이 있어야 해요.","answer":"O","reason_options":[{"t":"비슷한 점이 있어야 빗댄 까닭을 말로 옮길 수 있기 때문에","correct":true},{"t":"아무것에나 빗대어도 마음이 전해지기 때문에","mis":"K6-2-u6-X10"}],"mis":"K6-2-u6-X10","explanation":["주전자와 아침 집은 바쁘고 뜨거워요.","닮은 점이 있어야 빗대요.","그 점을 말로 옮길 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#5','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C10',1,'ox','auto','시는 연과 행으로 나누어 읽으면 노래하는 듯한 리듬이 느껴져요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":5,"concept":"K6-2-u6-C10","difficulty":1,"kind":"ox","stem":"시는 연과 행으로 나누어 읽으면 노래하는 듯한 리듬이 느껴져요.","answer":"O","reason_options":[{"t":"연과 행이 나뉘는 곳에서 쉬어 읽게 되기 때문에","correct":true},{"t":"연과 행은 꼭 지켜야 하는 규칙이기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["연과 행이 리듬을 만들어요.","그래도 규칙은 아니에요.","쓸 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#6','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C11',1,'mc','auto','짝의 경험을 자세히 떠올리도록 도우려고 해요. 알맞은 물음은 어느 것인가요?',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":6,"concept":"K6-2-u6-C11","difficulty":1,"kind":"mc","stem":"짝의 경험을 자세히 떠올리도록 도우려고 해요. 알맞은 물음은 어느 것인가요?","options":[{"t":"「그때 본 것과 들은 것은 무엇이었어?」","correct":true},{"t":"「그 일은 몇 시에 일어났어?」","mis":"K6-2-u6-X15"},{"t":"「시를 몇 줄로 쓸 거야?」","mis":"K6-2-u6-X15"},{"t":"「누가 제일 잘했어?」","mis":"K6-2-u6-X15"}],"explanation":["시각과 줄 수는 도움이 되지 않아요.","그 순간으로 다시 들어가게 해요.","본 것과 들은 것을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#7','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',1,'mc','auto','낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X21','K6-2-u6-X20']::text[],false,'{"seq":7,"concept":"K6-2-u6-C16","difficulty":1,"kind":"mc","stem":"낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"전하고 싶은 마음 정하기 → 목소리와 속도 찾기 → 효과음 · 음악 살펴보기 → 연습하기","correct":true},{"t":"배경 음악 고르기 → 영상 꾸미기 → 낭송하기","mis":"K6-2-u6-X22"},{"t":"가장 큰 목소리 정하기 → 낭송하기","mis":"K6-2-u6-X21"},{"t":"연습 없이 바로 낭송하기","mis":"K6-2-u6-X20"}],"explanation":["마음을 먼저 정해요.","그 마음에 어울리는 목소리와 속도를 찾아요.","여러 번 연습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#8','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C34',1,'mc','auto','「웃어른께 정중히 올리다」라는 뜻의 낱말은 어느 것인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"「웃어른께 정중히 올리다」라는 뜻의 낱말은 어느 것인가요?","options":[{"t":"바치다","correct":true},{"t":"받치다","mis":"K6-2-u6-X43"},{"t":"부치다","mis":"K6-2-u6-X43"},{"t":"붙이다","mis":"K6-2-u6-X43"}],"explanation":["받치다는 밑에서 괴는 거예요.","부치다는 보내는 거예요.","웃어른께 올리는 것은 바치다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#9','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C5',2,'ox','auto','「물수제비」에서 돌은 실제로 다리가 있어 물 위를 걸었어요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"ox","stem":"「물수제비」에서 돌은 실제로 다리가 있어 물 위를 걸었어요.","answer":"X","reason_options":[{"t":"물 위를 튀어 가는 돌의 모습을 걸어가는 것에 빗대었기 때문에","correct":true},{"t":"시에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["돌에는 다리가 없어요.","튀어 가는 모습이 걸음 같아요.","빗댄 표현으로 읽어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#10','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C8',2,'ox','auto','「돌이 물 위를 걸어간다」는 「처럼」이 없으니 직유법이 아니에요.',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":10,"concept":"K6-2-u6-C8","difficulty":2,"kind":"ox","stem":"「돌이 물 위를 걸어간다」는 「처럼」이 없으니 직유법이 아니에요.","answer":"O","reason_options":[{"t":"직유법은 「같이 · 처럼 · 듯이」를 써서 바로 견주는 방법이기 때문에","correct":true},{"t":"「처럼」이 없어도 모든 빗댄 표현은 직유법이기 때문에","mis":"K6-2-u6-X11"}],"mis":"K6-2-u6-X11","explanation":["「처럼 · 같이 · 듯이」가 없어요.","그래서 직유법이 아니에요.","돌을 걷는 것처럼 바로 말해 버렸어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#11','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C6',2,'mc','auto','「소풍」을 고쳐 쓸 때 연을 나누는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X14']::text[],false,'{"seq":11,"concept":"K6-2-u6-C6","difficulty":2,"kind":"mc","stem":"「소풍」을 고쳐 쓸 때 연을 나누는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면이 바뀌는 곳","correct":true},{"t":"아무 데서나 세 줄마다","mis":"K6-2-u6-X14"},{"t":"문장이 끝날 때마다 빠짐없이","mis":"K6-2-u6-X14"},{"t":"연은 나누지 않는다","mis":"K6-2-u6-X14"}],"explanation":["연은 줄 수로 나누지 않아요.","장면이 바뀔 때 나눠요.","읽는 사람이 장면을 따라가요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#12','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',2,'mc','auto','「지우개 가루」의 제목에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X18']::text[],false,'{"seq":12,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"「지우개 가루」의 제목에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"시 속 장면이 담겨 있어 읽고 나면 여러 번 틀리며 애쓴 마음이 떠오른다","correct":true},{"t":"빗댄 표현이 없어서 좋은 제목이 아니다","mis":"K6-2-u6-X03"},{"t":"맨 처음에 붙였는지 알 수 없으니 잘못된 제목이다","mis":"K6-2-u6-X18"},{"t":"제목은 반드시 길어야 한다","mis":"K6-2-u6-X18"}],"explanation":["제목에 꼭 빗댄 표현이 있어야 하지 않아요.","언제 붙였는지는 상관없어요.","읽고 나서 고개가 끄덕여지면 좋아요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#13','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',2,'ox','auto','서하처럼 모든 연을 똑같이 가장 큰 목소리로 빠르게 읽는 것이 알맞아요.',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":13,"concept":"K6-2-u6-C16","difficulty":2,"kind":"ox","stem":"서하처럼 모든 연을 똑같이 가장 큰 목소리로 빠르게 읽는 것이 알맞아요.","answer":"X","reason_options":[{"t":"연마다 담긴 마음이 달라 목소리와 속도도 달라져야 하기 때문에","correct":true},{"t":"같은 목소리로 읽어야 마음이 잘 건너가기 때문에","mis":"K6-2-u6-X20"}],"mis":"K6-2-u6-X20","explanation":["「물수제비」의 연마다 마음이 달라요.","목소리는 그 마음을 따라가요.","부분마다 정해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#14','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',2,'ox','auto','이야기를 바꾸어도 앞의 일이 뒤의 일을 불러오도록 이어져야 해요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":14,"concept":"K6-2-u6-C23","difficulty":2,"kind":"ox","stem":"이야기를 바꾸어도 앞의 일이 뒤의 일을 불러오도록 이어져야 해요.","answer":"O","reason_options":[{"t":"원인과 결과로 이어져야 이야기가 자연스럽기 때문에","correct":true},{"t":"바꾼 이야기는 앞뒤가 이어지지 않아도 되기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["바뀌었지만 끊기지 않아야 해요.","앞이 뒤를 불러요.","그래야 자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#15','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',2,'ox','auto','지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":15,"concept":"K6-2-u6-C23","difficulty":2,"kind":"ox","stem":"지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.","answer":"X","reason_options":[{"t":"앞에서 로봇이 나올 까닭이 없어 갑작스럽기 때문에","correct":true},{"t":"놀라운 일은 언제나 앞의 일과 이어지기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["앞의 일에 로봇은 없었어요.","갑자기 나타나면 이어지지 않아요.","앞이 뒤를 불러야 해요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#16','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C31',2,'ox','auto','시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.',ARRAY['K6-2-u6-X39']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"ox","stem":"시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.","answer":"X","reason_options":[{"t":"독자가 정해져야 책의 형태와 내용이 따라 정해지기 때문에","correct":true},{"t":"독자는 책의 내용과 상관없기 때문에","mis":"K6-2-u6-X39"}],"mis":"K6-2-u6-X39","explanation":["세윤이도 독자부터 정하자고 했어요.","독자가 형태를 정해요.","먼저 정해요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#17','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C7',3,'mc','auto','「물수제비」에서 돌이 튀어 가는 모습을 「걸어간다」에 빗댄 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X03','K6-2-u6-X10']::text[],false,'{"seq":17,"concept":"K6-2-u6-C7","difficulty":3,"kind":"mc","stem":"「물수제비」에서 돌이 튀어 가는 모습을 「걸어간다」에 빗댄 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"돌이 물 위에 한 번씩 닿았다 떨어지는 모습이 한 걸음씩 내딛는 발걸음과 닮아서","correct":true},{"t":"돌에 다리가 달려 있어서","mis":"K6-2-u6-X08"},{"t":"빗댄 표현을 많이 넣어야 좋은 시가 되어서","mis":"K6-2-u6-X03"},{"t":"돌과 사람은 아무 비슷한 점이 없어서","mis":"K6-2-u6-X10"}],"explanation":["빗댈 때에는 비슷한 점이 있어요.","물에 닿는 모습이 걸음과 닮았어요.","많이 넣으려고 빗댄 것이 아니에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#18','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',3,'mc','auto','도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":18,"concept":"K6-2-u6-C14","difficulty":3,"kind":"mc","stem":"도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쪽지 한 장이 내 것이 된 날","correct":true},{"t":"소풍 간 날 있었던 모든 일","mis":"K6-2-u6-X18"},{"t":"공원","mis":"K6-2-u6-X18"},{"t":"버스","mis":"K6-2-u6-X18"}],"explanation":["겪은 일 그대로의 제목은 마음이 흐려요.","버스와 공원은 인상 깊은 순간이 아니에요.","쪽지를 찾은 기쁨이 담기면 좋아요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#19','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',3,'mc','auto','「물수제비」의 넷째 연을 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X23','K6-2-u6-X20','K6-2-u6-X21']::text[],false,'{"seq":19,"concept":"K6-2-u6-C16","difficulty":3,"kind":"mc","stem":"「물수제비」의 넷째 연을 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아빠를 이긴 뿌듯함이 살아나게 조금 힘을 주어 또렷하게 읽고, 「강둑까지」에서 한 박자 쉬어 준다","correct":true},{"t":"가장 작은 목소리로 들리지 않게 읽는다","mis":"K6-2-u6-X23"},{"t":"앞 연과 똑같은 속도와 크기로 읽는다","mis":"K6-2-u6-X20"},{"t":"가장 큰 목소리로 소리치듯 읽는다","mis":"K6-2-u6-X21"}],"explanation":["넷째 연에는 뿌듯함이 담겨 있어요.","목소리는 그 마음을 따라가요.","들리게, 마음에 맞게 읽어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#20','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',3,'error','auto','지안이의 계획을 고칠 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":20,"concept":"K6-2-u6-C23","difficulty":3,"kind":"error","stem":"지안이의 계획을 고칠 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"로하 — 「로봇 말고 용이 내려오게 하면 더 자연스러워.」","correct":true,"mis_target":"K6-2-u6-X29"},{"t":"서진 — 「겨울에 베짱이가 노래로 개미들을 위로하고 개미가 먹이를 나누어 주게 하자.」","mis":"K6-2-u6-X29"},{"t":"하늬 — 「앞에서 연습한 노래가 뒤에서 쓰이게 이어 보자.」","mis":"K6-2-u6-X29"}],"explanation":["서진과 하늬는 앞이 뒤를 부르게 고쳤어요.","로봇을 용으로 바꾸어도 갑작스러워요.","로하는 이어짐을 보지 않았어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#21','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C32',3,'error','auto','실을 글을 쓰기 전에 정할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":21,"concept":"K6-2-u6-C32","difficulty":3,"kind":"error","stem":"실을 글을 쓰기 전에 정할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다온 — 「표지 색깔부터 정하면 글이 빨리 써져.」","correct":true,"mis_target":"K6-2-u6-X40"},{"t":"나래 — 「중심 사건부터 정하자.」","mis":"K6-2-u6-X40"},{"t":"시후 — 「사건이 이어지는 차례를 간단히 적어 두자.」","mis":"K6-2-u6-X40"}],"explanation":["나래와 시후는 바르게 말했어요.","표지 색은 글을 쓰기 전에 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#22','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',3,'ox','auto','이단 뛰기를 처음 성공한 경험에서 출발해, 주인공을 줄넘기 대회에 나간 다람쥐로 지어내 이야기를 써도 돼요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":22,"concept":"K6-2-u6-C25","difficulty":3,"kind":"ox","stem":"이단 뛰기를 처음 성공한 경험에서 출발해, 주인공을 줄넘기 대회에 나간 다람쥐로 지어내 이야기를 써도 돼요.","answer":"O","reason_options":[{"t":"경험을 바탕으로 쓴 이야기는 겪은 일에서 출발하되 인물 · 배경 · 사건을 지어내기 때문에","correct":true},{"t":"이야기는 겪은 일 그대로만 써야 하기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["일기는 사실만 적어요.","이야기는 지어내도 돼요.","겪어 본 것에서 출발하면 자세해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#23','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C28',4,'mc','auto','지안이의 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X30','K6-2-u6-X36']::text[],false,'{"seq":23,"concept":"K6-2-u6-C28","difficulty":4,"kind":"mc","stem":"지안이의 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전개 — 베짱이가 개미들을 위해 노래를 연습한다 / 절정 — 추운 겨울 개미 굴에 노래를 들려준다 / 마지막 — 개미들이 먹이를 나누고 함께 겨울을 난다 / 제목 — 겨울을 노래로 데우는 베짱이","correct":true},{"t":"전개 — 낮잠 / 절정 — 로봇이 먹이를 줌 / 마지막 — 행복해짐 / 제목 — 개미와 베짱이","mis":"K6-2-u6-X29"},{"t":"전개 — 연습 / 절정 — 갑자기 하늘을 남 / 마지막 — 왕이 됨 / 제목 — 하늘을 나는 베짱이","mis":"K6-2-u6-X30"},{"t":"바꿀 것을 성격 · 배경 · 사건 모두로 늘린다","mis":"K6-2-u6-X36"}],"explanation":["성격에 맞게 행동을 바꿔요.","앞이 뒤를 부르게 이어요.","바뀐 것이 드러나는 제목을 붙여요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#24','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C28',4,'essay','teacher','지안이의 바꾸기 계획에서 이어지지 않는 곳을 두 군데 찾아 까닭을 쓰고, 바꾼 성격이 살아나도록 전개 · 절정 · 마지막 · 제목을 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"지안이의 바꾸기 계획에서 이어지지 않는 곳을 두 군데 찾아 까닭을 쓰고, 바꾼 성격이 살아나도록 전개 · 절정 · 마지막 · 제목을 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 베짱이를 남을 위해 노래를 연습하는 성격으로 바꾸고도 전개에서 낮잠만 자게 해 성격과 행동이 어긋난다. 둘째, 절정에서 로봇이 갑자기 내려와 앞의 일과 이어지지 않는다. 고친 계획 — 전개: 베짱이는 여름 내내 개미들이 힘들 때 들을 노래를 연습한다. 절정: 추운 겨울, 지친 개미들이 굴 속에서 웅크리고 있을 때 베짱이가 찾아가 노래를 들려준다. 마지막: 기운을 얻은 개미들이 먹이를 나누고 모두 함께 겨울을 난다. 제목: 겨울을 노래로 데우는 베짱이.","scoring_points":["어긋난 곳 두 군데와 까닭을 썼는가","바꾼 성격에 맞게 행동을 고쳤는가","앞이 뒤를 부르게 잇고 바뀐 것이 드러나는 제목을 붙였는가"]},"explanation":["성격과 행동을 맞춰요.","갑작스러운 일을 빼요.","앞이 뒤를 부르게 이어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#25','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',4,'essay','teacher','내가 겪은 작은 일 하나를 골라, 그 경험을 시로 쓸 때와 그 경험을 바탕으로 이야기를 쓸 때 각각 어떻게 다르게 쓸지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C25","difficulty":4,"kind":"essay","stem":"내가 겪은 작은 일 하나를 골라, 그 경험을 시로 쓸 때와 그 경험을 바탕으로 이야기를 쓸 때 각각 어떻게 다르게 쓸지 설명하세요.","answer_guide":{"answer":"예: 겪은 일 — 짝과 우산 하나를 함께 쓰고 집에 온 일. 시로 쓸 때에는 어깨가 젖은 순간처럼 가장 인상 깊은 장면만 골라 짧게 쓰고, 장면이 바뀌는 곳에서 연을 나누며, 마음에 알맞으면 빗대거나 감각을 살린다. 이야기로 쓸 때에는 겪은 일에서 출발하되 인물 · 배경 · 사건을 지어낼 수 있다. 예를 들어 비가 그치지 않는 마을에 사는 두 친구로 인물과 배경을 바꾸고, 우산 하나를 나누어 쓰다 생긴 일이 앞뒤로 이어지게 발단부터 마지막까지 쓴다.","scoring_points":["겪은 작은 일을 하나 골랐는가","시로 쓸 때의 방법(고르기 · 연 · 표현)을 썼는가","이야기로 쓸 때 지어내고 이어지게 쓴다고 썼는가"]},"explanation":["작은 일도 글감이에요.","시는 고르고 짧게.","이야기는 지어내고 이어지게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#1','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C1',1,'mc','auto','「지우개 가루」를 쓴 사람이 경험을 시로 남겨 얻은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"「지우개 가루」를 쓴 사람이 경험을 시로 남겨 얻은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 번 틀리며 애쓴 마음을 오래 간직하게 되었다","correct":true},{"t":"글씨를 또박또박 쓰게 되었다","mis":"K6-2-u6-X01"},{"t":"시를 길게 늘이는 법을 알게 되었다","mis":"K6-2-u6-X01"},{"t":"지우개를 아껴 쓰게 되었다","mis":"K6-2-u6-X07"}],"explanation":["털어 낸 가루는 사라져요.","그런데 애쓴 마음은 시로 남았어요.","손끝이 알고 있다는 마음이에요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#2','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C3',1,'mc','auto','이 단원의 약속과 맞는 말은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 단원의 약속과 맞는 말은 어느 것인가요?","options":[{"t":"빗댄 표현은 마음에 알맞을 때 힘이 있다","correct":true},{"t":"빗댄 표현을 많이 넣을수록 좋은 시다","mis":"K6-2-u6-X03"},{"t":"어려운 말을 쓸수록 좋은 시다","mis":"K6-2-u6-X04"},{"t":"대단한 일을 겪어야 시가 된다","mis":"K6-2-u6-X02"}],"explanation":["많이 넣는다고 좋아지지 않아요.","어려운 말이 기준이 아니에요.","작은 일도 시가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#3','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C4',1,'ox','auto','인물 · 배경 · 사건은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직여요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"ox","stem":"인물 · 배경 · 사건은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직여요.","answer":"O","reason_options":[{"t":"셋이 모여 하나의 이야기를 이루기 때문에","correct":true},{"t":"셋은 서로 아무 상관이 없기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["성격이 바뀌면 하는 일이 바뀌어요.","배경이 바뀌면 할 수 있는 일이 바뀌어요.","셋은 함께 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#4','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C7',1,'mc','auto','「틀린 답이 / 눈처럼 쌓여 있다」에서 지우개 가루를 무엇에 빗대었나요?',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":4,"concept":"K6-2-u6-C7","difficulty":1,"kind":"mc","stem":"「틀린 답이 / 눈처럼 쌓여 있다」에서 지우개 가루를 무엇에 빗대었나요?","options":[{"t":"눈","correct":true},{"t":"공책","mis":"K6-2-u6-X10"},{"t":"손날","mis":"K6-2-u6-X10"},{"t":"틀린 답","mis":"K6-2-u6-X10"}],"explanation":["지우개 가루가 하얗게 쌓였어요.","그 모습이 눈과 닮았어요.","「처럼」으로 눈에 빗대었어요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#5','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C10',1,'mc','auto','시의 특성으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X14']::text[],false,'{"seq":5,"concept":"K6-2-u6-C10","difficulty":1,"kind":"mc","stem":"시의 특성으로 알맞은 것은 어느 것인가요?","options":[{"t":"생각이나 느낌을 짧은 글로 눌러 담는다","correct":true},{"t":"겪은 일을 빠짐없이 길게 적는다","mis":"K6-2-u6-X09"},{"t":"반드시 어려운 낱말을 쓴다","mis":"K6-2-u6-X04"},{"t":"연과 행을 나누지 않고 이어 쓴다","mis":"K6-2-u6-X14"}],"explanation":["빠짐없이 길게는 시의 특성이 아니에요.","어려운 낱말도 아니에요.","짧게 눌러 담는 것이 시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#6','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C13',1,'mc','auto','시를 쓸 때 생각그물에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17']::text[],false,'{"seq":6,"concept":"K6-2-u6-C13","difficulty":1,"kind":"mc","stem":"시를 쓸 때 생각그물에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 것만 골라 남기고 나머지는 버린다","correct":true},{"t":"모은 것을 하나도 빠짐없이 다 넣는다","mis":"K6-2-u6-X16"},{"t":"모은 것 가운데 가장 긴 것만 넣는다","mis":"K6-2-u6-X17"},{"t":"생각그물은 그리지 않는다","mis":"K6-2-u6-X16"}],"explanation":["다 넣으면 목록이 돼요.","길이가 기준이 아니에요.","인상 깊은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#7','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C18',1,'mc','auto','친구의 낭송을 들을 때 알맞은 모습은 어느 것인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":7,"concept":"K6-2-u6-C18","difficulty":1,"kind":"mc","stem":"친구의 낭송을 들을 때 알맞은 모습은 어느 것인가요?","options":[{"t":"시와 관련 있는 내 경험을 떠올리며 듣는다","correct":true},{"t":"틀린 글자를 찾아 적어 둔다","mis":"K6-2-u6-X24"},{"t":"옆 친구와 그때그때 이야기한다","mis":"K6-2-u6-X24"},{"t":"내 시를 속으로 읽어 본다","mis":"K6-2-u6-X24"}],"explanation":["낭송하는 사람을 바라봐요.","내 경험을 떠올리며 들어요.","끝난 뒤 잘한 점을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#8','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',1,'ox','auto','「운동화 끈을 단단히 매었다.」는 바르게 쓴 문장이에요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"ox","stem":"「운동화 끈을 단단히 매었다.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"끈을 묶는 것은 「매다」이기 때문에","correct":true},{"t":"어깨에 걸치는 것도 「매다」이기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["끈을 묶는 것은 매다예요.","어깨에 걸치는 것은 메다예요.","바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#9','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C5',2,'mc','auto','「물수제비」에서 말하는 이와 함께 돌을 던진 사람은 누구인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「물수제비」에서 말하는 이와 함께 돌을 던진 사람은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"선생님","mis":"K6-2-u6-X07"},{"t":"짝꿍","mis":"K6-2-u6-X07"},{"t":"동생","mis":"K6-2-u6-X07"}],"explanation":["넷째 연을 읽어요.","아빠 돌보다 한 걸음 더 갔어요.","아빠와 함께 던졌어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#10','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C10',2,'mc','auto','「물수제비」에 담긴 시의 특성으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X14','K6-2-u6-X12','K6-2-u6-X10']::text[],false,'{"seq":10,"concept":"K6-2-u6-C10","difficulty":2,"kind":"mc","stem":"「물수제비」에 담긴 시의 특성으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"겪은 일을 처음부터 끝까지 빠짐없이 적었다","correct":true},{"t":"장면이 바뀌는 곳에서 연을 나누었다","mis":"K6-2-u6-X14"},{"t":"들은 소리를 그대로 살렸다","mis":"K6-2-u6-X12"},{"t":"돌의 움직임을 다른 것에 빗대었다","mis":"K6-2-u6-X10"}],"explanation":["연을 나누고 소리를 살렸어요.","돌의 움직임을 빗대었어요.","빠짐없이 다 적지는 않았어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#11','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C14',2,'ox','auto','「소풍」이라는 제목은 도윤이의 마음이 잘 드러나는 제목이에요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":11,"concept":"K6-2-u6-C14","difficulty":2,"kind":"ox","stem":"「소풍」이라는 제목은 도윤이의 마음이 잘 드러나는 제목이에요.","answer":"X","reason_options":[{"t":"겪은 일 그대로의 제목이라 보물 쪽지를 찾은 기쁨이 드러나지 않기 때문에","correct":true},{"t":"제목은 짧을수록 마음이 잘 드러나기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["겪은 일 그대로의 제목도 쓸 수 있어요.","그런데 마음은 잘 드러나지 않아요.","인상 깊은 순간이 담기면 좋아요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#12','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C15',2,'mc','auto','시를 소리 내어 읽어 보며 고쳐 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 소리 내어 읽어 보며 고쳐 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸리는 줄을 찾아 고치거나 지우기 위해서","correct":true},{"t":"글씨를 예쁘게 다시 쓰기 위해서","mis":"K6-2-u6-X19"},{"t":"빗댄 표현의 개수를 세기 위해서","mis":"K6-2-u6-X19"},{"t":"친구 시보다 길게 늘리기 위해서","mis":"K6-2-u6-X19"}],"explanation":["귀로 들으면 걸리는 곳이 보여요.","걸리는 줄을 고치거나 지워요.","글씨나 개수는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#13','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C17',2,'mc','auto','서하의 계획에서 영상을 고칠 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":13,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"서하의 계획에서 영상을 고칠 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"강물 위를 튀는 돌처럼 시의 장면을 떠올리게 하는 그림을 조용히 보여 준다","correct":true},{"t":"더 반짝이는 꾸밈으로 바꾼다","mis":"K6-2-u6-X22"},{"t":"영상을 더 빠르게 바꾼다","mis":"K6-2-u6-X22"},{"t":"영상만 보여 주고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["화려하면 낭송의 흐름을 방해해요.","장면을 떠올리는 데 도움이 될 만큼만 써요.","낭송을 대신하지 않아요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#14','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C24',2,'mc','auto','잘 바꾼 이야기를 가늠하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X32']::text[],false,'{"seq":14,"concept":"K6-2-u6-C24","difficulty":2,"kind":"mc","stem":"잘 바꾼 이야기를 가늠하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 것에서 다음 일이 자연스럽게 나오는가","correct":true},{"t":"얼마나 놀라운 일이 일어나는가","mis":"K6-2-u6-X30"},{"t":"얼마나 많은 곳을 바꾸었는가","mis":"K6-2-u6-X36"},{"t":"원래 이야기와 얼마나 다르게 길어졌는가","mis":"K6-2-u6-X32"}],"explanation":["놀라움이 기준이 아니에요.","많이 바꾸는 것도 아니에요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#15','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C29',2,'mc','auto','지안이의 계획에서 제목을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X30']::text[],false,'{"seq":15,"concept":"K6-2-u6-C29","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 제목을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겨울을 노래로 데우는 베짱이","correct":true},{"t":"개미와 베짱이","mis":"K6-2-u6-X18"},{"t":"로봇 대소동","mis":"K6-2-u6-X30"},{"t":"여름","mis":"K6-2-u6-X18"}],"explanation":["원래 제목은 바뀐 것을 드러내지 못해요.","로봇은 이어지지 않는 사건이에요.","바뀐 성격이 드러나게 붙여요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#16','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',2,'mc','auto','하람이의 말을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-2-u6-X42','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C33","difficulty":2,"kind":"mc","stem":"하람이의 말을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「다 만들면 서로의 글에서 잘한 점부터 말해 주자.」","correct":true},{"t":"「다 만들면 가장 못한 사람을 뽑자.」","mis":"K6-2-u6-X42"},{"t":"「다 만들면 표지가 가장 화려한 모둠을 뽑자.」","mis":"K6-2-u6-X41"},{"t":"「다 만들면 아무 말도 하지 말자.」","mis":"K6-2-u6-X42"}],"explanation":["잘한 점에 초점을 맞춰요.","글에서 잘한 점을 찾아요.","나누는 즐거움이 목적이에요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#17','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C3',3,'ox','auto','「물수제비」는 빗댄 표현이 몇 개 들어 있느냐에 따라 좋은 시인지가 정해져요.',ARRAY['K6-2-u6-X03']::text[],false,'{"seq":17,"concept":"K6-2-u6-C3","difficulty":3,"kind":"ox","stem":"「물수제비」는 빗댄 표현이 몇 개 들어 있느냐에 따라 좋은 시인지가 정해져요.","answer":"X","reason_options":[{"t":"표현은 개수가 아니라 그 마음에 알맞은지로 가늠하기 때문에","correct":true},{"t":"빗댄 표현이 많을수록 좋은 시가 되기 때문에","mis":"K6-2-u6-X03"}],"mis":"K6-2-u6-X03","explanation":["개수를 세지 않아요.","으쓱한 마음이 잘 전해지는지 봐요.","알맞음이 기준이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#18','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C6',3,'ox','auto','도윤이가 「소풍」을 고칠 때 「너무 좋았다」를 그때 본 것이나 만진 것으로 바꾸어 쓰면 더 생생해져요.',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":18,"concept":"K6-2-u6-C6","difficulty":3,"kind":"ox","stem":"도윤이가 「소풍」을 고칠 때 「너무 좋았다」를 그때 본 것이나 만진 것으로 바꾸어 쓰면 더 생생해져요.","answer":"O","reason_options":[{"t":"본 것 · 들은 것 · 만진 것을 그대로 살리면 장면이 떠오르기 때문에","correct":true},{"t":"마음을 나타내는 말은 시에 쓰면 안 되기 때문에","mis":"K6-2-u6-X12"}],"mis":"K6-2-u6-X12","explanation":["「너무 좋았다」만으로는 장면이 떠오르지 않아요.","쪽지를 펼친 손끝을 살려 봐요.","감각을 살리면 생생해져요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#19','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C17',3,'ox','auto','서하가 배경 음악을 「물 흐르는 소리」로 바꾸고 낭송보다 작게 틀면 낭송을 도울 수 있어요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C17","difficulty":3,"kind":"ox","stem":"서하가 배경 음악을 「물 흐르는 소리」로 바꾸고 낭송보다 작게 틀면 낭송을 도울 수 있어요.","answer":"O","reason_options":[{"t":"시의 장면과 어울리고 목소리를 덮지 않기 때문에","correct":true},{"t":"음악은 무엇이든 틀기만 하면 낭송을 돕기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["강물 장면과 어울려요.","목소리보다 작아요.","돕는 만큼만 써요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#20','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C27',3,'ox','auto','지안이의 계획에서 인물의 성격을 정리할 때, 베짱이가 「남을 위해 연습하는 성격」이라는 것은 베짱이가 한 일에서 드러나야 해요.',ARRAY['K6-2-u6-X33']::text[],false,'{"seq":20,"concept":"K6-2-u6-C27","difficulty":3,"kind":"ox","stem":"지안이의 계획에서 인물의 성격을 정리할 때, 베짱이가 「남을 위해 연습하는 성격」이라는 것은 베짱이가 한 일에서 드러나야 해요.","answer":"O","reason_options":[{"t":"인물의 성격은 그 인물이 한 말과 행동에서 드러나기 때문에","correct":true},{"t":"성격은 바꿀 것 칸에 적기만 하면 되기 때문에","mis":"K6-2-u6-X33"}],"mis":"K6-2-u6-X33","explanation":["성격은 적어 두는 것으로 끝나지 않아요.","하는 일에서 드러나야 해요.","그래야 읽는 사람이 알아요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#21','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',3,'ox','auto','함께 책을 만들 때 누가 무엇을 언제까지 맡을지 정하지 않아도 저절로 잘 만들어져요.',ARRAY['K6-2-u6-X42']::text[],false,'{"seq":21,"concept":"K6-2-u6-C33","difficulty":3,"kind":"ox","stem":"함께 책을 만들 때 누가 무엇을 언제까지 맡을지 정하지 않아도 저절로 잘 만들어져요.","answer":"X","reason_options":[{"t":"맡을 일과 마칠 때를 정해야 함께 만드는 일이 이어지기 때문에","correct":true},{"t":"함께 만들면 정하지 않아도 모두 알아서 하기 때문에","mis":"K6-2-u6-X42"}],"mis":"K6-2-u6-X42","explanation":["누구와 · 무엇을 · 언제까지 정해요.","정하지 않으면 빠지는 일이 생겨요.","다 만든 뒤 잘한 점부터 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#22','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C26',3,'mc','auto','「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":22,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"속이지 않고 사정을 털어놓으면 함께 길을 찾을 수 있다","correct":true},{"t":"꾀가 많은 사람이 언제나 이긴다","mis":"K6-2-u6-X32"},{"t":"용왕의 말은 무조건 따라야 한다","mis":"K6-2-u6-X32"},{"t":"바닷속은 위험한 곳이다","mis":"K6-2-u6-X32"}],"explanation":["원래는 토끼가 꾀로 살아남는 이야기예요.","바꾸자 자라가 사실대로 말하고 함께 약을 찾아요.","정직하게 털어놓는 뜻이 새로 생겨요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#23','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',4,'mc','auto','학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":23,"concept":"K6-2-u6-C33","difficulty":4,"kind":"mc","stem":"학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래의 말처럼 중심 사건과 인물부터 정하고, 독자를 먼저 정해 형태를 고르며, 꾸미기는 이야기 뒤에, 나눌 때는 잘한 점부터 해야 한다","correct":true},{"t":"다온의 말처럼 표지를 먼저 꾸미면 된다","mis":"K6-2-u6-X41"},{"t":"루아의 말처럼 화면으로 보는 책이 언제나 정답이다","mis":"K6-2-u6-X38"},{"t":"시후의 말처럼 독자는 나중에 정해도 된다","mis":"K6-2-u6-X39"}],"explanation":["나래의 말이 알맞아요.","독자부터 정해요.","이야기가 먼저, 잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#24','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C31',4,'essay','teacher','학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.","answer_guide":{"answer":"예: 첫째, 다온이가 표지부터 사흘 동안 꾸미자고 했는데, 꾸미기가 이야기를 덮으면 안 되므로 이야기를 먼저 완성해야 한다. 둘째, 루아가 화면으로 보는 책이 제일 좋다고 했는데, 형태에는 등수가 없고 독자에 따라 달라진다. 셋째, 시후가 독자를 나중에 정하자고 했는데, 독자가 정해져야 형태가 정해진다. 바른 차례 — 독자 정하기 → 독자에게 맞는 형태 고르기 → 중심 사건 · 인물 · 때와 곳 · 차례 정하고 글 쓰기 → 누가 무엇을 언제까지 맡을지 나누어 만들기 → 꾸미기는 돕는 만큼 → 다 만든 뒤 잘한 점부터 나누기.","scoring_points":["알맞지 않은 말 세 가지와 까닭을 썼는가","독자를 먼저 정하고 형태를 고르는 차례를 썼는가","이야기 먼저 · 꾸미기는 돕는 만큼 · 잘한 점부터를 썼는가"]},"explanation":["독자부터 정해요.","이야기가 먼저예요.","잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#25','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',4,'essay','teacher','「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.","answer_guide":{"answer":"예: 아침에 운동화 끈을 단단히 매고, 무거운 가방을 어깨에 메고 학교까지 뛰어갔다. 「매다」는 끈이나 줄을 묶을 때 쓰므로 운동화 끈 자리에 썼고, 「메다」는 어깨에 걸쳐 질 때 쓰므로 가방 자리에 썼다. 두 낱말은 소리가 같지만 뜻이 달라 앞뒤 문장을 보고 골라 써야 한다.","scoring_points":["두 낱말을 모두 넣어 겪은 일을 썼는가","각 낱말을 뜻에 맞는 자리에 썼는가","가려 쓴 까닭을 뜻으로 설명했는가"]},"explanation":["겪은 일 가운데 떠올려요.","뜻에 맞는 자리에 써요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
